window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["PRO"]={"book":"PRO","editions":{"fin-biblia1776":[[1,1,"Salomon, Davidin pojan, Israelin kuninkaan sananlaskut;","Salomon, Davidin pojan, Israelin kuninkaan sananlaskut;"],[1,2,"Oppia viisautta ja kuritusta, ymmärtää tiedon puhetta,","Oppia viisautta ja kuritusta, ymmärtää tiedon puhetta,"],[1,3,"Vastaanottaa ymmärryksen neuvoa, vanhurskautta, oikeutta ja siveyttä;","Vastaanottaa ymmärryksen neuvoa, vanhurskautta, oikeutta ja siveyttä;"],[1,4,"Että tyhmät viisaaksi tulisivat ja nuorukaiset taidon ja ymmärryksen saisivat.","Että tyhmät viisaaksi tulisivat ja nuorukaiset taidon ja ymmärryksen saisivat."],[1,5,"Joka viisas on, se kuulkaan, että jän viisaammaksi tulis; ja joka toimellinen on, se ottakoon neuvon,","Joka viisas on, se kuulkaan, että jän viisaammaksi tulis; ja joka toimellinen on, se ottakoon neuvon,"],[1,6,"Että hän ymmärtäis sananlaskut ja niiden selityksen, viisasten opin ja heidän tapauksensa.","Että hän ymmärtäis sananlaskut ja niiden selityksen, viisasten opin ja heidän tapauksensa."],[1,7,"Herran pelko on viisauden alku; tyhmät hylkäävät viisauden ja opin.","Herran pelko on viisauden alku; tyhmät hylkäävät viisauden ja opin."],[1,8,"Poikani kuule isäs kuritusta, ja älä hylkää äitis käskyä!","Poikani kuule isäs kuritusta, ja älä hylkää äitis käskyä!"],[1,9,"Sillä se on sinun sinun pääs päällä otollinen kaunistus, ja käädyt kaulassas.","Sillä se on sinun sinun pääs päällä otollinen kaunistus, ja käädyt kaulassas."],[1,10,"Poikani! jos pahanjuoniset sinua sinua houkuttelevat, niin älä heihin suostu.","Poikani! jos pahanjuoniset sinua sinua houkuttelevat, niin älä heihin suostu."],[1,11,"Jos he sanovat: käy meidän kanssamme: me väijymme verta, ja viritämme pauloja nuhteettoman eteen ilman syytä;","Jos he sanovat: käy meidän kanssamme: me väijymme verta, ja viritämme pauloja nuhteettoman eteen ilman syytä;"],[1,12,"Me nielemme hänen, niinkuin helvetti elävältä, ja hurskaan niinkuin hautaan pudotamme;","Me nielemme hänen, niinkuin helvetti elävältä, ja hurskaan niinkuin hautaan pudotamme;"],[1,13,"Me löydämme kaikellaista kallista tavaraa, ja täytämme huoneemme saaliista;","Me löydämme kaikellaista kallista tavaraa, ja täytämme huoneemme saaliista;"],[1,14,"Koettele meidän kanssamme: meillä kaikilla pitää yksi kukkaro oleman:","Koettele meidän kanssamme: meillä kaikilla pitää yksi kukkaro oleman:"],[1,15,"Poikani! älä vaella heidän kanssansa: estä jalkas heidän retkiltänsä.","Poikani! älä vaella heidän kanssansa: estä jalkas heidän retkiltänsä."],[1,16,"Sillä heidän jalkansa juoksevat pahuuteen, ja he kiiruhtavat verta vuodattamaan.","Sillä heidän jalkansa juoksevat pahuuteen, ja he kiiruhtavat verta vuodattamaan."],[1,17,"Sillä turhaan verkot viritetään lintuin silmäin edessä.","Sillä turhaan verkot viritetään lintuin silmäin edessä."],[1,18,"Itse he myös väijyvät toinen toisensa verta, ja petoksella seisovat toinen toisensa hengen perään.","Itse he myös väijyvät toinen toisensa verta, ja petoksella seisovat toinen toisensa hengen perään."],[1,19,"Niin kaikki ahneet tekevät, ja ahneus on isännillensä surmaksi.","Niin kaikki ahneet tekevät, ja ahneus on isännillensä surmaksi."],[1,20,"Viisaus ulkona valittaa, ja kadulla äänensä ilmoittaa.","Viisaus ulkona valittaa, ja kadulla äänensä ilmoittaa."],[1,21,"Hän huutaa kansan edessä portissa, ja tuottaa sanansa edes kaupungissa, sanoen:","Hän huutaa kansan edessä portissa, ja tuottaa sanansa edes kaupungissa, sanoen:"],[1,22,"Kuinka kauvan te tyhmät tahdotte olla taitamattomat, ja pilkkakirveet rakastaa naurua? ja te hullut vihata opetusta?","Kuinka kauvan te tyhmät tahdotte olla taitamattomat, ja pilkkakirveet rakastaa naurua? ja te hullut vihata opetusta?"],[1,23,"Kääntäkäät itsenne minun kuritukseni puoleen: katso, ja minä tuon teille henkeni edes, ja ilmoitan teille sanani;","Kääntäkäät itsenne minun kuritukseni puoleen: katso, ja minä tuon teille henkeni edes, ja ilmoitan teille sanani;"],[1,24,"Että minä kutsuin teitä, ja te estelitte teitänne: minä kokotin käteni, ja ei yksikään ottanut siitä vaaria,","Että minä kutsuin teitä, ja te estelitte teitänne: minä kokotin käteni, ja ei yksikään ottanut siitä vaaria,"],[1,25,"Te hylkäsitte kaiken neuvoni, ja ette tahtoneet kuritustani;","Te hylkäsitte kaiken neuvoni, ja ette tahtoneet kuritustani;"],[1,26,"Niin minä myös nauran teidän vahinkoanne, ja pilkkaan teitä, kuin teidän päällenne tulee se, jota te pelkäätte,","Niin minä myös nauran teidän vahinkoanne, ja pilkkaan teitä, kuin teidän päällenne tulee se, jota te pelkäätte,"],[1,27,"Kuin se tulee, jota te pelkäätte, niinkuin rajuilma, ja tuska niinkuin tuulispää; kuin teidän päällenne tulee ahdistus ja vaiva.","Kuin se tulee, jota te pelkäätte, niinkuin rajuilma, ja tuska niinkuin tuulispää; kuin teidän päällenne tulee ahdistus ja vaiva."],[1,28,"Silloin he minua avuksensa huutavat, ja en minä kuule heitä: varhain he etsivät minua, ja ei löydä minua.","Silloin he minua avuksensa huutavat, ja en minä kuule heitä: varhain he etsivät minua, ja ei löydä minua."],[1,29,"Että he vihasivat opetusta, ja ei ottaneet vastaan Herran pelkoa,","Että he vihasivat opetusta, ja ei ottaneet vastaan Herran pelkoa,"],[1,30,"Eikä tyytyneet minun neuvooni, mutta laittivat kaiken kuritukseni;","Eikä tyytyneet minun neuvooni, mutta laittivat kaiken kuritukseni;"],[1,31,"Niin pitää heidän syömän tiensä hedelmästä, ja neuvostansa ravituksi tuleman.","Niin pitää heidän syömän tiensä hedelmästä, ja neuvostansa ravituksi tuleman."],[1,32,"Sillä tyhmäin himo tappaa heidät, ja hulluin onni kadottaa heidät.","Sillä tyhmäin himo tappaa heidät, ja hulluin onni kadottaa heidät."],[1,33,"Mutta joka minua kuulee, hän asuu turvallisesti, ja ei mitään pahaa pelkää.","Mutta joka minua kuulee, hän asuu turvallisesti, ja ei mitään pahaa pelkää."],[2,1,"Poikani, jos otat minun puheeni, ja käskyni kätket;","Poikani, jos otat minun puheeni, ja käskyni kätket;"],[2,2,"Niin anna korvas kuulla viisautta, ja taivuta sydämes ymmärrykseen.","Niin anna korvas kuulla viisautta, ja taivuta sydämes ymmärrykseen."],[2,3,"Sillä jos ymmärrystä ahkerasti halajat, ja rukoilet taitoa;","Sillä jos ymmärrystä ahkerasti halajat, ja rukoilet taitoa;"],[2,4,"Jos sitä etsit niinkuin hopiaa, ja pyörit sen perään niinkuin tavaran;","Jos sitä etsit niinkuin hopiaa, ja pyörit sen perään niinkuin tavaran;"],[2,5,"Niin sinä ymmärrät Herran pelvon, ja Herran tunnon löydät.","Niin sinä ymmärrät Herran pelvon, ja Herran tunnon löydät."],[2,6,"Sillä Herra antaa viisauden, ja hänen suustansa tulee taito ja ymmärrys.","Sillä Herra antaa viisauden, ja hänen suustansa tulee taito ja ymmärrys."],[2,7,"Hän antaa toimellisten hyvin käydä, ja suojelee niitä, jotka viattomasti vaeltavat,","Hän antaa toimellisten hyvin käydä, ja suojelee niitä, jotka viattomasti vaeltavat,"],[2,8,"Varjelee hurskaat, ja holhoo pyhäinsä retket.","Varjelee hurskaat, ja holhoo pyhäinsä retket."],[2,9,"Silloin sinä ymmärrät vanhurskauden ja tuomion, oikeuden ja kaiken hyvän tien.","Silloin sinä ymmärrät vanhurskauden ja tuomion, oikeuden ja kaiken hyvän tien."],[2,10,"Jos viisaus sydämees tulee, ja taito on sinulle kelvollinen,","Jos viisaus sydämees tulee, ja taito on sinulle kelvollinen,"],[2,11,"Niin hyvä neuvo sinua varjelee, ja ymmärrys kätkee sinun,","Niin hyvä neuvo sinua varjelee, ja ymmärrys kätkee sinun,"],[2,12,"Tempaamaan sinun pois pahalta tieltä, ja niiden seurasta, jotka toimettomia puhuvat,","Tempaamaan sinun pois pahalta tieltä, ja niiden seurasta, jotka toimettomia puhuvat,"],[2,13,"Ja hylkäävät oikian tien, ja vaeltavat pimeitä retkiä;","Ja hylkäävät oikian tien, ja vaeltavat pimeitä retkiä;"],[2,14,"Jotka iloitsevat pahoista töistänsä, ja riemuitsevat pahoista menoistansa;","Jotka iloitsevat pahoista töistänsä, ja riemuitsevat pahoista menoistansa;"],[2,15,"Joiden tiet ovat vastahakoiset, ja retket väärär ja häpiälliset:","Joiden tiet ovat vastahakoiset, ja retket väärär ja häpiälliset:"],[2,16,"Ettet sinä ryhtyisi vieraaseen vaimoon, joka ei sinun ole, joka suloisilla sanoilla puhuttelee,","Ettet sinä ryhtyisi vieraaseen vaimoon, joka ei sinun ole, joka suloisilla sanoilla puhuttelee,"],[2,17,"Ja hylkää nuoruutensa johdattajan, ja unohtaa Jumalansa liiton.","Ja hylkää nuoruutensa johdattajan, ja unohtaa Jumalansa liiton."],[2,18,"Sillä hänen huoneensa kallistuu kuolemaan, ja hänen askeleensa kadotettuin tykö.","Sillä hänen huoneensa kallistuu kuolemaan, ja hänen askeleensa kadotettuin tykö."],[2,19,"Jokainen joka menee hänen tykönsä, ei palaja, eikä elämän tielle joudu;","Jokainen joka menee hänen tykönsä, ei palaja, eikä elämän tielle joudu;"],[2,20,"Ettäs vaeltasit hyvää tietä, ja pitäisit hurskasten tiet.","Ettäs vaeltasit hyvää tietä, ja pitäisit hurskasten tiet."],[2,21,"Sillä vanhurskaat asuvat maassa, ja vakaat siinä pysyvät;","Sillä vanhurskaat asuvat maassa, ja vakaat siinä pysyvät;"],[2,22,"Mutta jumalattomat hukutetaan maasta, ja ylönkatsojat siitä teloitetaan.","Mutta jumalattomat hukutetaan maasta, ja ylönkatsojat siitä teloitetaan."],[3,1,"Poikani, älä unohda minun lakiani, mutta sinun sydämes pitäköön käskyni.","Poikani, älä unohda minun lakiani, mutta sinun sydämes pitäköön käskyni."],[3,2,"Sillä ne saatavat sinulle pitkän ijän, hyvät vuodet ja rauhan.","Sillä ne saatavat sinulle pitkän ijän, hyvät vuodet ja rauhan."],[3,3,"Armo ja totuus ei sinua pidä hylkäämän: ripusta ne kaulaas, ja kirjoita sydämes tauluun,","Armo ja totuus ei sinua pidä hylkäämän: ripusta ne kaulaas, ja kirjoita sydämes tauluun,"],[3,4,"Niin sinä löydät armon ja hyvän toimen, Jumalan ja ihmisten edessä.","Niin sinä löydät armon ja hyvän toimen, Jumalan ja ihmisten edessä."],[3,5,"Luota Herraan kaikesta sydämestäs, ja älä luota ymmärryksees;","Luota Herraan kaikesta sydämestäs, ja älä luota ymmärryksees;"],[3,6,"Mutta ajattele häntä kaikissa teissäs, niin hän sinua oikein johdattaa.","Mutta ajattele häntä kaikissa teissäs, niin hän sinua oikein johdattaa."],[3,7,"Älä ole viisas mielestäs, vaan pelkääerraa, ja vältä pahaa.","Älä ole viisas mielestäs, vaan pelkääerraa, ja vältä pahaa."],[3,8,"Sillä se on navalles terveellinen, ja virvoittaa luus.","Sillä se on navalles terveellinen, ja virvoittaa luus."],[3,9,"Kunnioita Herraa tavarastas, ja kaikista vuoden tulos esikoisista;","Kunnioita Herraa tavarastas, ja kaikista vuoden tulos esikoisista;"],[3,10,"Niin sinun riihes täytetään kyllyydellä, ja sinun viinakuurnas vuotaa ylitse.","Niin sinun riihes täytetään kyllyydellä, ja sinun viinakuurnas vuotaa ylitse."],[3,11,"Poikani, älä Herran kuritusta hylkää, ja älä ole kärsimätön, kuin hän sinua rankaisee,","Poikani, älä Herran kuritusta hylkää, ja älä ole kärsimätön, kuin hän sinua rankaisee,"],[3,12,"Sillä, jota Herra rakastaa, sitä hän rankaisee, ja on hänelle otollinen niinkuin poika isällensä.","Sillä, jota Herra rakastaa, sitä hän rankaisee, ja on hänelle otollinen niinkuin poika isällensä."],[3,13,"Autuas on se ihminen, joka viisauden löytää, ja se ihminen, joka ymmärryksen käsittää.","Autuas on se ihminen, joka viisauden löytää, ja se ihminen, joka ymmärryksen käsittää."],[3,14,"Sillä parempi on kaupita häntä kuin kaupita hopiaa, ja hänen hedelmänsä on parempi kuin kulta.","Sillä parempi on kaupita häntä kuin kaupita hopiaa, ja hänen hedelmänsä on parempi kuin kulta."],[3,15,"Hän on kalliimpi kuin päärlyt, eikä hänen vertaansa mitään toivottaa taideta.","Hän on kalliimpi kuin päärlyt, eikä hänen vertaansa mitään toivottaa taideta."],[3,16,"Pitkä ikä on hänen oikialla kädellänsä, rikkaus ja kunnia hänen vasemmallansa.","Pitkä ikä on hänen oikialla kädellänsä, rikkaus ja kunnia hänen vasemmallansa."],[3,17,"Hänen tiensä ovat iloiset, ja kaikki hänen askeleensa rauha.","Hänen tiensä ovat iloiset, ja kaikki hänen askeleensa rauha."],[3,18,"Hän on elämän puu niille, jotka häneen rupeevat; ja autuaat ovat ne, jotka hänen pitävät.","Hän on elämän puu niille, jotka häneen rupeevat; ja autuaat ovat ne, jotka hänen pitävät."],[3,19,"Sillä Herra on viisaudella maan perustanut, ja taivaat toimella valmistanut.","Sillä Herra on viisaudella maan perustanut, ja taivaat toimella valmistanut."],[3,20,"Hänen viisaudessansa ovat syvyydet eroitetut, ja pivet pisaroivat kasteen.","Hänen viisaudessansa ovat syvyydet eroitetut, ja pivet pisaroivat kasteen."],[3,21,"Poikani, älä salli näitä silmistäs tulla pois, niin sinä tulet onnelliseksi ja viisaaksi.","Poikani, älä salli näitä silmistäs tulla pois, niin sinä tulet onnelliseksi ja viisaaksi."],[3,22,"Se on sinun sielus elämä; ja sinun suus on otollinen.","Se on sinun sielus elämä; ja sinun suus on otollinen."],[3,23,"Silloin sinä murheetoinna vaellat teissäs, ettet jalkaas loukkaa.","Silloin sinä murheetoinna vaellat teissäs, ettet jalkaas loukkaa."],[3,24,"Et sinä pelkää maata pantuas, mutta makaat; ja sinun unes on sinulle makia,","Et sinä pelkää maata pantuas, mutta makaat; ja sinun unes on sinulle makia,"],[3,25,"Ettei sinun tarvitse peljätä äkillistä hirmua, eikä jumalattomain hävitystä, kuin se tulee.","Ettei sinun tarvitse peljätä äkillistä hirmua, eikä jumalattomain hävitystä, kuin se tulee."],[3,26,"Sillä Herra on sinun lohdutukses; hän varjelee sinun jalkas, ettei sitä saavuteta.","Sillä Herra on sinun lohdutukses; hän varjelee sinun jalkas, ettei sitä saavuteta."],[3,27,"Älä estele tarvitsevalle hyvää tehdä, jos sinulla on varaa, ettäs sen tehdä taidat.","Älä estele tarvitsevalle hyvää tehdä, jos sinulla on varaa, ettäs sen tehdä taidat."],[3,28,"Älä sano ystävälle: mene ja tule jälleen, huomenna minä sinulle annan; koska sinulla on.","Älä sano ystävälle: mene ja tule jälleen, huomenna minä sinulle annan; koska sinulla on."],[3,29,"Älä pyydä sinun ystäväs vahinkoa, joka hyvässä toivossa asuu sinun tykönäs.","Älä pyydä sinun ystäväs vahinkoa, joka hyvässä toivossa asuu sinun tykönäs."],[3,30,"Älä kenenkään kanssa toru ilman syytä, jos hän ei mitään pahaa sinulle tehnyt ole.","Älä kenenkään kanssa toru ilman syytä, jos hän ei mitään pahaa sinulle tehnyt ole."],[3,31,"Älä kiivoittele väärää miestä, älä noudata hänen retkiänsä.","Älä kiivoittele väärää miestä, älä noudata hänen retkiänsä."],[3,32,"Sillä pahanilkiset ovat Herralle kauhistus; mutta hänen salaisuutensa on hurskasten tykönä.","Sillä pahanilkiset ovat Herralle kauhistus; mutta hänen salaisuutensa on hurskasten tykönä."],[3,33,"Jumalattoman huoneessa on Herran kirous; muttavanhurskaan maja siunataan.","Jumalattoman huoneessa on Herran kirous; muttavanhurskaan maja siunataan."],[3,34,"Hän pilkkaa pilkkaajia; mutta nöyrille hän antaa armon.","Hän pilkkaa pilkkaajia; mutta nöyrille hän antaa armon."],[3,35,"Viisaat kunnian perivät, mutta tyhmät häpiän saavat.","Viisaat kunnian perivät, mutta tyhmät häpiän saavat."],[4,1,"Kuulkaat, lapseni, isänne kuritusta, ja ottakaa vaari, oppiaksenne ja viisaammaksi tullaksenne.","Kuulkaat, lapseni, isänne kuritusta, ja ottakaa vaari, oppiaksenne ja viisaammaksi tullaksenne."],[4,2,"Sillä minä annan teille hyvän opetuksen; älkööt hyljätkö minun lakiani.","Sillä minä annan teille hyvän opetuksen; älkööt hyljätkö minun lakiani."],[4,3,"Sillä minä olin isäni poika, hoikka ja ainoa äidilläni.","Sillä minä olin isäni poika, hoikka ja ainoa äidilläni."],[4,4,"Ja hän opetti minua, ja sanoi minulle; anna sydämes ottaa minun sanani vastaan: pidä minun käskyni, niin sinä elää saat.","Ja hän opetti minua, ja sanoi minulle; anna sydämes ottaa minun sanani vastaan: pidä minun käskyni, niin sinä elää saat."],[4,5,"Osta viisaus, osat ymmärrys: älä unohda, älä myös poikkee minun puheestani.","Osta viisaus, osat ymmärrys: älä unohda, älä myös poikkee minun puheestani."],[4,6,"Älä häntä hylkää, niin hän sinut kätkee: rakasta häntä, niin hän sinua varjelee.","Älä häntä hylkää, niin hän sinut kätkee: rakasta häntä, niin hän sinua varjelee."],[4,7,"Sillä viisauden alku on, ostaa viisautta, ja kaikella saadullas ostaa taitoa.","Sillä viisauden alku on, ostaa viisautta, ja kaikella saadullas ostaa taitoa."],[4,8,"Pidä häntä korkiassa kunniassa, niin hän sinua korottaa, ja saattaa kunniaan, jos sinä häntä rakastat.","Pidä häntä korkiassa kunniassa, niin hän sinua korottaa, ja saattaa kunniaan, jos sinä häntä rakastat."],[4,9,"Hän sinun pääs jalosti kaunistaa, ja kunnioittaa sinua ihanalla kruunulla.","Hän sinun pääs jalosti kaunistaa, ja kunnioittaa sinua ihanalla kruunulla."],[4,10,"Kuule siis, poikani, ja ota minun puheeni, niin ikäs vuotta on monta.","Kuule siis, poikani, ja ota minun puheeni, niin ikäs vuotta on monta."],[4,11,"Minä johdatan sinua viisauden tielle, ja saatan sinua käymään oikialla retkellä,","Minä johdatan sinua viisauden tielle, ja saatan sinua käymään oikialla retkellä,"],[4,12,"Niin että koskas vaellat, ei sinun käymises ole ahdas; ja koskas juokset, niin et sinä loukkaa sinuas.","Niin että koskas vaellat, ei sinun käymises ole ahdas; ja koskas juokset, niin et sinä loukkaa sinuas."],[4,13,"Pidä kuritus, älä hylkää häntä: kätke häntä; sillä hän on sinun elämäs.","Pidä kuritus, älä hylkää häntä: kätke häntä; sillä hän on sinun elämäs."],[4,14,"Älä mene jumalattomain askelille, ja älä astu pahain tielle;","Älä mene jumalattomain askelille, ja älä astu pahain tielle;"],[4,15,"Jätä se pois, ja älä käy siinä; karta sitä, ja mene ohitse.","Jätä se pois, ja älä käy siinä; karta sitä, ja mene ohitse."],[4,16,"Sillä ei he makaa, jollei he ole pahoin tehneet, eikä lepää, jollei he ole vahinkoa tehneet.","Sillä ei he makaa, jollei he ole pahoin tehneet, eikä lepää, jollei he ole vahinkoa tehneet."],[4,17,"Sillä he syövät jumalattomuuden leipää, ja juovat vääryyden viinaa.","Sillä he syövät jumalattomuuden leipää, ja juovat vääryyden viinaa."],[4,18,"Mutta vanhurskasten retki paistaa niinkuin valkeus, käy edes, ja valistaa hamaan isoon päivään asti.","Mutta vanhurskasten retki paistaa niinkuin valkeus, käy edes, ja valistaa hamaan isoon päivään asti."],[4,19,"Mutta jumalattomain tie on niinkuin pimeys; ja ei he tiedä, kussa he lankeevat.","Mutta jumalattomain tie on niinkuin pimeys; ja ei he tiedä, kussa he lankeevat."],[4,20,"Poikani, ota vaari sanoistani, ja kallista korvas puheisiini.","Poikani, ota vaari sanoistani, ja kallista korvas puheisiini."],[4,21,"Älä niiden anna tulla pois silmistäs: pidä ne sydämessäs.","Älä niiden anna tulla pois silmistäs: pidä ne sydämessäs."],[4,22,"Sillä ne ovat niiden elämä, jotka niitä ovat löytäneet, ja ovat terveelliset koko heidän ruumiillensa.","Sillä ne ovat niiden elämä, jotka niitä ovat löytäneet, ja ovat terveelliset koko heidän ruumiillensa."],[4,23,"Varjele sydämes kaikella ahkeruudella: sillä siitä elämä tulee.","Varjele sydämes kaikella ahkeruudella: sillä siitä elämä tulee."],[4,24,"Pane pois paha suu, ja väärät huulet anna olla sinustas kaukana.","Pane pois paha suu, ja väärät huulet anna olla sinustas kaukana."],[4,25,"Katsokoon silmäs oikein eteensä, ja sinun silmäs laudat olkoot oikiat edessäs.","Katsokoon silmäs oikein eteensä, ja sinun silmäs laudat olkoot oikiat edessäs."],[4,26,"Koettele jalkais askeleet, niin kaikki sinun ties vahvistuvat.","Koettele jalkais askeleet, niin kaikki sinun ties vahvistuvat."],[4,27,"Älä poikkee oikialle eli vasemmalle puolelle: tempaa jalkas pois pahuudesta.","Älä poikkee oikialle eli vasemmalle puolelle: tempaa jalkas pois pahuudesta."],[5,1,"Poikani, ota vaari viisaudestani: kallista korvas oppiini,","Poikani, ota vaari viisaudestani: kallista korvas oppiini,"],[5,2,"Ettäs pitäisit hyvän neuvon, ja sinun huules pitäis toimen.","Ettäs pitäisit hyvän neuvon, ja sinun huules pitäis toimen."],[5,3,"Sillä porton huulet ovat niin kuin mesileipä, ja hänen kitansa liukkaampi kuin öljy;","Sillä porton huulet ovat niin kuin mesileipä, ja hänen kitansa liukkaampi kuin öljy;"],[5,4,"Mutta viimeiseltä karvas kuin koiruoho, ja terävä kuin kaksiteräinen miekka.","Mutta viimeiseltä karvas kuin koiruoho, ja terävä kuin kaksiteräinen miekka."],[5,5,"Hänen jalkansa menevät alas kuolemaan, ja hänen askeleensa joutuvat helvettiin.","Hänen jalkansa menevät alas kuolemaan, ja hänen askeleensa joutuvat helvettiin."],[5,6,"Ei hän käy kohdastansa elämän tielle: huikentelevaiset ovat hänen astumisensa, niin ettei hän tiedä, kuhunka hän menee.","Ei hän käy kohdastansa elämän tielle: huikentelevaiset ovat hänen astumisensa, niin ettei hän tiedä, kuhunka hän menee."],[5,7,"Niin kuulkaat nyt minua, lapseni, ja älkäät poiketko minun puheistani.","Niin kuulkaat nyt minua, lapseni, ja älkäät poiketko minun puheistani."],[5,8,"Olkoon sinun ties kaukana hänestä, ja älä lähesty hänen hänen huoneensa ovea,","Olkoon sinun ties kaukana hänestä, ja älä lähesty hänen hänen huoneensa ovea,"],[5,9,"Ettes antaisi kunniaas muukalaisille, ja vuosias julmille;","Ettes antaisi kunniaas muukalaisille, ja vuosias julmille;"],[5,10,"Ettei muukalaiset ravittaisi sinun varastas, ja sinun työs olis toisen huoneessa,","Ettei muukalaiset ravittaisi sinun varastas, ja sinun työs olis toisen huoneessa,"],[5,11,"Ja sinä viimein huokaisit, koska elämäs ja hyvyytes tuhlannut olet,","Ja sinä viimein huokaisit, koska elämäs ja hyvyytes tuhlannut olet,"],[5,12,"Ja sanoisit: voi! kuinka minä olen vihannut hyvää neuvoa, ja sydämeni on hyljännyt kurituksen!","Ja sanoisit: voi! kuinka minä olen vihannut hyvää neuvoa, ja sydämeni on hyljännyt kurituksen!"],[5,13,"Ja en kuullut opettajani ääntä, enkä kallistanut korvaani opettajaini puoleen!","Ja en kuullut opettajani ääntä, enkä kallistanut korvaani opettajaini puoleen!"],[5,14,"Minä olen lähes kaikkeen pahuuteen joutunut, kaiken kansan ja seurakunnan keskellä.","Minä olen lähes kaikkeen pahuuteen joutunut, kaiken kansan ja seurakunnan keskellä."],[5,15,"Juo vettä kaivostas, ja mitä lähteestäs vuotaa.","Juo vettä kaivostas, ja mitä lähteestäs vuotaa."],[5,16,"Anna luontolähtees vuotaa ulos, ja vesiojas kujille.","Anna luontolähtees vuotaa ulos, ja vesiojas kujille."],[5,17,"Mutta pidä ne yksinäs, ja ei yksikään muukalainen sinun kanssas.","Mutta pidä ne yksinäs, ja ei yksikään muukalainen sinun kanssas."],[5,18,"Sinun kaivos olkoon siunattu, ja iloitse nuoruutes vaimosta.","Sinun kaivos olkoon siunattu, ja iloitse nuoruutes vaimosta."],[5,19,"Se on suloinen niinkuin naaras hirvi, ja otollinen niinkuin metsävuohi: hänen rakkautensa sinua aina ravitkoon; ja iloita itseäs aina hänen rakkaudestansa.","Se on suloinen niinkuin naaras hirvi, ja otollinen niinkuin metsävuohi: hänen rakkautensa sinua aina ravitkoon; ja iloita itseäs aina hänen rakkaudestansa."],[5,20,"Poikani, miksis annat muukalaisen sinuas pettää, ja halajat vierasta syliä?","Poikani, miksis annat muukalaisen sinuas pettää, ja halajat vierasta syliä?"],[5,21,"Sillä Herran edessä ovat kaikkien ihmisten tiet, ja hän tutkii kaikki heidän askeleensa.","Sillä Herran edessä ovat kaikkien ihmisten tiet, ja hän tutkii kaikki heidän askeleensa."],[5,22,"Jumalattoman vääryys käsittää hänen, ja hänen syntinsä paulat ottavat hänet kiinni.","Jumalattoman vääryys käsittää hänen, ja hänen syntinsä paulat ottavat hänet kiinni."],[5,23,"Hänen pitää kuoleman, ettei hän antanut opettaa itsiänsä, ja suuressa tyhmyydessänsä tulee hän petetyksi.","Hänen pitää kuoleman, ettei hän antanut opettaa itsiänsä, ja suuressa tyhmyydessänsä tulee hän petetyksi."],[6,1,"Poikani, jos sinää takaat lähimmäises, niin sinä olet kiinnittänyt kätes muukalaiseen.","Poikani, jos sinää takaat lähimmäises, niin sinä olet kiinnittänyt kätes muukalaiseen."],[6,2,"Sinun sanoissas olet sinä paulaan istunut: sinä olet saavutettu puheissas.","Sinun sanoissas olet sinä paulaan istunut: sinä olet saavutettu puheissas."],[6,3,"ee siis, poikani, näin: pelasta itses: sillä olet tullut lähimmäises käsiin: joudu, nöyryytä itses ja vaadi lähimmäistäs.","ee siis, poikani, näin: pelasta itses: sillä olet tullut lähimmäises käsiin: joudu, nöyryytä itses ja vaadi lähimmäistäs."],[6,4,"Älä anna silmilles unta, eikä silmälautas torkkua.","Älä anna silmilles unta, eikä silmälautas torkkua."],[6,5,"Kirvoita itses niinkuin metsävuohi pois käsistä, niinkuin lintu pyytäjänsä käsistä.","Kirvoita itses niinkuin metsävuohi pois käsistä, niinkuin lintu pyytäjänsä käsistä."],[6,6,"Mene laiska myyriäisen tykö, katso hänen menoansa ja opi.","Mene laiska myyriäisen tykö, katso hänen menoansa ja opi."],[6,7,"Vaikka ei hänelläyhtään hallitsiaa, teettäjää ja isäntää ole,","Vaikka ei hänelläyhtään hallitsiaa, teettäjää ja isäntää ole,"],[6,8,"Kuitenkin valmistaa hän elatuksensa suvella, ja koo ruokansa eloaikana.","Kuitenkin valmistaa hän elatuksensa suvella, ja koo ruokansa eloaikana."],[6,9,"Kuinka kauan sinä laiska makaat? koskas nouset unesta?","Kuinka kauan sinä laiska makaat? koskas nouset unesta?"],[6,10,"Makaa vielä vähä, ota vielä unta päähäs; laske kätes vähä yhteen, ettäs vielä levätä voisit;","Makaa vielä vähä, ota vielä unta päähäs; laske kätes vähä yhteen, ettäs vielä levätä voisit;"],[6,11,"Niin köyhyys äkisti tulee päälles niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies.","Niin köyhyys äkisti tulee päälles niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies."],[6,12,"Jumalatoin ihminen, vahingollinen mies, kävelee suunsa vääryydellä,","Jumalatoin ihminen, vahingollinen mies, kävelee suunsa vääryydellä,"],[6,13,"Iskee silmää, nyhtää jalvoillansa, kokottelee sormillansa.","Iskee silmää, nyhtää jalvoillansa, kokottelee sormillansa."],[6,14,"Vääryys on hänen sydämessänsä, ja aikoo pahaa: hän saattaa riidat matkaan.","Vääryys on hänen sydämessänsä, ja aikoo pahaa: hän saattaa riidat matkaan."],[6,15,"Sentähden tulee pikaisesti hänen kadotuksensa, ja hän äkisti muserretaan rikki, niin ettei hänellä yhtään parannusta ole.","Sentähden tulee pikaisesti hänen kadotuksensa, ja hän äkisti muserretaan rikki, niin ettei hänellä yhtään parannusta ole."],[6,16,"Kuusi on, joita Herra vihaa, ja seitsemää kauhistuu hänen sielunsa:","Kuusi on, joita Herra vihaa, ja seitsemää kauhistuu hänen sielunsa:"],[6,17,"Ylpiät silmät, petollinen kieli, kädet, jotka vuodattavat viatonta verta;","Ylpiät silmät, petollinen kieli, kädet, jotka vuodattavat viatonta verta;"],[6,18,"Sydän, joka vahingollisia ajattelee, jalat, jotka ovat nopsat pahuuteen juoksemaan;","Sydän, joka vahingollisia ajattelee, jalat, jotka ovat nopsat pahuuteen juoksemaan;"],[6,19,"Väärä todistaja, joka valheita tuottaa, ja se, joka saattaa riidan veljesten välille.","Väärä todistaja, joka valheita tuottaa, ja se, joka saattaa riidan veljesten välille."],[6,20,"Poikani, pidä isäs käskyt, ja älä hylkää äitis lakia.","Poikani, pidä isäs käskyt, ja älä hylkää äitis lakia."],[6,21,"Sido ne alati yhteen sydämes päälle, ja ripusta ne kaulaas.","Sido ne alati yhteen sydämes päälle, ja ripusta ne kaulaas."],[6,22,"Koskas vaellat, niin ne johdattavat sinua; koskas lepäät, niin he varjelevat sinua; koskas heräät, niin he puhuttelevat sinua.","Koskas vaellat, niin ne johdattavat sinua; koskas lepäät, niin he varjelevat sinua; koskas heräät, niin he puhuttelevat sinua."],[6,23,"Sillä käsky on niinkuin kynttilä, ja laki niinkuin valkeus, ja opin kuritus elämän tie,","Sillä käsky on niinkuin kynttilä, ja laki niinkuin valkeus, ja opin kuritus elämän tie,"],[6,24,"Ettäs varjeltaisiin pahasta vaimosta, ja muukalaisen makiasta kielestä.","Ettäs varjeltaisiin pahasta vaimosta, ja muukalaisen makiasta kielestä."],[6,25,"Älä himoitse sydämessäs hänen kauneuttansa, ettes vieteltäisi hänen silmäinsä kiillosta.","Älä himoitse sydämessäs hänen kauneuttansa, ettes vieteltäisi hänen silmäinsä kiillosta."],[6,26,"Sillä portto saattaa leivältä pois; mutta aviovaimo saattaa kauniin elämän.","Sillä portto saattaa leivältä pois; mutta aviovaimo saattaa kauniin elämän."],[6,27,"Taitaako joku kätkeä tulen poveensa, ettei hänen vaattensa pala?","Taitaako joku kätkeä tulen poveensa, ettei hänen vaattensa pala?"],[6,28,"Eli taitaako joku hiilten päällä kävellä, ettei hän jalkojansa polta?","Eli taitaako joku hiilten päällä kävellä, ettei hän jalkojansa polta?"],[6,29,"Niin sille tapahtuu, joka lähimmäisensä vaimoa lähentelee; ei se pääse rankaisematta, joka häneen ryhtyy.","Niin sille tapahtuu, joka lähimmäisensä vaimoa lähentelee; ei se pääse rankaisematta, joka häneen ryhtyy."],[6,30,"Ei se ole varkaalle niin suuri häpiä, jos hän varastaa henkensä piteeksi, koska nälkä on:","Ei se ole varkaalle niin suuri häpiä, jos hän varastaa henkensä piteeksi, koska nälkä on:"],[6,31,"Jos hän käsitetään, antaa hän sen seitsemänkertaisesti jälleen, ja kaiken huoneensa saadun;","Jos hän käsitetään, antaa hän sen seitsemänkertaisesti jälleen, ja kaiken huoneensa saadun;"],[6,32,"Mutta joka vaimon janssa huoruuteen lankee, se on tyhmä, ja joka sielunsa kadottaa tahtoo, se niin tekee.","Mutta joka vaimon janssa huoruuteen lankee, se on tyhmä, ja joka sielunsa kadottaa tahtoo, se niin tekee."],[6,33,"Rangaistus ja häpiä tulee hänen päällensä, ja hänen häväistyksensä ei pyyhitä pois.","Rangaistus ja häpiä tulee hänen päällensä, ja hänen häväistyksensä ei pyyhitä pois."],[6,34,"Sillä miehen vihalla on kiivaus: ei hän säästä häntä koston päivänä:","Sillä miehen vihalla on kiivaus: ei hän säästä häntä koston päivänä:"],[6,35,"Ei hän lukua pidä sovittajasta, eikä ota lahjoja, vaikka paljon antaisit.","Ei hän lukua pidä sovittajasta, eikä ota lahjoja, vaikka paljon antaisit."],[7,1,"Poikani! kätke minun sanani, ja pidä tykönäs minun käskyni.","Poikani! kätke minun sanani, ja pidä tykönäs minun käskyni."],[7,2,"Ota vaari minun käskyistäni, niin sinä elää saat, ja minun laistani, niinkuin silmäs terästä.","Ota vaari minun käskyistäni, niin sinä elää saat, ja minun laistani, niinkuin silmäs terästä."],[7,3,"Sido ne sormiis, kirjoita ne sydämes tauluun.","Sido ne sormiis, kirjoita ne sydämes tauluun."],[7,4,"Sano viiisaudelle: sinä olet sisareni, ja kutsu toimi ystäväkses,","Sano viiisaudelle: sinä olet sisareni, ja kutsu toimi ystäväkses,"],[7,5,"Että hän sinua varjelis muukalaisesta vaimosta, ja vieraasta, jonka sanat sileät ovat.","Että hän sinua varjelis muukalaisesta vaimosta, ja vieraasta, jonka sanat sileät ovat."],[7,6,"Sillä minä kurkistelin huoneeni akkunasta läpi häkin.","Sillä minä kurkistelin huoneeni akkunasta läpi häkin."],[7,7,"Ja näin tyhmän nuorukaisen taitamattomain seassa, ja äkkäsin hänen poikain joukossa;","Ja näin tyhmän nuorukaisen taitamattomain seassa, ja äkkäsin hänen poikain joukossa;"],[7,8,"Joka käveli kaduilla hänen nurkkainsa taitse, ja asteli sitä tietä, joka meni hänen huoneeseensa.","Joka käveli kaduilla hänen nurkkainsa taitse, ja asteli sitä tietä, joka meni hänen huoneeseensa."],[7,9,"Hämärissä, kuin päivä ehtoolla oli, ja jo yö ja pimiä tuli:","Hämärissä, kuin päivä ehtoolla oli, ja jo yö ja pimiä tuli:"],[7,10,"Ja katso, häntä kohtasi vaimo porton vaatteilla, kavala,","Ja katso, häntä kohtasi vaimo porton vaatteilla, kavala,"],[7,11,"Tuima ja hillimätöin, jonka jalat ei pysyneet huoneessansa.","Tuima ja hillimätöin, jonka jalat ei pysyneet huoneessansa."],[7,12,"Nyt on hän ulkona, nyt kaduilla, ja väijyy joka nurkassa.","Nyt on hän ulkona, nyt kaduilla, ja väijyy joka nurkassa."],[7,13,"Hän otti hänen kiinni, ja suuta antoi hänen ja sanoi häpeemättä:","Hän otti hänen kiinni, ja suuta antoi hänen ja sanoi häpeemättä:"],[7,14,"Minä olen tehnyt kiitosuhrin, ja olen tätäpänä täyttänyt lupaukseni:","Minä olen tehnyt kiitosuhrin, ja olen tätäpänä täyttänyt lupaukseni:"],[7,15,"Sentähden olen minä tullut sinua vastaan, varhain sinua etsimään, ja olen nyt sinut löytänyt.","Sentähden olen minä tullut sinua vastaan, varhain sinua etsimään, ja olen nyt sinut löytänyt."],[7,16,"Minä olen koreasti valmistanut vuoteeni Egyptin kirjavalla vaatteella,","Minä olen koreasti valmistanut vuoteeni Egyptin kirjavalla vaatteella,"],[7,17,"Ja olen hyvänhajuiseksi tehnyt kammioni mirhamilla, aloella ja kanelilla.","Ja olen hyvänhajuiseksi tehnyt kammioni mirhamilla, aloella ja kanelilla."],[7,18,"Tule, harjoittakaamme kyllin hekumaa aamuun asti, ja huvitelkaammme meitämme keskenämme rakkaudella.","Tule, harjoittakaamme kyllin hekumaa aamuun asti, ja huvitelkaammme meitämme keskenämme rakkaudella."],[7,19,"Sillä mies ei ole kotona: hän on pitkälle matkalle mennyt.","Sillä mies ei ole kotona: hän on pitkälle matkalle mennyt."],[7,20,"Hän on ottanut rahasäkin myötänsä, ja tulee kotia äsken määrätyllä päivällä.","Hän on ottanut rahasäkin myötänsä, ja tulee kotia äsken määrätyllä päivällä."],[7,21,"Ja niin hän houkutteli monelöla sanalla, ja vaati häntä makialla puheella.","Ja niin hän houkutteli monelöla sanalla, ja vaati häntä makialla puheella."],[7,22,"Hän meni hänen kanssansa nopiasti, niinkuin teurastettava härkä, ja niinkuin jalkapuuhun, jolla tyhmät rangoitaan.","Hän meni hänen kanssansa nopiasti, niinkuin teurastettava härkä, ja niinkuin jalkapuuhun, jolla tyhmät rangoitaan."],[7,23,"Siihenasti kuin hän nuolilla ampuu hänen maksansa lävitse: ja niinkuin lintu itsensä kiiruhtaa paulaan, ja ei tiedä sitä hengellensä vaaralliseksi.","Siihenasti kuin hän nuolilla ampuu hänen maksansa lävitse: ja niinkuin lintu itsensä kiiruhtaa paulaan, ja ei tiedä sitä hengellensä vaaralliseksi."],[7,24,"Niin kuulkaat siis minua, minun lapseni, ja ottakaat vaari minun suuni sanoista.","Niin kuulkaat siis minua, minun lapseni, ja ottakaat vaari minun suuni sanoista."],[7,25,"Älköön sydämes poiketko hänen tiellensä: älä salli sinuas vietellä hänen retkillensä.","Älköön sydämes poiketko hänen tiellensä: älä salli sinuas vietellä hänen retkillensä."],[7,26,"Sillä hän on monta haavoittanut ja langettanut, ja kaikkinaiset voimalliset ovat häneltä tapetut.","Sillä hän on monta haavoittanut ja langettanut, ja kaikkinaiset voimalliset ovat häneltä tapetut."],[7,27,"Hänen huoneensa ovat helvetin tiet, jotka menevät alas kuoleman kammioihin.","Hänen huoneensa ovat helvetin tiet, jotka menevät alas kuoleman kammioihin."],[8,1,"Eikö viisaus huuda, ja toimi julista ääntänsä?","Eikö viisaus huuda, ja toimi julista ääntänsä?"],[8,2,"Korkialla paikalla seisoo hän, teiden ja kujain vieressä.","Korkialla paikalla seisoo hän, teiden ja kujain vieressä."],[8,3,"Porteilla, kaupungin ovilla, joista sisälle käydään, hän huutaa:","Porteilla, kaupungin ovilla, joista sisälle käydään, hän huutaa:"],[8,4,"Te miehet! minä huudan teitä, ja minun ääneni on teidän tykönne, te ihmisten lapset;","Te miehet! minä huudan teitä, ja minun ääneni on teidän tykönne, te ihmisten lapset;"],[8,5,"Ymmärtäkäät te tyhmät viisautta, ja te houkkiot pankaat sydämiinne.","Ymmärtäkäät te tyhmät viisautta, ja te houkkiot pankaat sydämiinne."],[8,6,"Kuulkaat, sillä minä puhun sitä, mikä korkia on, opetan sitä, mikä oikia on.","Kuulkaat, sillä minä puhun sitä, mikä korkia on, opetan sitä, mikä oikia on."],[8,7,"Sillä minun suuni puhuu totuutta, ja minun huuleni vihaa jamalatointa.","Sillä minun suuni puhuu totuutta, ja minun huuleni vihaa jamalatointa."],[8,8,"Kaikki minun puheeni ovat oikiat: ei ole siinä mitään petosta eli vääryyttä.","Kaikki minun puheeni ovat oikiat: ei ole siinä mitään petosta eli vääryyttä."],[8,9,"Ne kaikki ovat selkiät niille, jotka niitä ymmärtävät, ja oikiat niille, jotka taidon löytävät.","Ne kaikki ovat selkiät niille, jotka niitä ymmärtävät, ja oikiat niille, jotka taidon löytävät."],[8,10,"Ottakaat minun kuritukseni ennenkuin hopia, ja pitäkäät korkiampana minun oppini kuin kallein kulta.","Ottakaat minun kuritukseni ennenkuin hopia, ja pitäkäät korkiampana minun oppini kuin kallein kulta."],[8,11,"Sillä viisaus on parempi kuin päärlyt, ja kaikki, mitä ihminen itsellensä toivottaa, ei ole hänen vertaisensa.","Sillä viisaus on parempi kuin päärlyt, ja kaikki, mitä ihminen itsellensä toivottaa, ei ole hänen vertaisensa."],[8,12,"Minä viisaus asun toimen tykönä, ja minä taidan antaa hyvän neuvon.","Minä viisaus asun toimen tykönä, ja minä taidan antaa hyvän neuvon."],[8,13,"Se on Herran pelko: vihata pahaa, ylpeyttä, tuimuutta ja pahoja teitä; sentähden vihaan minä petollista suuta.","Se on Herran pelko: vihata pahaa, ylpeyttä, tuimuutta ja pahoja teitä; sentähden vihaan minä petollista suuta."],[8,14,"Minun on neuvo ja voima, minun on toimi ja väkevyys.","Minun on neuvo ja voima, minun on toimi ja väkevyys."],[8,15,"Minun kauttani kuninkaat hallitsevat, ja neuvonantajat oikeutta saattavat;","Minun kauttani kuninkaat hallitsevat, ja neuvonantajat oikeutta saattavat;"],[8,16,"Minun kauttani päämiehet vallitsevat, valtamiehet ja kaikki maan tuomarit.","Minun kauttani päämiehet vallitsevat, valtamiehet ja kaikki maan tuomarit."],[8,17,"Minä rakastan niitä, jotka minua rakastavat, jotka varhain minua etsivät, ne löytävät minun.","Minä rakastan niitä, jotka minua rakastavat, jotka varhain minua etsivät, ne löytävät minun."],[8,18,"Rikkaus ja kunnia on minun tykönäni, pysyväinen tavara ja vanhurskaus.","Rikkaus ja kunnia on minun tykönäni, pysyväinen tavara ja vanhurskaus."],[8,19,"Minun hedelmäni on parempi kuin kulta ja rikkain kulta, ja minun tuloni parempi kuin valittu hopia.","Minun hedelmäni on parempi kuin kulta ja rikkain kulta, ja minun tuloni parempi kuin valittu hopia."],[8,20,"Minä vaellan vanhurskaudentietä ja oikeuden askeleilla,","Minä vaellan vanhurskaudentietä ja oikeuden askeleilla,"],[8,21,"Että minä pysyväisen perinnön saattaisin niille, jotka minua rakastavat, ja täyttäisin heidän tavaransa.","Että minä pysyväisen perinnön saattaisin niille, jotka minua rakastavat, ja täyttäisin heidän tavaransa."],[8,22,"Minä olen ollut Herran oma hänen teidensä alussa: ennenkuin mitään tehty oli, olin minä.","Minä olen ollut Herran oma hänen teidensä alussa: ennenkuin mitään tehty oli, olin minä."],[8,23,"Jo ijankaikkisuudesta olen minä asetettu, alussa, ennenkuin maa oli.","Jo ijankaikkisuudesta olen minä asetettu, alussa, ennenkuin maa oli."],[8,24,"Kuin ei syvyys vielä ollut, silloin minä olin jo syntynyt, kuin ei lähteet vielä vettä kuohuneet.","Kuin ei syvyys vielä ollut, silloin minä olin jo syntynyt, kuin ei lähteet vielä vettä kuohuneet."],[8,25,"Ennen kuin vuoret olivat perustetut, ja kukkulat valmistetut, olen minä syntynyt;","Ennen kuin vuoret olivat perustetut, ja kukkulat valmistetut, olen minä syntynyt;"],[8,26,"Ei hän ollut vielä maata luonut, ja mitä sen päällä on, eikä maan piirin vuoria.","Ei hän ollut vielä maata luonut, ja mitä sen päällä on, eikä maan piirin vuoria."],[8,27,"Kuin hän valmisti taivaan, olin minä siellä, kuin hän syvyyden visusti mittasi.","Kuin hän valmisti taivaan, olin minä siellä, kuin hän syvyyden visusti mittasi."],[8,28,"Kuin hän pilvet rakensi ylhäällä, ja sääsi syvyyden lähteet;","Kuin hän pilvet rakensi ylhäällä, ja sääsi syvyyden lähteet;"],[8,29,"Kuin hän meren ääret määräsi, ja vetten eteen asetti määrän, ettei he astuisi rantansa ylitse; kuin hän maan perustukset laski,","Kuin hän meren ääret määräsi, ja vetten eteen asetti määrän, ettei he astuisi rantansa ylitse; kuin hän maan perustukset laski,"],[8,30,"Silloin minä hänen kanssansa vaikutin, ja iloitsin joka päivä, ja leikitsin hänen hänen edessänsä joka aika;","Silloin minä hänen kanssansa vaikutin, ja iloitsin joka päivä, ja leikitsin hänen hänen edessänsä joka aika;"],[8,31,"Ja leikitsin maan piirin päällä; ja minun iloni on olla ihmisten lasten kanssa.","Ja leikitsin maan piirin päällä; ja minun iloni on olla ihmisten lasten kanssa."],[8,32,"Niin kuulkaat siis minua, te lapset: autuaat ovat ne, jotka minun tieni pitävät.","Niin kuulkaat siis minua, te lapset: autuaat ovat ne, jotka minun tieni pitävät."],[8,33,"Kuulkaat kuritusta, olkaat viisaat, ja älkäät hyljätkö sitä.","Kuulkaat kuritusta, olkaat viisaat, ja älkäät hyljätkö sitä."],[8,34,"Autuas on se ihminen, joka minua kuulee, joka minun ovellani valvoo joka päivä, ja vartioitsee minun pihtipielissäni.","Autuas on se ihminen, joka minua kuulee, joka minun ovellani valvoo joka päivä, ja vartioitsee minun pihtipielissäni."],[8,35,"Sillä joka minun löytää, hän elämän löytää, ja on Herralle otollinen;","Sillä joka minun löytää, hän elämän löytää, ja on Herralle otollinen;"],[8,36,"Mutta, joka minua vastaan syntiä tekee, hän vahingoitsee sielunsa: jokainen joka minua vihaa, hän rakastaa kuolemaa.","Mutta, joka minua vastaan syntiä tekee, hän vahingoitsee sielunsa: jokainen joka minua vihaa, hän rakastaa kuolemaa."],[9,1,"Viisaus rakensi huoneensa, ja vuoli siihen seitsemän patsasta,","Viisaus rakensi huoneensa, ja vuoli siihen seitsemän patsasta,"],[9,2,"Ja teurasti teuraansa, sekoitti viinansa ja valmisti pöytänsä,","Ja teurasti teuraansa, sekoitti viinansa ja valmisti pöytänsä,"],[9,3,"Ja lähetti piikansa, korkeista kaupungin saleista kutsumaan:","Ja lähetti piikansa, korkeista kaupungin saleista kutsumaan:"],[9,4,"Joka tyhmä on, hän tulkaan tänne; ja hulluille sanoi hän:","Joka tyhmä on, hän tulkaan tänne; ja hulluille sanoi hän:"],[9,5,"Tulkaat ja syökäät minun leivästäni, ja juokaat viinaa, jonka minä sekoitin.","Tulkaat ja syökäät minun leivästäni, ja juokaat viinaa, jonka minä sekoitin."],[9,6,"Hyljätkää hullu meno, niin te saatte elää, ja käykää ymmärryksen tiellä.","Hyljätkää hullu meno, niin te saatte elää, ja käykää ymmärryksen tiellä."],[9,7,"Joka pilkkaajaa kurittaa, hän saa häpiän, ja joka jumalatointa nuhtelee, hän häväistään.","Joka pilkkaajaa kurittaa, hän saa häpiän, ja joka jumalatointa nuhtelee, hän häväistään."],[9,8,"Älä rankaise pilkkaajaa, ettei hän sinua vihaisi: nuhtele viisasta, ja hän rakastaa sinua.","Älä rankaise pilkkaajaa, ettei hän sinua vihaisi: nuhtele viisasta, ja hän rakastaa sinua."],[9,9,"Anna viisaalle, niin hän viisaammaksi tulee: opeta vanhurskasta, niin hän opissaan etenee.","Anna viisaalle, niin hän viisaammaksi tulee: opeta vanhurskasta, niin hän opissaan etenee."],[9,10,"Viisauden alku on Herran pelko, ja pyhäin tieto on ymmärrys.","Viisauden alku on Herran pelko, ja pyhäin tieto on ymmärrys."],[9,11,"Sillä minun kauttani sinun päiväs enennetään, ja ikäs vuodet lisätään.","Sillä minun kauttani sinun päiväs enennetään, ja ikäs vuodet lisätään."],[9,12,"Jos sinä olet viisas, niin sinä itselles viisas olet; mutta jos sinä olet pilkkaaja, niin sinä itse sen kannat.","Jos sinä olet viisas, niin sinä itselles viisas olet; mutta jos sinä olet pilkkaaja, niin sinä itse sen kannat."],[9,13,"Hullu, huikentelevainen vaimo, mieletöin ei tiedä mitään,","Hullu, huikentelevainen vaimo, mieletöin ei tiedä mitään,"],[9,14,"Istuu huoneensa ovella, korkialla istuimella, ylimmäisessä siassa kaupungissa,","Istuu huoneensa ovella, korkialla istuimella, ylimmäisessä siassa kaupungissa,"],[9,15,"Että hän houkuttelis kaikkia, jotka siitä käyvät ohitse, ja tietänsä vaeltavat:","Että hän houkuttelis kaikkia, jotka siitä käyvät ohitse, ja tietänsä vaeltavat:"],[9,16,"Se joka tyhmä on, hän tulkoon tänne; ja hullulle sanoo hän:","Se joka tyhmä on, hän tulkoon tänne; ja hullulle sanoo hän:"],[9,17,"Varastettu vesi on makia, ja salattu leipä suloinen;","Varastettu vesi on makia, ja salattu leipä suloinen;"],[9,18,"Vaan ei hän tiedä, että siellä kuolleet ovat: hänen vieraansa ovat helvetin syvyydessä.","Vaan ei hän tiedä, että siellä kuolleet ovat: hänen vieraansa ovat helvetin syvyydessä."],[10,1,"Salomon sananlaskut. Viisas poika on isänsä ilo, mutta hullu poika on äidillensä murheeksi.","Salomon sananlaskut. Viisas poika on isänsä ilo, mutta hullu poika on äidillensä murheeksi."],[10,2,"Väärin saatu tavara ei ole hyödyllinen; mutta vanhurskaus vapauttaa kuolemasta.","Väärin saatu tavara ei ole hyödyllinen; mutta vanhurskaus vapauttaa kuolemasta."],[10,3,"Ei Herra anna vanhurskasten sielun nälkää kärsiä, mutta jumalattomain väärin saadut hän hajoittaa.","Ei Herra anna vanhurskasten sielun nälkää kärsiä, mutta jumalattomain väärin saadut hän hajoittaa."],[10,4,"Petollinen käsi tekee köyhäksi, mutta ahkera saattaa rikkaaksi.","Petollinen käsi tekee köyhäksi, mutta ahkera saattaa rikkaaksi."],[10,5,"Joka suvella kokoo, hän on toimellinen, mutta joka elonaikana makaa, hän tulee häpiään.","Joka suvella kokoo, hän on toimellinen, mutta joka elonaikana makaa, hän tulee häpiään."],[10,6,"Siunaus on vanhurskaan pään päällä, mutta jumalattoman suun peittää vääryys.","Siunaus on vanhurskaan pään päällä, mutta jumalattoman suun peittää vääryys."],[10,7,"Vanhurskaan muisto pysyy siunauksessa, vaan jumalattomain nimi mätänee.","Vanhurskaan muisto pysyy siunauksessa, vaan jumalattomain nimi mätänee."],[10,8,"Joka sydämestänsä viisas on, hän ottaa käskyt vastaan; mutta jolla hullut huulet ovat, se saa haavoja.","Joka sydämestänsä viisas on, hän ottaa käskyt vastaan; mutta jolla hullut huulet ovat, se saa haavoja."],[10,9,"Joka nuhteettomasti vaeltaa, hän elää murheetoinna; mutta joka väärällä tiellä vaeltaa, hän tulee ilmi.","Joka nuhteettomasti vaeltaa, hän elää murheetoinna; mutta joka väärällä tiellä vaeltaa, hän tulee ilmi."],[10,10,"Joka silmää iskee, hän vaivaa matkaan saattaa, ja jolla hullut huulet ovat, hän saa haavoja.","Joka silmää iskee, hän vaivaa matkaan saattaa, ja jolla hullut huulet ovat, hän saa haavoja."],[10,11,"Vanhurskaan suu on elämän lähde, mutta jumalattoman suun peittää vääryys.","Vanhurskaan suu on elämän lähde, mutta jumalattoman suun peittää vääryys."],[10,12,"Viha riidan saattaa, mutta rakkaus peittää kaikki rikokset.","Viha riidan saattaa, mutta rakkaus peittää kaikki rikokset."],[10,13,"Toimellisten huulissa löydetään viisaus, vaan tyhmäin selkään tarvitaan vitsa.","Toimellisten huulissa löydetään viisaus, vaan tyhmäin selkään tarvitaan vitsa."],[10,14,"Viisaat opin kätkevät, vaan hulluin suu on täynnä vahinkoa.","Viisaat opin kätkevät, vaan hulluin suu on täynnä vahinkoa."],[10,15,"Rikkaan tavara on hänen vahva kaupunkinsa; mutta köyhyys tekee köyhän pelkuriksi.","Rikkaan tavara on hänen vahva kaupunkinsa; mutta köyhyys tekee köyhän pelkuriksi."],[10,16,"Vanhurskaus tekee työtä hengen ylöspitämiseksi, mutta jumalattoman saalis on symmiksi.","Vanhurskaus tekee työtä hengen ylöspitämiseksi, mutta jumalattoman saalis on symmiksi."],[10,17,"Joka kurituksen ottaa vastaan, hän on elämän tiellä; mutta joka rangaistuksen heittää pois, hän menee väärin.","Joka kurituksen ottaa vastaan, hän on elämän tiellä; mutta joka rangaistuksen heittää pois, hän menee väärin."],[10,18,"Petolliset suut peittävät vainon, ja joka panettelee,hän on tyhmä.","Petolliset suut peittävät vainon, ja joka panettelee,hän on tyhmä."],[10,19,"Jossa paljo puhutaan, siitä ei synti ole kaukana; mutta joka huulensa hillitsee, hän on toimellinen.","Jossa paljo puhutaan, siitä ei synti ole kaukana; mutta joka huulensa hillitsee, hän on toimellinen."],[10,20,"Vanhurskaan kieli on kalliimpi hopiaa, mutta jumalattoman sydän on miinkuin ei mitään.","Vanhurskaan kieli on kalliimpi hopiaa, mutta jumalattoman sydän on miinkuin ei mitään."],[10,21,"Vanhurskaan huulet monta ravitsevat, mutta hullut kuolevat hulluudessa.","Vanhurskaan huulet monta ravitsevat, mutta hullut kuolevat hulluudessa."],[10,22,"Herran siunaus tekee rikkaaksi ilman vaivaa.","Herran siunaus tekee rikkaaksi ilman vaivaa."],[10,23,"Hullu tekee pahaa ja nauraa sitä, vaan viisas pitää siitä vaarinsa.","Hullu tekee pahaa ja nauraa sitä, vaan viisas pitää siitä vaarinsa."],[10,24,"Mitä jumalatoin pelkää, se hänelle tapahtuu, ja mitä vanhurskaat himoitsevat, sitä heille annetaan.","Mitä jumalatoin pelkää, se hänelle tapahtuu, ja mitä vanhurskaat himoitsevat, sitä heille annetaan."],[10,25,"Jumalatoin on niinkuin tuulispää, joka menee ohitse ja tyhjiksi raukee; mutta vanhurskas pysyy ijankaikkisesti.","Jumalatoin on niinkuin tuulispää, joka menee ohitse ja tyhjiksi raukee; mutta vanhurskas pysyy ijankaikkisesti."],[10,26,"Niin kuin etikka tekee pahaa hampaille ja savu silmille, niin on laiska niiden mielestä paha, jotka hänen lähettävät.","Niin kuin etikka tekee pahaa hampaille ja savu silmille, niin on laiska niiden mielestä paha, jotka hänen lähettävät."],[10,27,"Herran pelko enentää päiviä, vaan jumalattomain vuodet vähennetään.","Herran pelko enentää päiviä, vaan jumalattomain vuodet vähennetään."],[10,28,"Vanhurskaan toivo on ilo, mutta jumalattomain toivo katoo.","Vanhurskaan toivo on ilo, mutta jumalattomain toivo katoo."],[10,29,"Herran tie on hurskasten väkevyys, mutta pahointekiät ovat pelkurit.","Herran tie on hurskasten väkevyys, mutta pahointekiät ovat pelkurit."],[10,30,"Vanhurskas pysyy aina kohdallansa kukistamatta, mutta jumalattoman ei pidä asuman maan päällä.","Vanhurskas pysyy aina kohdallansa kukistamatta, mutta jumalattoman ei pidä asuman maan päällä."],[10,31,"Vanhurskaan suu tuottaa viisauden, vaan vääräin kieli hukutetaan.","Vanhurskaan suu tuottaa viisauden, vaan vääräin kieli hukutetaan."],[10,32,"Vanhurskaan huulet opettavat terveellisiä asioita, vaan jumalattoman suu on täynnä vääryyttä.","Vanhurskaan huulet opettavat terveellisiä asioita, vaan jumalattoman suu on täynnä vääryyttä."],[11,1,"Väärä vaaka on Herralle kauhistus, mutta oikia puntari on hänelle otollinen.","Väärä vaaka on Herralle kauhistus, mutta oikia puntari on hänelle otollinen."],[11,2,"Kussa ylpeys on, siinä on myös ylönkatse; mutta viisaus on nöyräin tykönä.","Kussa ylpeys on, siinä on myös ylönkatse; mutta viisaus on nöyräin tykönä."],[11,3,"Viattomuus johdattaa siviät, vaan pahuus kukistaa pilkkaajat.","Viattomuus johdattaa siviät, vaan pahuus kukistaa pilkkaajat."],[11,4,"Ei rakkaus auta vihan päivänä, mutta vanhurskaus vapahtaa kuolemasta.","Ei rakkaus auta vihan päivänä, mutta vanhurskaus vapahtaa kuolemasta."],[11,5,"Viattoman vanhurskaus tekee hänen tiensä tasaiseksi, mutta jumalatoin lankee jumalattomassa menossansa.","Viattoman vanhurskaus tekee hänen tiensä tasaiseksi, mutta jumalatoin lankee jumalattomassa menossansa."],[11,6,"Jumalisten vanhurskaus pelastaa heitä, vaan väärintekiät käsitetään viekkaudessansa.","Jumalisten vanhurskaus pelastaa heitä, vaan väärintekiät käsitetään viekkaudessansa."],[11,7,"Kuin jumalatoin ihminen kuolee, niin ei ole yhtään toivoa: ja jota väärintekiät odottavat, se tulee tyhjäksi.","Kuin jumalatoin ihminen kuolee, niin ei ole yhtään toivoa: ja jota väärintekiät odottavat, se tulee tyhjäksi."],[11,8,"Vanhurskas vapahdetaan vaivasta, ja jumalatoin tuleehänen siaansa.","Vanhurskas vapahdetaan vaivasta, ja jumalatoin tuleehänen siaansa."],[11,9,"Ulkokullatun ihmisen suun kautta petetään hänen lähimmäisensä; vaan vanhurskaat ymmärtävät sen, ja pelastetaan.","Ulkokullatun ihmisen suun kautta petetään hänen lähimmäisensä; vaan vanhurskaat ymmärtävät sen, ja pelastetaan."],[11,10,"Kaupunki iloitsee, koska vanhurskaan hyvin käy, ja riemuitsee, koska jumalatoin hukkuu.","Kaupunki iloitsee, koska vanhurskaan hyvin käy, ja riemuitsee, koska jumalatoin hukkuu."],[11,11,"Vanhurskasten siunauksen kautta kaupunki korotetaan, vaan jumalattoman suun kautta kukistetaan.","Vanhurskasten siunauksen kautta kaupunki korotetaan, vaan jumalattoman suun kautta kukistetaan."],[11,12,"Joka lähimmäistänsä häpäisee, se on hullu, mutta toimellinen mies on vaiti.","Joka lähimmäistänsä häpäisee, se on hullu, mutta toimellinen mies on vaiti."],[11,13,"Panettelia ilmoittaa salaisuuden, vaan jolla on uskollinen sydän, hän salaa sen.","Panettelia ilmoittaa salaisuuden, vaan jolla on uskollinen sydän, hän salaa sen."],[11,14,"Jossa ei neuvoa ole, siinä kansa hukkuu; vaan jossa monta neuvonantajaa on, siinä hyvin käy.","Jossa ei neuvoa ole, siinä kansa hukkuu; vaan jossa monta neuvonantajaa on, siinä hyvin käy."],[11,15,"Joka toisen takaa, hän tulee vahinkoon; vaan joka siitä itsensä pitää pois, hän on murheetoin.","Joka toisen takaa, hän tulee vahinkoon; vaan joka siitä itsensä pitää pois, hän on murheetoin."],[11,16,"Vaimo, joka otollinen on, pitää kunnian; vaan väkevät pitävät rikkauden.","Vaimo, joka otollinen on, pitää kunnian; vaan väkevät pitävät rikkauden."],[11,17,"Armias mies tekee ruumiillensa hyvää; vaan se, joka julma on, saattaa lihansa murheelliseksi.","Armias mies tekee ruumiillensa hyvää; vaan se, joka julma on, saattaa lihansa murheelliseksi."],[11,18,"Jumalattoman työ on turha, vaan joka vanhurskautta kylvää, sillä on hyvä palkka.","Jumalattoman työ on turha, vaan joka vanhurskautta kylvää, sillä on hyvä palkka."],[11,19,"Sillä vanhurskaus saattaa elämän, vaan joka pahaa pyytää, hän saattaa kuoleman.","Sillä vanhurskaus saattaa elämän, vaan joka pahaa pyytää, hän saattaa kuoleman."],[11,20,"Petollinen sydän on kauhistus Herralle, Vaan viattoman tie on hänelle otollinen.","Petollinen sydän on kauhistus Herralle, Vaan viattoman tie on hänelle otollinen."],[11,21,"Ei jumalattoimia auta, vaikka kaikki kätensä yhteen pistäisivät, mutta vanhurskaan siemen pelastetaan.","Ei jumalattoimia auta, vaikka kaikki kätensä yhteen pistäisivät, mutta vanhurskaan siemen pelastetaan."],[11,22,"Kaunis vaimo ilman taidota on niinkuin sika, jolla olis kultainen käädy kuonossa.","Kaunis vaimo ilman taidota on niinkuin sika, jolla olis kultainen käädy kuonossa."],[11,23,"Vanhurskasten himo on ainoastaan hyvä, vaan jumalattomain odotus on kiukku.","Vanhurskasten himo on ainoastaan hyvä, vaan jumalattomain odotus on kiukku."],[11,24,"Muutama jakaa omastansa, ja saa enemmän; toinen säästää, jossa ei pitäisi, ja tulee köyhemmäksi.","Muutama jakaa omastansa, ja saa enemmän; toinen säästää, jossa ei pitäisi, ja tulee köyhemmäksi."],[11,25,"Sielu, joka siunaa, tulee rikkaaksi: ja joka juottaa, se myös juotetaan.","Sielu, joka siunaa, tulee rikkaaksi: ja joka juottaa, se myös juotetaan."],[11,26,"Joka jyvät salaa, häntä kansa kiroilee; mutta joka myy, hänelle tulee siunaus.","Joka jyvät salaa, häntä kansa kiroilee; mutta joka myy, hänelle tulee siunaus."],[11,27,"Joka varhain hyvää etsii, hänelle hyvin menestyy; mutta joka pahaa noudattaa, hänelle pahoin tapahtuu.","Joka varhain hyvää etsii, hänelle hyvin menestyy; mutta joka pahaa noudattaa, hänelle pahoin tapahtuu."],[11,28,"Joka rikkauteensa luottaa, hän hukkuu, vaan vanhurskaat viheriöitsevät niinkuin lehti.","Joka rikkauteensa luottaa, hän hukkuu, vaan vanhurskaat viheriöitsevät niinkuin lehti."],[11,29,"Joka huoneensa murheelliseksi tekee, hän saa tuulen perinnöksi: ja hullun täytyy viisasta palvella.","Joka huoneensa murheelliseksi tekee, hän saa tuulen perinnöksi: ja hullun täytyy viisasta palvella."],[11,30,"Vanhurskaan hedelmä on elämän puu: joka viisas on, hän kääntää sielut.","Vanhurskaan hedelmä on elämän puu: joka viisas on, hän kääntää sielut."],[11,31,"Koska vanhurskas paljon kärsii, kuinka paljoa enemmin jumalatoin ja syntinen?","Koska vanhurskas paljon kärsii, kuinka paljoa enemmin jumalatoin ja syntinen?"],[12,1,"Joka itsensä mielellänsä kurittaa antaa, se tulee toimelliseksi; mutta joka rankaisematta olla tahtoo, se on tyhmä.","Joka itsensä mielellänsä kurittaa antaa, se tulee toimelliseksi; mutta joka rankaisematta olla tahtoo, se on tyhmä."],[12,2,"Hyvä saa lohdutuksen Herralta, mutta häijy mies hyljätään.","Hyvä saa lohdutuksen Herralta, mutta häijy mies hyljätään."],[12,3,"Ei ihminen vahvistu jumalattomuudessa, vaan vanhurskaan juuri on pysyväinen.","Ei ihminen vahvistu jumalattomuudessa, vaan vanhurskaan juuri on pysyväinen."],[12,4,"Ahkera vaimo on miehensä kruunu, vaan häijy on niinkuin märkä hänen luissansa.","Ahkera vaimo on miehensä kruunu, vaan häijy on niinkuin märkä hänen luissansa."],[12,5,"Vanhurskasten ajatukset ovat vilpittömät, vaan jumalattomain aivoitus on petollinen.","Vanhurskasten ajatukset ovat vilpittömät, vaan jumalattomain aivoitus on petollinen."],[12,6,"Jumalattomain sanat väijyvät verta, vaan hurskasten suu vapahtaa heitä.","Jumalattomain sanat väijyvät verta, vaan hurskasten suu vapahtaa heitä."],[12,7,"Jumalattomat kaatuvat, ja ei ole sitte enää, mutta vanhurskasten huone pysyy.","Jumalattomat kaatuvat, ja ei ole sitte enää, mutta vanhurskasten huone pysyy."],[12,8,"Toimellinen mies neuvossansa ylistetään, vaan petollinen tulee katsotuksi ylön.","Toimellinen mies neuvossansa ylistetään, vaan petollinen tulee katsotuksi ylön."],[12,9,"Parempi on nöyrä, joka omansa katsoo, kuin se, joka tahtoo iso olla, ja kuitenkin puuttuu leipää.","Parempi on nöyrä, joka omansa katsoo, kuin se, joka tahtoo iso olla, ja kuitenkin puuttuu leipää."],[12,10,"Vanhurskas armahtaa juhtaansa, mutta jumalattoman sydän on halutoin.","Vanhurskas armahtaa juhtaansa, mutta jumalattoman sydän on halutoin."],[12,11,"Joka peltonsa viljelee, se saa leipää yltäkylläisesti; vaan joka turhia ajelee takaa, se on tyhmä.","Joka peltonsa viljelee, se saa leipää yltäkylläisesti; vaan joka turhia ajelee takaa, se on tyhmä."],[12,12,"Jumalatoin halajaa aina pahaa tehdä, mutta vanhurskaan juuri kantaa hedelmää.","Jumalatoin halajaa aina pahaa tehdä, mutta vanhurskaan juuri kantaa hedelmää."],[12,13,"Ilkiä käsitetään omissa sanoissansa, vaan vanhurskas pääsee hädästä.","Ilkiä käsitetään omissa sanoissansa, vaan vanhurskas pääsee hädästä."],[12,14,"Suun hedelmästä tulee paljon hyvää; ja niinkuin kukin käsillänsä tehnyt on, kostetaan hänelle.","Suun hedelmästä tulee paljon hyvää; ja niinkuin kukin käsillänsä tehnyt on, kostetaan hänelle."],[12,15,"Tyhmäin mielestä on hänen tiensä otollinen, mutta viisas ottaa neuvon.","Tyhmäin mielestä on hänen tiensä otollinen, mutta viisas ottaa neuvon."],[12,16,"Tyhmä osoittaa kohta vihansa, vaan joka peittää vääryyden, se on kavala.","Tyhmä osoittaa kohta vihansa, vaan joka peittää vääryyden, se on kavala."],[12,17,"Joka totuuden puhuu, se vanhurskauden ilmoittaa; mutta joka väärin todistaa, hän pettää.","Joka totuuden puhuu, se vanhurskauden ilmoittaa; mutta joka väärin todistaa, hän pettää."],[12,18,"Joka ajattelematta puhuu, hän pistää niinkuin miekalla; vaan viisasten kieli on terveellinen.","Joka ajattelematta puhuu, hän pistää niinkuin miekalla; vaan viisasten kieli on terveellinen."],[12,19,"Totinen suu pysyy vahvana ijankaikkisesti, vain väärä kieli ei pysy kauvan.","Totinen suu pysyy vahvana ijankaikkisesti, vain väärä kieli ei pysy kauvan."],[12,20,"Jotka pahaa ajattelevat, niiden sydämessä on petos; vaan jotka rauhaa neuvovat, niillä on ilo.","Jotka pahaa ajattelevat, niiden sydämessä on petos; vaan jotka rauhaa neuvovat, niillä on ilo."],[12,21,"Ei vanhurskaalle mitään vaaraa tapahdu; vaan jumalattomat pahuudella täytetään.","Ei vanhurskaalle mitään vaaraa tapahdu; vaan jumalattomat pahuudella täytetään."],[12,22,"Petolliset huulet ovat Herralle kauhistus; vaan jotka oikein tekevät, ovat hänelle otolliset.","Petolliset huulet ovat Herralle kauhistus; vaan jotka oikein tekevät, ovat hänelle otolliset."],[12,23,"Kavala salaa taitonsa, vaan hulluin sydän ilmoittaa hulluutta.","Kavala salaa taitonsa, vaan hulluin sydän ilmoittaa hulluutta."],[12,24,"Ahkera käsi saa hallita, vaan laiskan täytyy veronalaiseksi tulla.","Ahkera käsi saa hallita, vaan laiskan täytyy veronalaiseksi tulla."],[12,25,"Sydämellinen murhe kivistelee, vaan lohdullinen sana iloittaa,","Sydämellinen murhe kivistelee, vaan lohdullinen sana iloittaa,"],[12,26,"Vanhurskas on parempi lähimmäistänsä, mutta jumalattoman tie viettelee hänen","Vanhurskas on parempi lähimmäistänsä, mutta jumalattoman tie viettelee hänen"],[12,27,"Ei petollinen asia menesty, mutta ahkera saa hyvän tavaran.","Ei petollinen asia menesty, mutta ahkera saa hyvän tavaran."],[12,28,"Vanhurskauden tiellä on elämä, ja hänen poluillansa ei ole kuolemaa.","Vanhurskauden tiellä on elämä, ja hänen poluillansa ei ole kuolemaa."],[13,1,"Viisas poika ottaa isänsä kurituksen, mutta pilkkaaja ei tottele rangaistusta.","Viisas poika ottaa isänsä kurituksen, mutta pilkkaaja ei tottele rangaistusta."],[13,2,"Suunsa hedelmästä kukin nautitsee hyvää, vaan jumalattomain sielu vääryyttä.","Suunsa hedelmästä kukin nautitsee hyvää, vaan jumalattomain sielu vääryyttä."],[13,3,"Joka suunsa hallitsee, hän saa elää; vaan joka suunsa toimettomasti avajaa, se tulee hämmästykseen.","Joka suunsa hallitsee, hän saa elää; vaan joka suunsa toimettomasti avajaa, se tulee hämmästykseen."],[13,4,"Laiska pyytää ja ei saa, mutta viriät saavat yltäkylläisesti.","Laiska pyytää ja ei saa, mutta viriät saavat yltäkylläisesti."],[13,5,"Vanhurskas vihaa valhetta, mutta jumalatoin häpäisee ja pilkkaa itsiänsä.","Vanhurskas vihaa valhetta, mutta jumalatoin häpäisee ja pilkkaa itsiänsä."],[13,6,"Vanhurskaus varjelee nuhteettoman, mutta jumalatoin meno kukistaa syntisen.","Vanhurskaus varjelee nuhteettoman, mutta jumalatoin meno kukistaa syntisen."],[13,7,"Moni on köyhä suuressa rikkaudessa, ja moni rikas köyhyydessänsä.","Moni on köyhä suuressa rikkaudessa, ja moni rikas köyhyydessänsä."],[13,8,"Rikkaudellansa taitaa joku lunastaa henkensä; mutta joka köyhä on, ei hän kuule kuritusta.","Rikkaudellansa taitaa joku lunastaa henkensä; mutta joka köyhä on, ei hän kuule kuritusta."],[13,9,"Vanhurskasten valkeus tekee iloiseksi, vaan jumalattomain kynttilä sammuu.","Vanhurskasten valkeus tekee iloiseksi, vaan jumalattomain kynttilä sammuu."],[13,10,"Ylpeiden seassa on aina riita, mutta viisaus saattaa ihmisen toimelliseksi.","Ylpeiden seassa on aina riita, mutta viisaus saattaa ihmisen toimelliseksi."],[13,11,"Rikkaus vähenee tuhlatessa, vaan koossa pitäin se enenee.","Rikkaus vähenee tuhlatessa, vaan koossa pitäin se enenee."],[13,12,"Viivytetty toivo vaivaa sydäntä; vaan kuin se tulee, jota hän toivoo, se on elämän puu.","Viivytetty toivo vaivaa sydäntä; vaan kuin se tulee, jota hän toivoo, se on elämän puu."],[13,13,"Joka sanan katsoo ylön, hän turmelee itsensä; mutta joka käskyä pelkää, hän rauhassa vaeltaa.","Joka sanan katsoo ylön, hän turmelee itsensä; mutta joka käskyä pelkää, hän rauhassa vaeltaa."],[13,14,"Viisaan oppi on elämän lähde, Välttämään kuoleman paulaa.","Viisaan oppi on elämän lähde, Välttämään kuoleman paulaa."],[13,15,"Hyvä neuvo on otollinen; vaan ylönkatsojain tie on kova.","Hyvä neuvo on otollinen; vaan ylönkatsojain tie on kova."],[13,16,"Viisas tekee kaiken toimellisesti, vaan hullu ilmoittaa tyhmyyden.","Viisas tekee kaiken toimellisesti, vaan hullu ilmoittaa tyhmyyden."],[13,17,"Jumalatoin sanansaattaja lankee onnettomuuteen, vaan totinen lähetys on terveellinen.","Jumalatoin sanansaattaja lankee onnettomuuteen, vaan totinen lähetys on terveellinen."],[13,18,"Joka kurituksen hylkää, hänellä on köyhyys ja häpiä; vaan joka antaa itsensä rangaista, hän tulee kunniaan.","Joka kurituksen hylkää, hänellä on köyhyys ja häpiä; vaan joka antaa itsensä rangaista, hän tulee kunniaan."],[13,19,"Kun toivo tulee täytetyksi, niin sydän iloitsee; mutta joka pahuutta välttää; on hulluille kauhistukseksi.","Kun toivo tulee täytetyksi, niin sydän iloitsee; mutta joka pahuutta välttää; on hulluille kauhistukseksi."],[13,20,"Joka viisasten kanssa käyskentelee, hän tulee viisaaksi; vaan joka hulluin kumppani on, hän tulee vahinkoon.","Joka viisasten kanssa käyskentelee, hän tulee viisaaksi; vaan joka hulluin kumppani on, hän tulee vahinkoon."],[13,21,"Pahuus noudattaa syntisiä, mutta vanhurskaille kostetaan hyvyydellä.","Pahuus noudattaa syntisiä, mutta vanhurskaille kostetaan hyvyydellä."],[13,22,"Hyvällä on perilliset lasten lapsissa; vaan syntisen tavara vanhurskaalle säästetään.","Hyvällä on perilliset lasten lapsissa; vaan syntisen tavara vanhurskaalle säästetään."],[13,23,"Paljo ruokaa on köyhän kynnössä; vaan jotka vääryyttä tekevät, ne hukkuvat.","Paljo ruokaa on köyhän kynnössä; vaan jotka vääryyttä tekevät, ne hukkuvat."],[13,24,"Joka vitsaansa säästää, hän vihaa lastansa; vaan joka häntä rakastaa, hän aikanansa sitä kurittaa.","Joka vitsaansa säästää, hän vihaa lastansa; vaan joka häntä rakastaa, hän aikanansa sitä kurittaa."],[13,25,"Vanhurskas syö, että hänen sielunsa ravittaisiin; vaan jumalattomain vatsa on tyytymätöin.","Vanhurskas syö, että hänen sielunsa ravittaisiin; vaan jumalattomain vatsa on tyytymätöin."],[14,1,"Viisas vaimo rakentaa huoneensa, vaan hullu kukistaa sen teollansa.","Viisas vaimo rakentaa huoneensa, vaan hullu kukistaa sen teollansa."],[14,2,"Joka vaeltaa oikiaa tietä, se pelkää Herraa; mutta se, joka poikkee pois tieltänsä, ylönkatsoo hänen.","Joka vaeltaa oikiaa tietä, se pelkää Herraa; mutta se, joka poikkee pois tieltänsä, ylönkatsoo hänen."],[14,3,"Tyhmän suussa on ylpeyden vitsa; vaan viisasten huulet varjelevat heitä.","Tyhmän suussa on ylpeyden vitsa; vaan viisasten huulet varjelevat heitä."],[14,4,"Jossa ei härkiä ole, siinä seimet puhtaana ovat; vaan jossa juhdat työtä tekevät, siinä tuloa kyllä on.","Jossa ei härkiä ole, siinä seimet puhtaana ovat; vaan jossa juhdat työtä tekevät, siinä tuloa kyllä on."],[14,5,"Totinen todistaja välttää valhetta; vaan väärä todistaja rohkiasti valhettelee.","Totinen todistaja välttää valhetta; vaan väärä todistaja rohkiasti valhettelee."],[14,6,"Pilkkaaja etsii viisautta, ja ei löydä; vaan toimelliset viisauden huokiasti saavat.","Pilkkaaja etsii viisautta, ja ei löydä; vaan toimelliset viisauden huokiasti saavat."],[14,7,"Mene pois tyhmän tyköä; sillä et sinä opi mitään häneltä.","Mene pois tyhmän tyköä; sillä et sinä opi mitään häneltä."],[14,8,"Toimellisen viisaus on teistänsä ottaa vaarin; vaan tyhmäin hulluus on sula petos.","Toimellisen viisaus on teistänsä ottaa vaarin; vaan tyhmäin hulluus on sula petos."],[14,9,"Tyhmä nauraa syntiä, mutta hurskasten välillä on hyvä suosio.","Tyhmä nauraa syntiä, mutta hurskasten välillä on hyvä suosio."],[14,10,"Koska sydän on murheellinen, niin ei auta ulkonainen ilo.","Koska sydän on murheellinen, niin ei auta ulkonainen ilo."],[14,11,"Jumalattomain huoneet kukistetaan, vaan jumalisten majat viheriöitsevät.","Jumalattomain huoneet kukistetaan, vaan jumalisten majat viheriöitsevät."],[14,12,"Monella on tie mielestänsä oikia, vaan viimeiseltä johdattaa se kuolemaan.","Monella on tie mielestänsä oikia, vaan viimeiseltä johdattaa se kuolemaan."],[14,13,"Naurun jälkeen tulee murhe, ja ilon perästä suru.","Naurun jälkeen tulee murhe, ja ilon perästä suru."],[14,14,"Tyhmälle tapahtuu laittamisensa jälkeen, vaan hyvä ihminen asetetaan hänen ylitsensä.","Tyhmälle tapahtuu laittamisensa jälkeen, vaan hyvä ihminen asetetaan hänen ylitsensä."],[14,15,"Taitamatoin uskoo kaikki, mutta ymmärtäväinen ottaa teistänsä vaarin.","Taitamatoin uskoo kaikki, mutta ymmärtäväinen ottaa teistänsä vaarin."],[14,16,"Viisas pelkää ja karttaa pahaa, vaan tyhmä päätähavin menee.","Viisas pelkää ja karttaa pahaa, vaan tyhmä päätähavin menee."],[14,17,"Äkillinen ihminen tekee hullun töitä, ja kavala ihminen tulee vihattavaksi.","Äkillinen ihminen tekee hullun töitä, ja kavala ihminen tulee vihattavaksi."],[14,18,"Taitamattomat perivät tyhmyyden; vaan se on toimellisten kruunu, että he toimellisesti tekevät.","Taitamattomat perivät tyhmyyden; vaan se on toimellisten kruunu, että he toimellisesti tekevät."],[14,19,"Häijyn täytyy kumartaa hyviä, ja jumalattomat vanhurskasten porteissa.","Häijyn täytyy kumartaa hyviä, ja jumalattomat vanhurskasten porteissa."],[14,20,"Köyhää vihaavat hänen lähimmäisensäkin; vaan rikkaalla on monta ystävää.","Köyhää vihaavat hänen lähimmäisensäkin; vaan rikkaalla on monta ystävää."],[14,21,"Joka katsoo lähimmäisensä ylön. hän tekee syntiä; vaan autuas on se, joka viheliäistä armahtaa.","Joka katsoo lähimmäisensä ylön. hän tekee syntiä; vaan autuas on se, joka viheliäistä armahtaa."],[14,22,"Jotka viekkaudessa vaeltavat, niiltä puuttuu; mutta jotka hyvää ajattelevat, niille tapahtuu hyvyys ja uskollisuus.","Jotka viekkaudessa vaeltavat, niiltä puuttuu; mutta jotka hyvää ajattelevat, niille tapahtuu hyvyys ja uskollisuus."],[14,23,"Jossa työtä tehdään, siinä kyllä on; vaan joka tyhjiin puheisiin tyytyy, siinä on köyhyys.","Jossa työtä tehdään, siinä kyllä on; vaan joka tyhjiin puheisiin tyytyy, siinä on köyhyys."],[14,24,"Viisasten rikkaus on heidän kruununsa, mutta tyhmäin hulluus on hulluus.","Viisasten rikkaus on heidän kruununsa, mutta tyhmäin hulluus on hulluus."],[14,25,"Uskollinen todistaja vapahtaa hengen, vaan väärä todistaja pettää.","Uskollinen todistaja vapahtaa hengen, vaan väärä todistaja pettää."],[14,26,"Joka Herraa pelkää, hänellä on vahva linna, ja hänen lapsensa varjellaan.","Joka Herraa pelkää, hänellä on vahva linna, ja hänen lapsensa varjellaan."],[14,27,"Herran pelko on elämän lähde, että kuoleman nuora välttää taidetaan.","Herran pelko on elämän lähde, että kuoleman nuora välttää taidetaan."],[14,28,"Koska kuninkaalla on paljo väkeä, se on hänen kunniansa; vaan koska vähä on väkeä, se tekee päämiehen kehnoksi.","Koska kuninkaalla on paljo väkeä, se on hänen kunniansa; vaan koska vähä on väkeä, se tekee päämiehen kehnoksi."],[14,29,"Joka on pitkämielinen, se on viisas; vaan joka äkillinen on, se ilmoittaa tyhmyyden.","Joka on pitkämielinen, se on viisas; vaan joka äkillinen on, se ilmoittaa tyhmyyden."],[14,30,"Leppyinen sydän on ruumiin elämä; vaan kateus on märkä luissa.","Leppyinen sydän on ruumiin elämä; vaan kateus on märkä luissa."],[14,31,"Joka köyhälle tekee väkivaltaa, hän laittaa hänen luojaansa; vaan joka armahtaa vaivaista, se kunnioittaa Jumalaa.","Joka köyhälle tekee väkivaltaa, hän laittaa hänen luojaansa; vaan joka armahtaa vaivaista, se kunnioittaa Jumalaa."],[14,32,"Pahuutensa tähden jumalatoin kukistetaan; vaan vanhurskas on kuolemassakin rohkia.","Pahuutensa tähden jumalatoin kukistetaan; vaan vanhurskas on kuolemassakin rohkia."],[14,33,"Toimellisen sydämessä lepää viisaus; mutta mitä tyhmäin mielessä on, se tulee ilmi.","Toimellisen sydämessä lepää viisaus; mutta mitä tyhmäin mielessä on, se tulee ilmi."],[14,34,"Vanhurskaus korottaa kansan, vaan synti on kansan häpiä.","Vanhurskaus korottaa kansan, vaan synti on kansan häpiä."],[14,35,"Toimellinen palvelia on kuninkaalle otollinen; vaan häpiällistä palveliaa ei hän kärsi.","Toimellinen palvelia on kuninkaalle otollinen; vaan häpiällistä palveliaa ei hän kärsi."],[15,1,"Suloinen vastaus hillitse vihan, mutta kova sana saattaa mielen karvaaksi.","Suloinen vastaus hillitse vihan, mutta kova sana saattaa mielen karvaaksi."],[15,2,"Viisasten kieli saattaa opetuksen suloiseksi, vaan tyhmäin suu aina hulluuta sylkee.","Viisasten kieli saattaa opetuksen suloiseksi, vaan tyhmäin suu aina hulluuta sylkee."],[15,3,"Herran silmät katselevat joka paikassa, sekä pahat että hyvät.","Herran silmät katselevat joka paikassa, sekä pahat että hyvät."],[15,4,"Terveellinen kieli on elämän puu: vaan valhettelevainen saattaa sydämen kivun.","Terveellinen kieli on elämän puu: vaan valhettelevainen saattaa sydämen kivun."],[15,5,"Tyhmä laittaa isänsä kurituksen; vaan joka rangaistuksen ottaa, hän tulee taitavaksi.","Tyhmä laittaa isänsä kurituksen; vaan joka rangaistuksen ottaa, hän tulee taitavaksi."],[15,6,"Vanhurskaan huoneessa on yltäkyllä; vaan jumalattoman saalis on hävintö.","Vanhurskaan huoneessa on yltäkyllä; vaan jumalattoman saalis on hävintö."],[15,7,"Viisasten huulet jakavat neuvoa; vaan tyhmäin sydän ei ole niin.","Viisasten huulet jakavat neuvoa; vaan tyhmäin sydän ei ole niin."],[15,8,"Jumalattoman uhri on Herralle kauhistus; vaan jumalisten rukous on hänelle otollinen.","Jumalattoman uhri on Herralle kauhistus; vaan jumalisten rukous on hänelle otollinen."],[15,9,"Jumalattoman tie on Herralle kauhistus; vaan joka vanhursjautta noudattaa, on hänelle rakas.","Jumalattoman tie on Herralle kauhistus; vaan joka vanhursjautta noudattaa, on hänelle rakas."],[15,10,"Kuritus on sille paha, joka hylkää tiensä: ja joka rangaistusta vihaa, hänen pitää kuoleman.","Kuritus on sille paha, joka hylkää tiensä: ja joka rangaistusta vihaa, hänen pitää kuoleman."],[15,11,"Helvetti ja kadotus on Herran edessä: kunka paljon enemmin ihmisten lasten sydämet.","Helvetti ja kadotus on Herran edessä: kunka paljon enemmin ihmisten lasten sydämet."],[15,12,"Ei pilkkaaja rakasta sitä, joka häntä rankaisee, ja ei hän mene viisasten tykö.","Ei pilkkaaja rakasta sitä, joka häntä rankaisee, ja ei hän mene viisasten tykö."],[15,13,"Iloinen sydän tekee iloiset kasvot; vaan koska sydän on surullinen, niin rohkeus raukee.","Iloinen sydän tekee iloiset kasvot; vaan koska sydän on surullinen, niin rohkeus raukee."],[15,14,"Ymmärtäväinen sydän etsii viisautta; vaan tyhmäin suu tyhmyydellä ravitaan.","Ymmärtäväinen sydän etsii viisautta; vaan tyhmäin suu tyhmyydellä ravitaan."],[15,15,"Surullisella ihmisellä ei ole koskaan hyvää päivää; vaan jolla hyvä sydän on, hänellä on joka päivä vieraspito.","Surullisella ihmisellä ei ole koskaan hyvää päivää; vaan jolla hyvä sydän on, hänellä on joka päivä vieraspito."],[15,16,"Parempi on vähä Herran pelvossa, kuin suuri tavara ilman lepoa.","Parempi on vähä Herran pelvossa, kuin suuri tavara ilman lepoa."],[15,17,"Parempi on ateria kaalia rakkaudessa, kuin syötetty härkä vihassa.","Parempi on ateria kaalia rakkaudessa, kuin syötetty härkä vihassa."],[15,18,"Vihainen mies saattaa toran matkaan; mutta kärsivällinen asettaa riidan.","Vihainen mies saattaa toran matkaan; mutta kärsivällinen asettaa riidan."],[15,19,"Laiskan tie on orjantappurainen; vaan hurskasten tie on tasainen.","Laiskan tie on orjantappurainen; vaan hurskasten tie on tasainen."],[15,20,"Viisas poika iloittaa isänsä, ja hullu ihminen häpäisee äitinsä.","Viisas poika iloittaa isänsä, ja hullu ihminen häpäisee äitinsä."],[15,21,"Hulluulle on tyhmyys iloksi; vaan toimellinen mies pysyy oikialla tiellä.","Hulluulle on tyhmyys iloksi; vaan toimellinen mies pysyy oikialla tiellä."],[15,22,"Aivoitus raukee ilman neuvoaa; vaan jossa monta neuvonantajaa on, se on vahva.","Aivoitus raukee ilman neuvoaa; vaan jossa monta neuvonantajaa on, se on vahva."],[15,23,"Se on ihmisen ilo, että hän toimella vastata taitaa, ja aikanansa sanottu sana on otollinen.","Se on ihmisen ilo, että hän toimella vastata taitaa, ja aikanansa sanottu sana on otollinen."],[15,24,"Elämän tie johdattaa viisaan ylöspäin, välttämään helvettiä, joka alhaalla on.","Elämän tie johdattaa viisaan ylöspäin, välttämään helvettiä, joka alhaalla on."],[15,25,"Herra ylpeiden huoneet kukistaa, ja vahvistaa lesken rajat.","Herra ylpeiden huoneet kukistaa, ja vahvistaa lesken rajat."],[15,26,"Ilkiäin aivoitukset ovat Herralle kauhistukseksi; vaan toimellinen puhe on otollinen.","Ilkiäin aivoitukset ovat Herralle kauhistukseksi; vaan toimellinen puhe on otollinen."],[15,27,"Ahneudella voitetut kukistavat oman huoneensa; vaan joka lahjoja vihaa, saa elää.","Ahneudella voitetut kukistavat oman huoneensa; vaan joka lahjoja vihaa, saa elää."],[15,28,"Vanhurskaan sydän ajattelee vastausta; vaan jumalattoman suu ammuntaa pahaa.","Vanhurskaan sydän ajattelee vastausta; vaan jumalattoman suu ammuntaa pahaa."],[15,29,"Herra on kaukana jumalattomista; vaan hän kuulee vanhurskasten rukoukset.","Herra on kaukana jumalattomista; vaan hän kuulee vanhurskasten rukoukset."],[15,30,"Suloinen kasvo iloittaa sydämen: hyvä sanoma tekee luut lihaviksi.","Suloinen kasvo iloittaa sydämen: hyvä sanoma tekee luut lihaviksi."],[15,31,"Korva, joka kuulee elämän rangaistusta, on asuva viisasten seassa.","Korva, joka kuulee elämän rangaistusta, on asuva viisasten seassa."],[15,32,"Joka ei itsiänsä salli kurittaa, se katsoo ylön sielunsa; vaan joka rangaistusta kuulee, hän tulee viisaaksi.","Joka ei itsiänsä salli kurittaa, se katsoo ylön sielunsa; vaan joka rangaistusta kuulee, hän tulee viisaaksi."],[15,33,"Herran pelko on kuritus viisauteen, ja kunnian edellä käy nöyryys.","Herran pelko on kuritus viisauteen, ja kunnian edellä käy nöyryys."],[16,1,"Ihminen aikoo sydämessänsä; vaan Herralta tulee kielen vastaus.","Ihminen aikoo sydämessänsä; vaan Herralta tulee kielen vastaus."],[16,2,"Jokaisen mielestä on hänen tiensä puhdas; mutta Herra tutkistelee sydämet.","Jokaisen mielestä on hänen tiensä puhdas; mutta Herra tutkistelee sydämet."],[16,3,"Anna Herran haltuun sinun työs, niin sinun aivoitukses menestyy.","Anna Herran haltuun sinun työs, niin sinun aivoitukses menestyy."],[16,4,"Herra tekee kaikki itse tähtensä, niin myös jumalattoman pahaksi päiväksi.","Herra tekee kaikki itse tähtensä, niin myös jumalattoman pahaksi päiväksi."],[16,5,"Jokainen ylpiä on Herralle kauhistus, ja ei pääse rankaisematta, ehkä he kaikki yhtä pitäisivät.","Jokainen ylpiä on Herralle kauhistus, ja ei pääse rankaisematta, ehkä he kaikki yhtä pitäisivät."],[16,6,"Laupiuden ja totuuden kautta pahateko sovitetaan, ja Herran pelvolla paha vältetään.","Laupiuden ja totuuden kautta pahateko sovitetaan, ja Herran pelvolla paha vältetään."],[16,7,"Jos jonkun tiet ovat Herralle kelvolliset, niin hän myös kääntää hänen vihamiehensä rauhaan.","Jos jonkun tiet ovat Herralle kelvolliset, niin hän myös kääntää hänen vihamiehensä rauhaan."],[16,8,"Parempi on vähä vanhurskaudessa, kuin suuri saalis vääryydessä.","Parempi on vähä vanhurskaudessa, kuin suuri saalis vääryydessä."],[16,9,"Ihmisen sydän aikoo tiensä; vaan Herra johdattaa hänen käymisensä.","Ihmisen sydän aikoo tiensä; vaan Herra johdattaa hänen käymisensä."],[16,10,"Ennustus on kuninkaan huulissa: ei hänen suunsa puhu tuomiossa väärin.","Ennustus on kuninkaan huulissa: ei hänen suunsa puhu tuomiossa väärin."],[16,11,"Oikia puntari ja vaaka on Herralta, ja kaikki painokivet kukkarossa ovat hänen tekoansa.","Oikia puntari ja vaaka on Herralta, ja kaikki painokivet kukkarossa ovat hänen tekoansa."],[16,12,"Kuninkaan edessä on kauhistus väärin tehdä; sillä vanhurskaudella istuin vahvistetaan.","Kuninkaan edessä on kauhistus väärin tehdä; sillä vanhurskaudella istuin vahvistetaan."],[16,13,"Oikia neuvo on kuninkaalle otollinen; ja joka oikein puhuu, häntä rakastetaan.","Oikia neuvo on kuninkaalle otollinen; ja joka oikein puhuu, häntä rakastetaan."],[16,14,"Kuninkaan viha on kuoleman sanansaattaja; ja viisas mies lepyttää hänen.","Kuninkaan viha on kuoleman sanansaattaja; ja viisas mies lepyttää hänen."],[16,15,"Kuin kuninkaan kasvo on leppyinen, siinä on elämä, ja hänen armonsa on niinkuin hiljainen sade.","Kuin kuninkaan kasvo on leppyinen, siinä on elämä, ja hänen armonsa on niinkuin hiljainen sade."],[16,16,"Ota viisautta tykös, sillä se on parempi kultaa: ja saada ymmärrystä on kalliimpi hopiaa.","Ota viisautta tykös, sillä se on parempi kultaa: ja saada ymmärrystä on kalliimpi hopiaa."],[16,17,"Siviän tiet välttävät pahaa, ja joka sielunsa varjelee, se tiestänsä ottaa vaarin.","Siviän tiet välttävät pahaa, ja joka sielunsa varjelee, se tiestänsä ottaa vaarin."],[16,18,"Joka alennetaan, se ensisti tulee ylpiäksi; ja ylpeys on aina lankeemuksen edellä.","Joka alennetaan, se ensisti tulee ylpiäksi; ja ylpeys on aina lankeemuksen edellä."],[16,19,"Parempi on nöyränä olla siveiden kanssa, kuin jakaa suurta saalista ylpeiden kanssa.","Parempi on nöyränä olla siveiden kanssa, kuin jakaa suurta saalista ylpeiden kanssa."],[16,20,"Joka jonkun asian viisaasti alkaa, hän löytää onnen; ja se on autuas, joka luottaa Herraan.","Joka jonkun asian viisaasti alkaa, hän löytää onnen; ja se on autuas, joka luottaa Herraan."],[16,21,"Toimellinen mies ylistetään viisautensa tähden; ja suloinen puhe lisää oppia.","Toimellinen mies ylistetään viisautensa tähden; ja suloinen puhe lisää oppia."],[16,22,"Viisaus on elämän lähde hänelle, joka sen saanut on, vaan tyhmäin oppi on hulluus.","Viisaus on elämän lähde hänelle, joka sen saanut on, vaan tyhmäin oppi on hulluus."],[16,23,"Viisas sydän puhuu toimellisesti, ja hänen huulensa opettavat hyvin.","Viisas sydän puhuu toimellisesti, ja hänen huulensa opettavat hyvin."],[16,24,"Suloiset sanat ovat mesileipää; ne lohduttavat sielua, ja virvoittavat luut.","Suloiset sanat ovat mesileipää; ne lohduttavat sielua, ja virvoittavat luut."],[16,25,"Monella on tie mielestänsä oikia, vaan se johdattaa viimein kuolemaan.","Monella on tie mielestänsä oikia, vaan se johdattaa viimein kuolemaan."],[16,26,"Moni tulee suureen vahinkoon oman suunsa kautta.","Moni tulee suureen vahinkoon oman suunsa kautta."],[16,27,"Jumalatoin ihminen kaivaa onnettomuutta, ja hänen suussansa palaa niinkuin tuli.","Jumalatoin ihminen kaivaa onnettomuutta, ja hänen suussansa palaa niinkuin tuli."],[16,28,"Väärä ihminen saattaa riidan, ja panettelia tekee ruhtinaat eripuraisiksi.","Väärä ihminen saattaa riidan, ja panettelia tekee ruhtinaat eripuraisiksi."],[16,29,"Viekas ihminen houkuttelee lähimmäistänsä, ja johdattaa hänen pahalle tielle.","Viekas ihminen houkuttelee lähimmäistänsä, ja johdattaa hänen pahalle tielle."],[16,30,"Joka silmää iskee, ei se hyvää ajattele, ja joka huuliansa pureskelee, se pahaa matkaan saattaa.","Joka silmää iskee, ei se hyvää ajattele, ja joka huuliansa pureskelee, se pahaa matkaan saattaa."],[16,31,"Harmaat hiukset ovat kunnian kruunu, joka löydetään vanhurskauden tiellä.","Harmaat hiukset ovat kunnian kruunu, joka löydetään vanhurskauden tiellä."],[16,32,"Kärsivällinen on parempi kuin väkevä; ja joka hillitsee mielensä, on parempi, kuin se joka kaupungin voittaa.","Kärsivällinen on parempi kuin väkevä; ja joka hillitsee mielensä, on parempi, kuin se joka kaupungin voittaa."],[16,33,"Arpa heitetään syliin, vaan Herralta tulee kaikki sen meno.","Arpa heitetään syliin, vaan Herralta tulee kaikki sen meno."],[17,1,"Kuiva pala, siinä jossa rauha on, on parempi kuin huone teurasta täynnä riidassa.","Kuiva pala, siinä jossa rauha on, on parempi kuin huone teurasta täynnä riidassa."],[17,2,"Toimellinen palvelia hallitsee häpiällisiä lapsia, ja hän jakaa perintöä veljein välillä.","Toimellinen palvelia hallitsee häpiällisiä lapsia, ja hän jakaa perintöä veljein välillä."],[17,3,"Niinkuin tuli koettelee hopian ja ahjo kullan, niin Herra tutkistelee sydämet.","Niinkuin tuli koettelee hopian ja ahjo kullan, niin Herra tutkistelee sydämet."],[17,4,"Paha ottaa pahoista suista vaarin, ja petollinen kuuntelee mielellänsä vahingollista kieltä.","Paha ottaa pahoista suista vaarin, ja petollinen kuuntelee mielellänsä vahingollista kieltä."],[17,5,"Joka köyhää syljeskelee, se häpäisee Luojaansa; ja joka iloitsee toisen vahingosta, ei pääse rankaisematta.","Joka köyhää syljeskelee, se häpäisee Luojaansa; ja joka iloitsee toisen vahingosta, ei pääse rankaisematta."],[17,6,"vanhain kruunu ovat lasten lapset, ja lasten kunnia ovat heidän isänsä.","vanhain kruunu ovat lasten lapset, ja lasten kunnia ovat heidän isänsä."],[17,7,"Ei sovi tyhmäin puhua korkeista asioista, paljoa vähemmin päämiehen valhetella.","Ei sovi tyhmäin puhua korkeista asioista, paljoa vähemmin päämiehen valhetella."],[17,8,"Jolla vara on lahja antaa, se on niinkuin kallis kivi: kuhunka hän itsensä kääntää, niin hän viisaana pidetään.","Jolla vara on lahja antaa, se on niinkuin kallis kivi: kuhunka hän itsensä kääntää, niin hän viisaana pidetään."],[17,9,"Joka syntiä peittää, se saattaa itsellensä ystävyyden; vaan joka asian ilmoittaa, se saattaa ruhtinaat eripuraisiksi.","Joka syntiä peittää, se saattaa itsellensä ystävyyden; vaan joka asian ilmoittaa, se saattaa ruhtinaat eripuraisiksi."],[17,10,"Sanat vaikuttavat enemmän toimellisen tykönä, kuin sata haavaa tyhmän tykönä.","Sanat vaikuttavat enemmän toimellisen tykönä, kuin sata haavaa tyhmän tykönä."],[17,11,"Niskuri tosin etsii vahinkoa, vaan julma enkeli lähetetään häntä vastaan.","Niskuri tosin etsii vahinkoa, vaan julma enkeli lähetetään häntä vastaan."],[17,12,"Parempi on kohdata karhua, jolta pojat ovat otetut pois, kuin hullua hulluudessansa.","Parempi on kohdata karhua, jolta pojat ovat otetut pois, kuin hullua hulluudessansa."],[17,13,"Joka kostaa hyvän pahalla, ei hänen huoneestansa pidä pahuus luopuman.","Joka kostaa hyvän pahalla, ei hänen huoneestansa pidä pahuus luopuman."],[17,14,"Riidan alku on niinkuin vewsi, joka itsensä leikkaa ulos: lakkaa riidasta ennenkuin sinä siihen sekaannut.","Riidan alku on niinkuin vewsi, joka itsensä leikkaa ulos: lakkaa riidasta ennenkuin sinä siihen sekaannut."],[17,15,"Joka jumalattoman hurskaaksi sanoo, ja joka vanhurskaan soimaa jumalattomaksi, ne molemmat ovat Herralle kauhistus.","Joka jumalattoman hurskaaksi sanoo, ja joka vanhurskaan soimaa jumalattomaksi, ne molemmat ovat Herralle kauhistus."],[17,16,"Mitä tyhmä tekee kädessänsä rahalla, ettei hänellä ole sydäntä ostaa viisautta?","Mitä tyhmä tekee kädessänsä rahalla, ettei hänellä ole sydäntä ostaa viisautta?"],[17,17,"Ystävä rakastaa ainian, ja veli tulee julki hädässä.","Ystävä rakastaa ainian, ja veli tulee julki hädässä."],[17,18,"Se on tyhmä ihminen, joka kätensä taritsee, ja takaa lähimmäisensä.","Se on tyhmä ihminen, joka kätensä taritsee, ja takaa lähimmäisensä."],[17,19,"Joka toraa rakastaa, se rakastaa syntiä; ja joka ovensa korottaa, se etsii onnettomuutta.","Joka toraa rakastaa, se rakastaa syntiä; ja joka ovensa korottaa, se etsii onnettomuutta."],[17,20,"Häijy sydän ei löydä mitään hyvää; ja jolla paha kieli on, se lankee onnettomuuteen.","Häijy sydän ei löydä mitään hyvää; ja jolla paha kieli on, se lankee onnettomuuteen."],[17,21,"Joka tyhmän synnyttää, hänellä on murhe, ja tyhmän isällä ei ole iloa.","Joka tyhmän synnyttää, hänellä on murhe, ja tyhmän isällä ei ole iloa."],[17,22,"Iloinen sydän tekee elämän suloiseksi, vaan surullinen sydän kaivaa luut.","Iloinen sydän tekee elämän suloiseksi, vaan surullinen sydän kaivaa luut."],[17,23,"Jumalatoin ottaa mielellänsä salaisesti lahjoja, mutkataksensa lain teitä.","Jumalatoin ottaa mielellänsä salaisesti lahjoja, mutkataksensa lain teitä."],[17,24,"Toimellinen mies laittaa itsensä viisaasti, vaan tyhmä heittelee silmiänsä sinne ja tänne.","Toimellinen mies laittaa itsensä viisaasti, vaan tyhmä heittelee silmiänsä sinne ja tänne."],[17,25,"Hullu popika on isänsä suru, ja äidillensä murhe, joka hänen synnyttänyt on.","Hullu popika on isänsä suru, ja äidillensä murhe, joka hänen synnyttänyt on."],[17,26,"Ei ole se hyvä, että vanhurskalle tehdään väärin, taikka että sitä ruhtinasta lyödään, joka oikein tuomitsee.","Ei ole se hyvä, että vanhurskalle tehdään väärin, taikka että sitä ruhtinasta lyödään, joka oikein tuomitsee."],[17,27,"Toimellinen mies taitaa puheensa tallella pitää, ja taitava mies on kallis sielu.","Toimellinen mies taitaa puheensa tallella pitää, ja taitava mies on kallis sielu."],[17,28,"Jos tyhmä vaiti olis, niin hän viisaaksi luettaisiin, ja toimelliseksi, jos hän suunsa pitäis kiinni.","Jos tyhmä vaiti olis, niin hän viisaaksi luettaisiin, ja toimelliseksi, jos hän suunsa pitäis kiinni."],[18,1,"Eripurainen etsii mitä hänelle kelpaa, ja sekoittaa itsensä kaikkiin asioihin.","Eripurainen etsii mitä hänelle kelpaa, ja sekoittaa itsensä kaikkiin asioihin."],[18,2,"Tyhmällä ei ole himo ymmärrykseen, vaan niitä ilmoittamaan, mitkä ovat hänen sydämessänsä.","Tyhmällä ei ole himo ymmärrykseen, vaan niitä ilmoittamaan, mitkä ovat hänen sydämessänsä."],[18,3,"Jumalattoman tullessa tulee ylönkatse, pilkka ja häpiä.","Jumalattoman tullessa tulee ylönkatse, pilkka ja häpiä."],[18,4,"Sanat ihmisen suussa ovat niinkuin syvät vedet, ja viisauden lähde on täynnä virtaa.","Sanat ihmisen suussa ovat niinkuin syvät vedet, ja viisauden lähde on täynnä virtaa."],[18,5,"Ei ole hyvä katsoa jumalattomain muotoa, ja sortaa vanhurskasta tuomiossa.","Ei ole hyvä katsoa jumalattomain muotoa, ja sortaa vanhurskasta tuomiossa."],[18,6,"Tyhmän huulet saattavat toran, ja hänen suunsa noudattaa haavoja.","Tyhmän huulet saattavat toran, ja hänen suunsa noudattaa haavoja."],[18,7,"Tyhmän suu häpäisee itsensä, ja hänen huulensa ovat paula omalle omalle sielulle.","Tyhmän suu häpäisee itsensä, ja hänen huulensa ovat paula omalle omalle sielulle."],[18,8,"Panetteian sanat ovat haavat, ja käyvät läpi sydämen.","Panetteian sanat ovat haavat, ja käyvät läpi sydämen."],[18,9,"Joka laiska on työssänsä, hän on sen veli, joka vahinkoa tekee.","Joka laiska on työssänsä, hän on sen veli, joka vahinkoa tekee."],[18,10,"Herran nimi on vahva linna: vanhurskas juoksee sinne, ja tulee varjelluksi.","Herran nimi on vahva linna: vanhurskas juoksee sinne, ja tulee varjelluksi."],[18,11,"Rikkaan tavara on hänelle vahva kaupunki, ja niinkuin korkea muuri hänen mielestänsä.","Rikkaan tavara on hänelle vahva kaupunki, ja niinkuin korkea muuri hänen mielestänsä."],[18,12,"Kuin joku lankee, niin hänen sydämensä ensisti tulee ylpiäksi, ja ennenkuin joku kunniaan tulee, pitää hänen nöyrän oleman..","Kuin joku lankee, niin hänen sydämensä ensisti tulee ylpiäksi, ja ennenkuin joku kunniaan tulee, pitää hänen nöyrän oleman.."],[18,13,"Joka vastaa ennekuin hän kuulee, se on hänelle hulluudeksi ja häpiäksi.","Joka vastaa ennekuin hän kuulee, se on hänelle hulluudeksi ja häpiäksi."],[18,14,"Ihmisen henki pitää ylös hänen heikkoutensa; vaan murheellista henkeä kuka voi kärsiä?","Ihmisen henki pitää ylös hänen heikkoutensa; vaan murheellista henkeä kuka voi kärsiä?"],[18,15,"Ymmärtäväinen sydän saa viisauden, ja viisasten korva etsii taitoa.","Ymmärtäväinen sydän saa viisauden, ja viisasten korva etsii taitoa."],[18,16,"Ihmisen lahja tekee hänelle avaran sian, ja saattaa suurten herrain eteen.","Ihmisen lahja tekee hänelle avaran sian, ja saattaa suurten herrain eteen."],[18,17,"Jokaisella on ensisti omassa asiassansa oikeus; vaan kuin hänen lähimmäisensä tulee, niin se löydetäään.","Jokaisella on ensisti omassa asiassansa oikeus; vaan kuin hänen lähimmäisensä tulee, niin se löydetäään."],[18,18,"Arpa asettaa riidan, ja eroitaa voimallisten vaiheella.","Arpa asettaa riidan, ja eroitaa voimallisten vaiheella."],[18,19,"Vihoitettu veli pitää puoltansa lujemmin kuin vahva kaupunki; ja riita pitää kovemmin puolensa kuin telki linnan edessä.","Vihoitettu veli pitää puoltansa lujemmin kuin vahva kaupunki; ja riita pitää kovemmin puolensa kuin telki linnan edessä."],[18,20,"Sen jälkeen kullekin maksetaan, kuin hänen suunsa on puhunut; ja hän ravitaan huultensa hedelmästä.","Sen jälkeen kullekin maksetaan, kuin hänen suunsa on puhunut; ja hän ravitaan huultensa hedelmästä."],[18,21,"Kuolema ja elämä on kielen voimassa: joka häntä rakastaa, se saa syösä hänen hedelmästänsä.","Kuolema ja elämä on kielen voimassa: joka häntä rakastaa, se saa syösä hänen hedelmästänsä."],[18,22,"Joka aviovaimon osaa, hän löytäää hyvän kappaleen, ja saa mielisuosionsa Herralta.","Joka aviovaimon osaa, hän löytäää hyvän kappaleen, ja saa mielisuosionsa Herralta."],[18,23,"Köyhä mies puhuu nöyrästi, vaan rikas vastaa ylpiästi.","Köyhä mies puhuu nöyrästi, vaan rikas vastaa ylpiästi."],[18,24,"Ihminen, jolla on ystävä, pitää oleman ystävällinen; sillä ystävä pitää lujemmin hänen kanssansa kuin veli.","Ihminen, jolla on ystävä, pitää oleman ystävällinen; sillä ystävä pitää lujemmin hänen kanssansa kuin veli."],[19,1,"Köyhä joka siveydessä vaeltaa, on parempi kuin väärä huulissansa, joka kuitenkin tyhmä on.","Köyhä joka siveydessä vaeltaa, on parempi kuin väärä huulissansa, joka kuitenkin tyhmä on."],[19,2,"Joka ei toimella laita, ei hänelle hyvin käy; ja joka on nopsa jaloista, se loukkaa itsensä.","Joka ei toimella laita, ei hänelle hyvin käy; ja joka on nopsa jaloista, se loukkaa itsensä."],[19,3,"Ihmisen tyhmyys eksyttää hänen tiensä, niin että hänen sydämensä vihastuu Herraa vastaan.","Ihmisen tyhmyys eksyttää hänen tiensä, niin että hänen sydämensä vihastuu Herraa vastaan."],[19,4,"Tavara tekee monta ystävää, vaan köyhä hyljätään ystäviltä.","Tavara tekee monta ystävää, vaan köyhä hyljätään ystäviltä."],[19,5,"Ei väärä todistaja pidä pääsemän rankaisematta; joka rohkiasti valehtelee, ei hänen pidä selkeemän.","Ei väärä todistaja pidä pääsemän rankaisematta; joka rohkiasti valehtelee, ei hänen pidä selkeemän."],[19,6,"Moni rukoilee päämiestä, ja jokainen on hänen ystävänsä, joka lahjoja jakaa.","Moni rukoilee päämiestä, ja jokainen on hänen ystävänsä, joka lahjoja jakaa."],[19,7,"Köyhää vihaavat kaikki hänen veljensä, ja hänen ystävänsä vetäytyvät taamma hänestä; ja joka sanoihin luottaa, ei hän saa mitään.","Köyhää vihaavat kaikki hänen veljensä, ja hänen ystävänsä vetäytyvät taamma hänestä; ja joka sanoihin luottaa, ei hän saa mitään."],[19,8,"Joka viisas on, hän rakastaa henkeänsä, ja joka toimellinen on, se löytää hyvän.","Joka viisas on, hän rakastaa henkeänsä, ja joka toimellinen on, se löytää hyvän."],[19,9,"Väärä todistaja ei pidä pääsemän rankaisematta; ja joka rohkiasti valehtelee, se kadotetaan.","Väärä todistaja ei pidä pääsemän rankaisematta; ja joka rohkiasti valehtelee, se kadotetaan."],[19,10,"Ei hullulle sovi hyvät päivät, paljoa vähemmin palvelian päämiehiä hallita.","Ei hullulle sovi hyvät päivät, paljoa vähemmin palvelian päämiehiä hallita."],[19,11,"Joka on kärsivällinen, se on toimellinen ihminen; ja se on hänelle kunniaksi, että hän viat välttää.","Joka on kärsivällinen, se on toimellinen ihminen; ja se on hänelle kunniaksi, että hän viat välttää."],[19,12,"Kuninkaan viha on niinkuin nuoren jalopeuran kiljuminen; mutta hänen ystävyytensä on niinkuin kaste ruoholle.","Kuninkaan viha on niinkuin nuoren jalopeuran kiljuminen; mutta hänen ystävyytensä on niinkuin kaste ruoholle."],[19,13,"Hullu poika on isänsä murhe, ja riitainen vaimo on niinkuin alinomainen pisaroitseminen.","Hullu poika on isänsä murhe, ja riitainen vaimo on niinkuin alinomainen pisaroitseminen."],[19,14,"Huoneet ja tavarat peritään vanhemmilta, vaan toimellinen emäntä tulee Herralta.","Huoneet ja tavarat peritään vanhemmilta, vaan toimellinen emäntä tulee Herralta."],[19,15,"Laiskuus tuo unen, ja joutilas sielu kärsii nälkää.","Laiskuus tuo unen, ja joutilas sielu kärsii nälkää."],[19,16,"Joka käskyt pitää, hän on vapahtanut henkensä; vaan joka tiensä hylkää, hänen pitää kuoleman.","Joka käskyt pitää, hän on vapahtanut henkensä; vaan joka tiensä hylkää, hänen pitää kuoleman."],[19,17,"Jöka köyhää armahtaa, hän lainaa Herralle, joka hänen hyvän työnsä hänelle jälleen maksava on.","Jöka köyhää armahtaa, hän lainaa Herralle, joka hänen hyvän työnsä hänelle jälleen maksava on."],[19,18,"Kurita lastas, koska vielä toivo on; mutta älä pyydä häntä tappaa;","Kurita lastas, koska vielä toivo on; mutta älä pyydä häntä tappaa;"],[19,19,"Sillä suuri julmuus saattaa vahingon: sentähden laske vallallensa, ja kurita häntä toistamiseen.","Sillä suuri julmuus saattaa vahingon: sentähden laske vallallensa, ja kurita häntä toistamiseen."],[19,20,"Kuule neuvoa ja ota kuritus vastaan, tullakses vihdoinkin viisaaksi.","Kuule neuvoa ja ota kuritus vastaan, tullakses vihdoinkin viisaaksi."],[19,21,"Monet aivoitukset oavt miehen sydämessä; mutta Herran neuvo on pysyväinen.","Monet aivoitukset oavt miehen sydämessä; mutta Herran neuvo on pysyväinen."],[19,22,"Ihmiselle kelpaa hänen laupeutensa, ja köyhä mies on parempi kuin valehtelia.","Ihmiselle kelpaa hänen laupeutensa, ja köyhä mies on parempi kuin valehtelia."],[19,23,"Herran pelko saattaa elämän, ja se pysyy ravittuna, ettei mikään paha häntä lähesty.","Herran pelko saattaa elämän, ja se pysyy ravittuna, ettei mikään paha häntä lähesty."],[19,24,"Laiska kätkee kätensä poveensa, ja ei vie sitä jälleen suuhunsa.","Laiska kätkee kätensä poveensa, ja ei vie sitä jälleen suuhunsa."],[19,25,"Jos pilkkaajaa lyödään, niin taitamatoin tulee viisaaksi; ja jos toimellista lyödään, niin hän tulee toimelliseksi.","Jos pilkkaajaa lyödään, niin taitamatoin tulee viisaaksi; ja jos toimellista lyödään, niin hän tulee toimelliseksi."],[19,26,"Joka vaivaa isäänsä, ja ajaa ulos äitinsä, hän on häpeemätöin ja kirottu lapsi.","Joka vaivaa isäänsä, ja ajaa ulos äitinsä, hän on häpeemätöin ja kirottu lapsi."],[19,27,"Lakkaa poikani, kuuntelemasta sitä neuvoa, joka sinua viettelee pois toimellisesta opista.","Lakkaa poikani, kuuntelemasta sitä neuvoa, joka sinua viettelee pois toimellisesta opista."],[19,28,"Väärä todistus häpäisee tuomion, ja jumalattomain suu nielee vääryyden.","Väärä todistus häpäisee tuomion, ja jumalattomain suu nielee vääryyden."],[19,29,"Pilkkaajille on rangaistus valmistettu, ja haavat hulluin selkään.","Pilkkaajille on rangaistus valmistettu, ja haavat hulluin selkään."],[20,1,"Viina tekee pilkkaajaksi, ja väkevät juotavat tekevät tyhmäksi: joka niitä halajaa, ei hän ikinä viisaaksi tule.","Viina tekee pilkkaajaksi, ja väkevät juotavat tekevät tyhmäksi: joka niitä halajaa, ei hän ikinä viisaaksi tule."],[20,2,"Kuninkaan peljättämys on niinkuin nuoren jalopeuran kiljuminen: joka hänen vihoittaa, hän tekee omaa henkeänsä vastoin.","Kuninkaan peljättämys on niinkuin nuoren jalopeuran kiljuminen: joka hänen vihoittaa, hän tekee omaa henkeänsä vastoin."],[20,3,"Miehen kunnia on olla ilman riitaa; vaan jotka mielellänsä riitelevät, ovat kaikki tyhmät.","Miehen kunnia on olla ilman riitaa; vaan jotka mielellänsä riitelevät, ovat kaikki tyhmät."],[20,4,"Kylmän tähden ei tahdo laiska kyntää; sentähden hän elonaikana kerjää, ja ei saa mitään.","Kylmän tähden ei tahdo laiska kyntää; sentähden hän elonaikana kerjää, ja ei saa mitään."],[20,5,"Neuvo on miehen sydämessä niinkuin syvä vesi; mutta toimellinen ammuntaa sen ylös.","Neuvo on miehen sydämessä niinkuin syvä vesi; mutta toimellinen ammuntaa sen ylös."],[20,6,"Monta ihmistä kerskataan hyväksi; vaan kuka löytää jonkun, joka todella hyvä on?","Monta ihmistä kerskataan hyväksi; vaan kuka löytää jonkun, joka todella hyvä on?"],[20,7,"Vanhurskas siveydessä vaeltaa; hänen lastensa käy hyvin hänen perässänsä.","Vanhurskas siveydessä vaeltaa; hänen lastensa käy hyvin hänen perässänsä."],[20,8,"Kuningas, joka istuu istuimella tuomitsemaan, hajoittaa kaikki, jotka pahat ovat, silmillänsä.","Kuningas, joka istuu istuimella tuomitsemaan, hajoittaa kaikki, jotka pahat ovat, silmillänsä."],[20,9,"Kuka sanoo: minä olen puhdas sydämessäni, ja vapaa synnistäni?","Kuka sanoo: minä olen puhdas sydämessäni, ja vapaa synnistäni?"],[20,10,"Monenlainen vaaka ja mitta ovat molemmat kauhistus herralle.","Monenlainen vaaka ja mitta ovat molemmat kauhistus herralle."],[20,11,"Nuorukainen tunnetaan menostansa, jos hän siviäksi ja toimelliseksi tuleva on.","Nuorukainen tunnetaan menostansa, jos hän siviäksi ja toimelliseksi tuleva on."],[20,12,"Kuulevaisen korvan ja näkeväisen silmän on Herra molemmat tehnyt.","Kuulevaisen korvan ja näkeväisen silmän on Herra molemmat tehnyt."],[20,13,"Älä rakasta unta, ettes köyhtyisi: avaa silmäs, niin sinä saat kyllän leipää.","Älä rakasta unta, ettes köyhtyisi: avaa silmäs, niin sinä saat kyllän leipää."],[20,14,"Paha, paha, sanoo ostaja; mutta mentyänsä pois hän kerskaa.","Paha, paha, sanoo ostaja; mutta mentyänsä pois hän kerskaa."],[20,15,"Kultaa ja kalliita kiviä löydetään kyllä, vaan toimellinen suu on kallis kappale.","Kultaa ja kalliita kiviä löydetään kyllä, vaan toimellinen suu on kallis kappale."],[20,16,"Ota hänen vaattensa joka muukaisen takaa: ja ota häneltä pantti tuntemattoman edestä.","Ota hänen vaattensa joka muukaisen takaa: ja ota häneltä pantti tuntemattoman edestä."],[20,17,"Varastettu leipä maistuu miehelle hyvin; vaan sitte pitää hänen suunsa oleman täynnä teräviä kiviä.","Varastettu leipä maistuu miehelle hyvin; vaan sitte pitää hänen suunsa oleman täynnä teräviä kiviä."],[20,18,"Aivoitukset menestyvät, kuin ne neuvotella toimitetaan, ja sodat myös pitää toimella pidettämän.","Aivoitukset menestyvät, kuin ne neuvotella toimitetaan, ja sodat myös pitää toimella pidettämän."],[20,19,"Älä sekoita sinuas sen kanssa, joka salaisuuden ilmoittaa, ja joka panettelee, ja jolla petollinen suu on.","Älä sekoita sinuas sen kanssa, joka salaisuuden ilmoittaa, ja joka panettelee, ja jolla petollinen suu on."],[20,20,"Joka isäänsä ja äitiänsä kiroilee, hänen kynttilänsä pitää sammuman synkiässä pimeydessä.","Joka isäänsä ja äitiänsä kiroilee, hänen kynttilänsä pitää sammuman synkiässä pimeydessä."],[20,21,"Perintö, johon varhain kiiruhdetaan, on viimeiseltä ilman siunausta.","Perintö, johon varhain kiiruhdetaan, on viimeiseltä ilman siunausta."],[20,22,"Älä sano: minä kostan pahan; odota Herraa, hän auttaa sinua.","Älä sano: minä kostan pahan; odota Herraa, hän auttaa sinua."],[20,23,"Monenlaiset puntarit ovat Herralle kauhistus, ja väärä vaaka ei ole hyvä.","Monenlaiset puntarit ovat Herralle kauhistus, ja väärä vaaka ei ole hyvä."],[20,24,"Jokaisen retket tulevat Herralta: kuka ihminen taitaa ymmärtää tiensä?","Jokaisen retket tulevat Herralta: kuka ihminen taitaa ymmärtää tiensä?"],[20,25,"Se on ihmiselle paula, kuin hän pilkkaa pyhää, ja etsii sitte lupauksia.","Se on ihmiselle paula, kuin hän pilkkaa pyhää, ja etsii sitte lupauksia."],[20,26,"Viisas kuningas hajoittaa jumalattomat, ja antaa ratasten käydä heidän päällitsensä.","Viisas kuningas hajoittaa jumalattomat, ja antaa ratasten käydä heidän päällitsensä."],[20,27,"Herran kynttilä on ihmisen henki: hän käy läpi koko sydämen.","Herran kynttilä on ihmisen henki: hän käy läpi koko sydämen."],[20,28,"Laupius ja totuus varjelee kuninkaan, ja hän vahvistaa istuimensa laupiudella.","Laupius ja totuus varjelee kuninkaan, ja hän vahvistaa istuimensa laupiudella."],[20,29,"Nuorten miesten väkevyys on heidän kunniansa, ja harmaat karvat on vanhain kaunistus.","Nuorten miesten väkevyys on heidän kunniansa, ja harmaat karvat on vanhain kaunistus."],[20,30,"Haavoilla pitää pahuus ajettaman pois, ja koko sydämen kivulla.","Haavoilla pitää pahuus ajettaman pois, ja koko sydämen kivulla."],[21,1,"Kuninkaan sydän on Herran kädessä, niinkuin vesiojat, ja hän taittaa sen kuhunka tahtoo.","Kuninkaan sydän on Herran kädessä, niinkuin vesiojat, ja hän taittaa sen kuhunka tahtoo."],[21,2,"Jokainen luulee tiensä oikiaksi, vaan Herra koettelee sydämet.","Jokainen luulee tiensä oikiaksi, vaan Herra koettelee sydämet."],[21,3,"Hyvin ja oikein tehdä, on Herralle otollisempi kuin uhri.","Hyvin ja oikein tehdä, on Herralle otollisempi kuin uhri."],[21,4,"Ylpiät silmät ja paisunut sydän, ja jumalattomain kynttilä on synti.","Ylpiät silmät ja paisunut sydän, ja jumalattomain kynttilä on synti."],[21,5,"Ahkeran miehen aivoitukset tuovat yltäkylläisyyden; vaan joka pikainen on, se tulee köyhäksi.","Ahkeran miehen aivoitukset tuovat yltäkylläisyyden; vaan joka pikainen on, se tulee köyhäksi."],[21,6,"Joka tavaran kokoo valheella, se on kulkeva turhuus, niiden seassa, jotka kuolemaa etsivät.","Joka tavaran kokoo valheella, se on kulkeva turhuus, niiden seassa, jotka kuolemaa etsivät."],[21,7,"Jumalattomain raatelemus pitää heitä peljättämän; sillä ei he tahtoneet tehdä, mitä oikia on.","Jumalattomain raatelemus pitää heitä peljättämän; sillä ei he tahtoneet tehdä, mitä oikia on."],[21,8,"Jumalattoman ihmisen tie on outo; mutta puhtaan työ on oikia.","Jumalattoman ihmisen tie on outo; mutta puhtaan työ on oikia."],[21,9,"Parempi on asua katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa.","Parempi on asua katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa."],[21,10,"Jumalattoman sielu toivottaa pahaa, ja ei suo lähimmäisellensä mitään.","Jumalattoman sielu toivottaa pahaa, ja ei suo lähimmäisellensä mitään."],[21,11,"Kuin pilkkaaja rangaistaan, niin tyhmät viisaaksi tulevat, ja kuin viisas tulee opetetuksi, niin hän ottaa opin.","Kuin pilkkaaja rangaistaan, niin tyhmät viisaaksi tulevat, ja kuin viisas tulee opetetuksi, niin hän ottaa opin."],[21,12,"vanhurskas pitää itsensä viisaasti jumalattoman huonetta vastaan; vaan jumalattomat kietovat itsensä onnettomuuteen.","vanhurskas pitää itsensä viisaasti jumalattoman huonetta vastaan; vaan jumalattomat kietovat itsensä onnettomuuteen."],[21,13,"Joka tukitsee korvansa köyhän huudolta, hänen pitää myös huutaman, ja ei kuultaman.","Joka tukitsee korvansa köyhän huudolta, hänen pitää myös huutaman, ja ei kuultaman."],[21,14,"Salainen lahja asettaa vihan, ja helmaan anto lepyttä suurimman kiukun.","Salainen lahja asettaa vihan, ja helmaan anto lepyttä suurimman kiukun."],[21,15,"Se on vanhurskaille ilo, tehdä mikä oikia on, vaan pahantekiöillä on pelko.","Se on vanhurskaille ilo, tehdä mikä oikia on, vaan pahantekiöillä on pelko."],[21,16,"Ihminen joka poikkee viisauden tieltä, pitää oleman kuolleiden joukossa.","Ihminen joka poikkee viisauden tieltä, pitää oleman kuolleiden joukossa."],[21,17,"Joka hekumaa rakastaa, se tulee köyhäksi; ja joka viinaa ja öljyä rakastaa, ei hän tule rikkaaksi.","Joka hekumaa rakastaa, se tulee köyhäksi; ja joka viinaa ja öljyä rakastaa, ei hän tule rikkaaksi."],[21,18,"Jumalatoin pitää annettaman ulos vanhurskaan siaan, ja ylönkatsoja siveiden edestä.","Jumalatoin pitää annettaman ulos vanhurskaan siaan, ja ylönkatsoja siveiden edestä."],[21,19,"Parempi on asua autiossa maassa kuin riitaisen ja vihaisen vaimon kanssa.","Parempi on asua autiossa maassa kuin riitaisen ja vihaisen vaimon kanssa."],[21,20,"Viisaan huoneessa on suloinen tavara ja öljy, vaan tyhmä ihminen sen tuhlaa.","Viisaan huoneessa on suloinen tavara ja öljy, vaan tyhmä ihminen sen tuhlaa."],[21,21,"Joka vanhurskautta ja hyvyyttä noudattaa, hän löytää elämän, vanhurskauden ja kunnian.","Joka vanhurskautta ja hyvyyttä noudattaa, hän löytää elämän, vanhurskauden ja kunnian."],[21,22,"Viisas mies voittaa väkeväin kaupungin, ja kukistaa heidän uskalluksensa vahvuuden.","Viisas mies voittaa väkeväin kaupungin, ja kukistaa heidän uskalluksensa vahvuuden."],[21,23,"Joka suunsa ja kielensä hillitsee, hän varjelee sielunsa ahdistuksesta.","Joka suunsa ja kielensä hillitsee, hän varjelee sielunsa ahdistuksesta."],[21,24,"Joka ynseä ja ylpiä on, hän kutsutaan pilkkaajaksi, joka vihassa ynseytensä näyttää.","Joka ynseä ja ylpiä on, hän kutsutaan pilkkaajaksi, joka vihassa ynseytensä näyttää."],[21,25,"Laiskan himo tappaa hänen, ettei hänen kätensä tahtoneet mitään tehdä:","Laiskan himo tappaa hänen, ettei hänen kätensä tahtoneet mitään tehdä:"],[21,26,"Hän himoitsee suuresti kaiken päivän; muuta vanhurskas antaa, ja ei kiellä.","Hän himoitsee suuresti kaiken päivän; muuta vanhurskas antaa, ja ei kiellä."],[21,27,"Jumalattomain uhri on kauhistus, semminkin kuin se synnissä uhrataan.","Jumalattomain uhri on kauhistus, semminkin kuin se synnissä uhrataan."],[21,28,"Väärän todistajan pitää hukkuman; vaan joka tottelee, hän saa aina puhua.","Väärän todistajan pitää hukkuman; vaan joka tottelee, hän saa aina puhua."],[21,29,"Jumalatoin juoksee päätähavin lävitse: mutta hurskas ojentaa tiensä.","Jumalatoin juoksee päätähavin lävitse: mutta hurskas ojentaa tiensä."],[21,30,"Ei yksikään viisaus, eli ymmärrys, eikä neuvo, auta herraa vastaan.","Ei yksikään viisaus, eli ymmärrys, eikä neuvo, auta herraa vastaan."],[21,31,"Hevoset valmistetaan sodan päiväksi; mutta voitto tulee herralta.","Hevoset valmistetaan sodan päiväksi; mutta voitto tulee herralta."],[22,1,"Hyvä sanoma on kalliimpi kuin suuri rikkaus, ja suosio on parempi kuin hopia ja kulta.","Hyvä sanoma on kalliimpi kuin suuri rikkaus, ja suosio on parempi kuin hopia ja kulta."],[22,2,"Rikas ja köyhä tulevat toinen toistansa vastaan: ja Herra on ne kaikki tehnyt.","Rikas ja köyhä tulevat toinen toistansa vastaan: ja Herra on ne kaikki tehnyt."],[22,3,"Viisas näkee pahan, ja karttaa; taitamattomat juoksevat lävitse, ja saavat vahingon.","Viisas näkee pahan, ja karttaa; taitamattomat juoksevat lävitse, ja saavat vahingon."],[22,4,"Nöyryyden ja Herran pelvon palkka on rikkaus, kunnia ja elämä.","Nöyryyden ja Herran pelvon palkka on rikkaus, kunnia ja elämä."],[22,5,"Orjantappurat ja paulat ovat väärän tiellä; vaan joka siitä taamma vetäytyy, hän varjelee henkensä.","Orjantappurat ja paulat ovat väärän tiellä; vaan joka siitä taamma vetäytyy, hän varjelee henkensä."],[22,6,"Niinkuin sinä lapsen totutat nuoruudessa, niin ei hän siitä luovu, kuin hän vanhenee.","Niinkuin sinä lapsen totutat nuoruudessa, niin ei hän siitä luovu, kuin hän vanhenee."],[22,7,"Rikas vallitsee köyhiä, ja joka lainaksi ottaa, hän on lainaajan orja.","Rikas vallitsee köyhiä, ja joka lainaksi ottaa, hän on lainaajan orja."],[22,8,"Joka vääryyttä kylvää, se niittäää vaivan, ja hänen pahuutensa hukkuu vitsalla.","Joka vääryyttä kylvää, se niittäää vaivan, ja hänen pahuutensa hukkuu vitsalla."],[22,9,"Laupiaat silmät siunataan, sillä hän antaa leivästä köyhälle.","Laupiaat silmät siunataan, sillä hän antaa leivästä köyhälle."],[22,10,"Aja pilkkaaja pois,niin riita asettuu, ja tora ja häväistys lakkaa.","Aja pilkkaaja pois,niin riita asettuu, ja tora ja häväistys lakkaa."],[22,11,"Joka sydämen puhtautta rakastaa, sen huulet ovat otolliset, ja kuningas on hänen ystävänsä.","Joka sydämen puhtautta rakastaa, sen huulet ovat otolliset, ja kuningas on hänen ystävänsä."],[22,12,"Herran silmät varjelevat hyvän neuvon, ja kukistavat ylönkatsojan sanat.","Herran silmät varjelevat hyvän neuvon, ja kukistavat ylönkatsojan sanat."],[22,13,"Laiska sanoo: jalopeura on ulkona, ja minä tapetaan kadulla.","Laiska sanoo: jalopeura on ulkona, ja minä tapetaan kadulla."],[22,14,"Porttoin suu on syvä kuoppa: joka ei Herran suosiossa ole, hän lankee siihen.","Porttoin suu on syvä kuoppa: joka ei Herran suosiossa ole, hän lankee siihen."],[22,15,"Hulluus riippuu nuorukaisen sydämessä, vaan kurituksen vitsa ajaa sen kauvas hänestä.","Hulluus riippuu nuorukaisen sydämessä, vaan kurituksen vitsa ajaa sen kauvas hänestä."],[22,16,"Joka köyhälle tekee vääryyttä enentääksensä tavaraansa, hänen pitää itse rikkaalle antaman, ja tosin köyhäksi tuleman.","Joka köyhälle tekee vääryyttä enentääksensä tavaraansa, hänen pitää itse rikkaalle antaman, ja tosin köyhäksi tuleman."],[22,17,"Kallista korvas ja kuule viisasten sanat, ja pane minun oppini sydämees.","Kallista korvas ja kuule viisasten sanat, ja pane minun oppini sydämees."],[22,18,"Sillä se on sinulle suloinen, jos sinä pidät sen mielessäs, ja ne sovitetaan yhteen sinun huulilles.","Sillä se on sinulle suloinen, jos sinä pidät sen mielessäs, ja ne sovitetaan yhteen sinun huulilles."],[22,19,"Että sinun toivos olis Herrassa, olen minä sinua tänäpänä neuvonut; niin ota myös sinä näistä vaari.","Että sinun toivos olis Herrassa, olen minä sinua tänäpänä neuvonut; niin ota myös sinä näistä vaari."],[22,20,"Enkö minä ole suurista asioista kirjoittanut sinun etees, neuvoin ja opettain?","Enkö minä ole suurista asioista kirjoittanut sinun etees, neuvoin ja opettain?"],[22,21,"Osoittaakseni sinulle vahvan totuuden perustuksen, vastatakses niitä oikein, jotka sinun lähettävät.","Osoittaakseni sinulle vahvan totuuden perustuksen, vastatakses niitä oikein, jotka sinun lähettävät."],[22,22,"Älä ryöstä köyhää, vaikka hän köyhä on, ja älä solvaise vaivaista portissa.","Älä ryöstä köyhää, vaikka hän köyhä on, ja älä solvaise vaivaista portissa."],[22,23,"Sillä Herra ajaa heidän asiansa, ja sortaa heidän soortajansa.","Sillä Herra ajaa heidän asiansa, ja sortaa heidän soortajansa."],[22,24,"Älä antaudu vihaisen miehen seuraan, ja älä ole julman tykönä,","Älä antaudu vihaisen miehen seuraan, ja älä ole julman tykönä,"],[22,25,"Ettes oppisi hänen teitänsä, ja saisi sielulles paulaa.","Ettes oppisi hänen teitänsä, ja saisi sielulles paulaa."],[22,26,"Älä ole niiden tykönä, jotka kättä lyövät ja velkaa takaavat;","Älä ole niiden tykönä, jotka kättä lyövät ja velkaa takaavat;"],[22,27,"Sillä jos sinulla ei ole varaa maksaa, niin vuotees otetaan altas pois.","Sillä jos sinulla ei ole varaa maksaa, niin vuotees otetaan altas pois."],[22,28,"Älä siirrä takaperin entisiä rajoja, jotka esi-isäs tehneet ovat.","Älä siirrä takaperin entisiä rajoja, jotka esi-isäs tehneet ovat."],[22,29,"Jos sinä näet nopsan miehen asiassansa, sen pitää seisoman kuninkaan edessä: ei hänen pidä seisoman halpain edessä.","Jos sinä näet nopsan miehen asiassansa, sen pitää seisoman kuninkaan edessä: ei hänen pidä seisoman halpain edessä."],[23,1,"Koskas istus ja syöt jonkun herran kanssa, niin ota visu vaari, kuka edessäs on.","Koskas istus ja syöt jonkun herran kanssa, niin ota visu vaari, kuka edessäs on."],[23,2,"Ja pane veitsi kaulaas, jos sinä tahdot henkes pitää.","Ja pane veitsi kaulaas, jos sinä tahdot henkes pitää."],[23,3,"Älä himoitse hänen herkustansa; sillä se on petollinen leipä.","Älä himoitse hänen herkustansa; sillä se on petollinen leipä."],[23,4,"Älä vaivaa sinuas tullakses rikkaksi, ja lakkaa sinun viisaudesta.","Älä vaivaa sinuas tullakses rikkaksi, ja lakkaa sinun viisaudesta."],[23,5,"Älä lennätä silmiäs sen jälkeen, jota et sinä taida saada; sillä se tekee itsellensä siivet niinkuin kotka, ja lentää taivasta päin.","Älä lennätä silmiäs sen jälkeen, jota et sinä taida saada; sillä se tekee itsellensä siivet niinkuin kotka, ja lentää taivasta päin."],[23,6,"Älä syö leipää kateen kanssa, ja älä himoitse hänen hänen herkkuansa.","Älä syö leipää kateen kanssa, ja älä himoitse hänen hänen herkkuansa."],[23,7,"Sillä niinkuin hän itse sydämessänsä ajattelee, niin se on; hän sanoo sinulle: syö ja juo, ja ei kuitenkaan ole hänen mielensä sinun kanssas.","Sillä niinkuin hän itse sydämessänsä ajattelee, niin se on; hän sanoo sinulle: syö ja juo, ja ei kuitenkaan ole hänen mielensä sinun kanssas."],[23,8,"Sinun palas, jotka syönyt olet, pitää sinun oksentaman, ja sinun ystävälliset puhees pitää hukkaan tuleman.","Sinun palas, jotka syönyt olet, pitää sinun oksentaman, ja sinun ystävälliset puhees pitää hukkaan tuleman."],[23,9,"Älä puhu hullun korvissa; sillä hän katsoo sinun toimellisen puheen ylön.","Älä puhu hullun korvissa; sillä hän katsoo sinun toimellisen puheen ylön."],[23,10,"Älä siirrä takaperin entisiä rajoja,ja älä mene orpoin pellolle.","Älä siirrä takaperin entisiä rajoja,ja älä mene orpoin pellolle."],[23,11,"Sillä heidän lunastajansa on voimallinen: hän toimittaa heidän asiansa sinua vastaan.","Sillä heidän lunastajansa on voimallinen: hän toimittaa heidän asiansa sinua vastaan."],[23,12,"Anna sydämes kuritukseen, ja korvas toimelliseen puheesen.","Anna sydämes kuritukseen, ja korvas toimelliseen puheesen."],[23,13,"Älä lakkaa lasta kurittamasta; sillä jos sinä häntä vitsalla lyöt, niin ei hän kuole.","Älä lakkaa lasta kurittamasta; sillä jos sinä häntä vitsalla lyöt, niin ei hän kuole."],[23,14,"Sinä lyöt häntä vitsalla, vaan sinä vapahdat hänen sielunsa helvetistä.","Sinä lyöt häntä vitsalla, vaan sinä vapahdat hänen sielunsa helvetistä."],[23,15,"Poikani, jos sinä viisas olet, niin myös sydämeni iloitsee.","Poikani, jos sinä viisas olet, niin myös sydämeni iloitsee."],[23,16,"Ja minun munaskuuni ovat riemuiset, koska sinun huules puhuvat, mikä oikia on.","Ja minun munaskuuni ovat riemuiset, koska sinun huules puhuvat, mikä oikia on."],[23,17,"Älköön sinun sydämes kiivoitelko syntisiä, vaan olkoon Herran pelvossa joka päivä.","Älköön sinun sydämes kiivoitelko syntisiä, vaan olkoon Herran pelvossa joka päivä."],[23,18,"Sillä se on sinulle viimein hyväksi, ja ei sinun odottamises puutu.","Sillä se on sinulle viimein hyväksi, ja ei sinun odottamises puutu."],[23,19,"Kuule, poikani, ja ole viisas, ja johdata sydämes tielle.","Kuule, poikani, ja ole viisas, ja johdata sydämes tielle."],[23,20,"Älä ole juomarien ja syömärien seassa.","Älä ole juomarien ja syömärien seassa."],[23,21,"Sillä juomarit ja syömärit köyhtyvät, ja unikeko pitää ryysyissä käymän.","Sillä juomarit ja syömärit köyhtyvät, ja unikeko pitää ryysyissä käymän."],[23,22,"Kuule isääs, joka sinun siittänyt on, ja älä katso äitiäs ylön, kuin hän vanhaksi tulee.","Kuule isääs, joka sinun siittänyt on, ja älä katso äitiäs ylön, kuin hän vanhaksi tulee."],[23,23,"Osta totuutta, ja älä sitä myy, niin myös viisautta, oppia ja ymmärrystä.","Osta totuutta, ja älä sitä myy, niin myös viisautta, oppia ja ymmärrystä."],[23,24,"Vanhurskaan isä suuresti riemuitsee; ja joka viisaan siittänyt on, hän iloitsee hänestä.","Vanhurskaan isä suuresti riemuitsee; ja joka viisaan siittänyt on, hän iloitsee hänestä."],[23,25,"Anna isäs ja äitis iloita; ja riemuitkaan se, joka sinun synnyttänyt on.","Anna isäs ja äitis iloita; ja riemuitkaan se, joka sinun synnyttänyt on."],[23,26,"Anna minulle, poikani, sydämes, ja sinun silmäs pitäköön minun tieni.","Anna minulle, poikani, sydämes, ja sinun silmäs pitäköön minun tieni."],[23,27,"Sillä portto on syvä kuoppa, ja vieras vaimo on ahdas kaivo.","Sillä portto on syvä kuoppa, ja vieras vaimo on ahdas kaivo."],[23,28,"Ja hän väijyy niinkuin saalista, ja saattaa monta tottelemattomaksi ihmisten seassa.","Ja hän väijyy niinkuin saalista, ja saattaa monta tottelemattomaksi ihmisten seassa."],[23,29,"Kussa on kipu? kussa murhe? kussa tora? kussa valitus? kenellä haavat ilman syytä? kenellä punaiset silmät?","Kussa on kipu? kussa murhe? kussa tora? kussa valitus? kenellä haavat ilman syytä? kenellä punaiset silmät?"],[23,30,"Siinä, kussa viinan tykönä viivytään, ja tullaan tyhjentämään, mitä sisälle pantu on.","Siinä, kussa viinan tykönä viivytään, ja tullaan tyhjentämään, mitä sisälle pantu on."],[23,31,"Älä katsele viinaa, vaikka se punoittaa, ja on selkiänä lasissa, ja huokiasti menee alas;","Älä katsele viinaa, vaikka se punoittaa, ja on selkiänä lasissa, ja huokiasti menee alas;"],[23,32,"Vaan viimeiseltä puree se niinkuin käärme, ja pistää niinkuin kyykäärme.","Vaan viimeiseltä puree se niinkuin käärme, ja pistää niinkuin kyykäärme."],[23,33,"Niin katsovat sinun silmäs muita vaimoja, ja sinun sydämes puhuu toimettomia asioita,","Niin katsovat sinun silmäs muita vaimoja, ja sinun sydämes puhuu toimettomia asioita,"],[23,34,"Ja sinä tulet niinkuin se, joka makaa keskellä merta, ja niinkuin se joka makaa ylhäällä haahden pielen päässä.","Ja sinä tulet niinkuin se, joka makaa keskellä merta, ja niinkuin se joka makaa ylhäällä haahden pielen päässä."],[23,35,"Sinä sanot; he löivät minua, vaan en minä kipua tuntenut; he sysivät minua, ja en minä tiennyt. Kuin minä herään, niin tahdon minä vielä niin tehdä, ja sitä enempi etsiä.","Sinä sanot; he löivät minua, vaan en minä kipua tuntenut; he sysivät minua, ja en minä tiennyt. Kuin minä herään, niin tahdon minä vielä niin tehdä, ja sitä enempi etsiä."],[24,1,"Älä ole kiivas pahain ihmisten kanssa, ja älä himoitse olla heitä läsnä;","Älä ole kiivas pahain ihmisten kanssa, ja älä himoitse olla heitä läsnä;"],[24,2,"Sillä heidän sydämensä pyytää vahingoittaa, ja heidän huulensa neuvovat pahuuteen.","Sillä heidän sydämensä pyytää vahingoittaa, ja heidän huulensa neuvovat pahuuteen."],[24,3,"Viisaudella raknnetaan huone, ja toimella se vahvistetaan.","Viisaudella raknnetaan huone, ja toimella se vahvistetaan."],[24,4,"Taidolla kammio täytetään kaikkinaisista kalliista ja jaloista tavaroista.","Taidolla kammio täytetään kaikkinaisista kalliista ja jaloista tavaroista."],[24,5,"Viisas mies on väkevä, ja toimellinen mies on voimallinen väestä.","Viisas mies on väkevä, ja toimellinen mies on voimallinen väestä."],[24,6,"Sillä neuvolla sodatkin pidetään: ja jossa monta neuvonantajaa on, siinä on voitto.","Sillä neuvolla sodatkin pidetään: ja jossa monta neuvonantajaa on, siinä on voitto."],[24,7,"Viisaus on hullulle ylen korkia, ei hän tohdi avata suutansa portissa.","Viisaus on hullulle ylen korkia, ei hän tohdi avata suutansa portissa."],[24,8,"Joka ajattelee pahaa tehdäksensä, se kutsutaan pahain ajatusten päämieheksi.","Joka ajattelee pahaa tehdäksensä, se kutsutaan pahain ajatusten päämieheksi."],[24,9,"Tyhmäin ajatus on synti, ja pilkkaaja on kauhistus ihmisille.","Tyhmäin ajatus on synti, ja pilkkaaja on kauhistus ihmisille."],[24,10,"Ei se ole väkevä, joka ei tuskassa vahva ole.","Ei se ole väkevä, joka ei tuskassa vahva ole."],[24,11,"Auta niitä, joita tappaa tahdotaan, ja älä vedä sinuas pois pois niiden tyköä, jotka kuoletetaan.","Auta niitä, joita tappaa tahdotaan, ja älä vedä sinuas pois pois niiden tyköä, jotka kuoletetaan."],[24,12,"Jos sinä sanot: katso, emme ymmärrä sitä! luuletkos, ettei se, joka sydämet tutkii, sitä ymmärrä? ja se, joka sielustas ottaa vaarin, tunne sitä ja kosta ihmiselle tekonsa jälkeen?","Jos sinä sanot: katso, emme ymmärrä sitä! luuletkos, ettei se, joka sydämet tutkii, sitä ymmärrä? ja se, joka sielustas ottaa vaarin, tunne sitä ja kosta ihmiselle tekonsa jälkeen?"],[24,13,"Syö, poikani, hunajaa; sillä se on hyvä, ja mesileupä on makia suus laelle.","Syö, poikani, hunajaa; sillä se on hyvä, ja mesileupä on makia suus laelle."],[24,14,"Niin on myös viisauden oppi sielulles: koskas sen löydät, niin sinun viimein käy hyvin, ja ei sinun toivos ole turha.","Niin on myös viisauden oppi sielulles: koskas sen löydät, niin sinun viimein käy hyvin, ja ei sinun toivos ole turha."],[24,15,"Älä vartioitse vanhurskaan huonetta, sinä jumalatoin, älä hukkaa hänen lepoansa.","Älä vartioitse vanhurskaan huonetta, sinä jumalatoin, älä hukkaa hänen lepoansa."],[24,16,"Sillä vanhurskas taitaa langeta seitsemän kertaa, ja nousee jälleen; mutta jumalattomat kaatuvat onnettomuuteen.","Sillä vanhurskas taitaa langeta seitsemän kertaa, ja nousee jälleen; mutta jumalattomat kaatuvat onnettomuuteen."],[24,17,"Älä iloitse vihamiehes vahingosta, ja älköön sinun sydämes riemuitko hänen onnettomuudestansa,","Älä iloitse vihamiehes vahingosta, ja älköön sinun sydämes riemuitko hänen onnettomuudestansa,"],[24,18,"Ettei Herra näkisi sitä, ja se olis hänelle kelvotoin, ja hän kääntäis vihansa pois hänen päältänsä.","Ettei Herra näkisi sitä, ja se olis hänelle kelvotoin, ja hän kääntäis vihansa pois hänen päältänsä."],[24,19,"Älä vihastu pahain päälle, älä myös ole kiivas jumalattomain tähden;","Älä vihastu pahain päälle, älä myös ole kiivas jumalattomain tähden;"],[24,20,"Sillä ei häijyllä ole mitään toivomista, ja jumalattomain kynttilä pitää sammuman.","Sillä ei häijyllä ole mitään toivomista, ja jumalattomain kynttilä pitää sammuman."],[24,21,"Poikani, pelkää Herraa ja kuningasta, ja älä sekoita sinuas kapinan nostajain kanssa.","Poikani, pelkää Herraa ja kuningasta, ja älä sekoita sinuas kapinan nostajain kanssa."],[24,22,"Sillä heidän kadotuksensa nousee äkisti: ja kuka tietää, koska kummankin onnetomuus tulee?","Sillä heidän kadotuksensa nousee äkisti: ja kuka tietää, koska kummankin onnetomuus tulee?"],[24,23,"Nämä ovat myös viisasten: ei ole hyvä katsoa muotoa tuomiossa.","Nämä ovat myös viisasten: ei ole hyvä katsoa muotoa tuomiossa."],[24,24,"Joka jumalattomalle sanoo: sinä olet hurskas! häntä kiroovat ihmiset, ja kansa vihaa häntä.","Joka jumalattomalle sanoo: sinä olet hurskas! häntä kiroovat ihmiset, ja kansa vihaa häntä."],[24,25,"Mutta jotka rankaisevat, he ovat otolliset, ja runsas siunaus tulee heidän päällensä.","Mutta jotka rankaisevat, he ovat otolliset, ja runsas siunaus tulee heidän päällensä."],[24,26,"Toimellinen vastaus on niinkuin suloinen suun antamus.","Toimellinen vastaus on niinkuin suloinen suun antamus."],[24,27,"Toimita työs ulkona, ja valmista peltos, ja rakenna sitte huonees.","Toimita työs ulkona, ja valmista peltos, ja rakenna sitte huonees."],[24,28,"Älä todista lähimmäistäs vastaan ilman syytä, ja älä petä suullas.","Älä todista lähimmäistäs vastaan ilman syytä, ja älä petä suullas."],[24,29,"Älä sano: niinkuin hän teki minulle, niin minä teen hänelle: minä kostan jokaiselle hänen tekonsa jälkeen.","Älä sano: niinkuin hän teki minulle, niin minä teen hänelle: minä kostan jokaiselle hänen tekonsa jälkeen."],[24,30,"Minä kävin laiskan pellon ohitse, ja tyhmän viinamäen sivuitse,","Minä kävin laiskan pellon ohitse, ja tyhmän viinamäen sivuitse,"],[24,31,"Ja katso, siinä olivat paljaat ohdakkeet kasvaneet, ja se oli nukulaista täynnä, ja aidat olivat kaatuneet.","Ja katso, siinä olivat paljaat ohdakkeet kasvaneet, ja se oli nukulaista täynnä, ja aidat olivat kaatuneet."],[24,32,"Kuin minä sen bäin, panin minä sen sydämeeni, katselin ja opin siitä.","Kuin minä sen bäin, panin minä sen sydämeeni, katselin ja opin siitä."],[24,33,"Sinä tahdot vielä vähä maata ja unelias olla, ja enempi käsiäs yhteen panna lepäämään;","Sinä tahdot vielä vähä maata ja unelias olla, ja enempi käsiäs yhteen panna lepäämään;"],[24,34,"Mutta köyhyytes pitää sinulle tuleman niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies.","Mutta köyhyytes pitää sinulle tuleman niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies."],[25,1,"Nämät ovat myös Salomon sananlaskut, jotka Hiskian ja Juudan kuninkaan miehet ovat tähän panneet tykö.","Nämät ovat myös Salomon sananlaskut, jotka Hiskian ja Juudan kuninkaan miehet ovat tähän panneet tykö."],[25,2,"Se on Jumalan kunnia, salata asiaa; mutta kuninkaan kunnia, tutkia asiaa.","Se on Jumalan kunnia, salata asiaa; mutta kuninkaan kunnia, tutkia asiaa."],[25,3,"Taivas on korkia ja maa syvä, ja kuninkaan sydän on tutkimatoin.","Taivas on korkia ja maa syvä, ja kuninkaan sydän on tutkimatoin."],[25,4,"Raiska otetaan hopiasta pois, niin siitä tulee puhdas astia.","Raiska otetaan hopiasta pois, niin siitä tulee puhdas astia."],[25,5,"Jos jumalatoin otetaan pois kuninkaan kasvoin edestä, niin hänen istuimensa vanhurskaudella vahvistetaan.","Jos jumalatoin otetaan pois kuninkaan kasvoin edestä, niin hänen istuimensa vanhurskaudella vahvistetaan."],[25,6,"Älä koreile kuninkaan nähden, ja älä astu suurten sialle.","Älä koreile kuninkaan nähden, ja älä astu suurten sialle."],[25,7,"Sillä se on sinulle parempi, koska sinulle sanotaan: astu tänne ylemmä! kuin ettäs ruhtinaan edessä alennettaisiin, jota sinun silmäs näkisivät.","Sillä se on sinulle parempi, koska sinulle sanotaan: astu tänne ylemmä! kuin ettäs ruhtinaan edessä alennettaisiin, jota sinun silmäs näkisivät."],[25,8,"Älä ole pikainen riitelemään, ettes tiedä mitäs teet, koska lähimmäiseltäs häväisty olet?","Älä ole pikainen riitelemään, ettes tiedä mitäs teet, koska lähimmäiseltäs häväisty olet?"],[25,9,"Toimita asias lähimmmäises kanssa, älä ilmoita toisen salaisuutta,","Toimita asias lähimmmäises kanssa, älä ilmoita toisen salaisuutta,"],[25,10,"Ettei se, joka sen kuulee, sinua häpäisisi, ja ettei sinun paha sanomas lakkaa.","Ettei se, joka sen kuulee, sinua häpäisisi, ja ettei sinun paha sanomas lakkaa."],[25,11,"Sana, aikanansa puhuttu, on niinkuin kultainen omena hopiamaljassa.","Sana, aikanansa puhuttu, on niinkuin kultainen omena hopiamaljassa."],[25,12,"Koska viisas rankaisee sitä, jaka häntä kuulee, se on niinkuin korvarengas, ja niinkuin kaunistus parhaasta kullasta.","Koska viisas rankaisee sitä, jaka häntä kuulee, se on niinkuin korvarengas, ja niinkuin kaunistus parhaasta kullasta."],[25,13,"Niinkuin lumen kylmä elonaikana, niin on uskollinen sanansaattaja sille, joka hänen lähettänyt on, ja virvoittaa herransa sielun.","Niinkuin lumen kylmä elonaikana, niin on uskollinen sanansaattaja sille, joka hänen lähettänyt on, ja virvoittaa herransa sielun."],[25,14,"Joka paljon puhuu ja vähän pitää, hän on niinkuin tuuli ja pilvi ilman sadetta.","Joka paljon puhuu ja vähän pitää, hän on niinkuin tuuli ja pilvi ilman sadetta."],[25,15,"Kärsivällisyydellä päämies lepytetään, ja siviä kieli pehmittää kovuuden.","Kärsivällisyydellä päämies lepytetään, ja siviä kieli pehmittää kovuuden."],[25,16,"Jos sinä löydät hunajaa, niin syö tarpeekses, ettes ylönpalttisesti tulisi ravituksi, ja antaisi sitä ylen.","Jos sinä löydät hunajaa, niin syö tarpeekses, ettes ylönpalttisesti tulisi ravituksi, ja antaisi sitä ylen."],[25,17,"Anna jalkas harvoin tulla lähimmäises huoneeseen, ettei hän suuttuis sinuun, ja vihaisi sinua.","Anna jalkas harvoin tulla lähimmäises huoneeseen, ettei hän suuttuis sinuun, ja vihaisi sinua."],[25,18,"Joka väärää todistusta puhuu lähimmäistänsä vastaan, hän on vasara, miekka ja terävä nuoli.","Joka väärää todistusta puhuu lähimmäistänsä vastaan, hän on vasara, miekka ja terävä nuoli."],[25,19,"Pilkkaajan toivo hädän aikana on niinkuin murrettu hammas, ja vilpisteleväinen jalka.","Pilkkaajan toivo hädän aikana on niinkuin murrettu hammas, ja vilpisteleväinen jalka."],[25,20,"Joka murheellisen sydämen edessä virsiä veisaa, hän on niinkuin se, joka vaatten tempaa pois talvella, ja etikka pleikun päällä.","Joka murheellisen sydämen edessä virsiä veisaa, hän on niinkuin se, joka vaatten tempaa pois talvella, ja etikka pleikun päällä."],[25,21,"Jos sinun vihamiehes isoo, niin ravitse häntä leivällä: jos hän janoo, niin juota häntä vedellä;","Jos sinun vihamiehes isoo, niin ravitse häntä leivällä: jos hän janoo, niin juota häntä vedellä;"],[25,22,"Sillä sinä kokoot hiilet hänen päänsä päälle, ja Herra kostaa sen sinulle.","Sillä sinä kokoot hiilet hänen päänsä päälle, ja Herra kostaa sen sinulle."],[25,23,"Pohjatuuli tuottaa sateen, ja salainen kieli saattaa kasvot vihaisiksi.","Pohjatuuli tuottaa sateen, ja salainen kieli saattaa kasvot vihaisiksi."],[25,24,"Parempi on istus katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa.","Parempi on istus katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa."],[25,25,"Hyvä sanoma kaukaiselta maalta on kylmän veden kaltainen janoovaiselle sielulle.","Hyvä sanoma kaukaiselta maalta on kylmän veden kaltainen janoovaiselle sielulle."],[25,26,"Vanhurskas, joka jumalattoman eteen lankee, on niinkuin sekoitettu kaivo ja turmeltu lähde.","Vanhurskas, joka jumalattoman eteen lankee, on niinkuin sekoitettu kaivo ja turmeltu lähde."],[25,27,"Joka paljon hunajaa syö, ei se ole hyvä, ja joka työtläitä asioita tutkii, se tulee hänelle työlääksi.","Joka paljon hunajaa syö, ei se ole hyvä, ja joka työtläitä asioita tutkii, se tulee hänelle työlääksi."],[25,28,"Joka ei taida hillitä henkeänsä, hän on niinkuin hävitetty kaupunki ilman muuria.","Joka ei taida hillitä henkeänsä, hän on niinkuin hävitetty kaupunki ilman muuria."],[26,1,"Niinkuin lumi suvella ja sede elonaikana, niin ei sovi tyhmälle kunnia.","Niinkuin lumi suvella ja sede elonaikana, niin ei sovi tyhmälle kunnia."],[26,2,"Niinkuin lintu menee pois, ja pääskynen lentää, niin ei sovi salvaa kirous ilman syytä.","Niinkuin lintu menee pois, ja pääskynen lentää, niin ei sovi salvaa kirous ilman syytä."],[26,3,"Hevoselle ruoska ja aasille ohjat, ja hullulle vitsa selkään.","Hevoselle ruoska ja aasille ohjat, ja hullulle vitsa selkään."],[26,4,"Älä vastaa tyhmää hänen tyhmyytensä jälkeen, ettes myös sinä hänen kaltaiseksensa tulisi.","Älä vastaa tyhmää hänen tyhmyytensä jälkeen, ettes myös sinä hänen kaltaiseksensa tulisi."],[26,5,"Vastaa tyhmää hänen tyhmyytensä jälkeen, ettei hän näkyisi viisaaksi silmissänsä.","Vastaa tyhmää hänen tyhmyytensä jälkeen, ettei hän näkyisi viisaaksi silmissänsä."],[26,6,"Joka tyhmäin sanansaattajain kautta asian toimittaa, hän on niinkuin rampa jaloista, ja saa vahingon.","Joka tyhmäin sanansaattajain kautta asian toimittaa, hän on niinkuin rampa jaloista, ja saa vahingon."],[26,7,"Niinkuin nilkku voi hypätä, niin tyhmä taitaa puhua viisaudesta.","Niinkuin nilkku voi hypätä, niin tyhmä taitaa puhua viisaudesta."],[26,8,"Joka tyhmälle taritsee kunniaa, on niinkuin joku heittäisi kalliin kiven kiviroukkioon.","Joka tyhmälle taritsee kunniaa, on niinkuin joku heittäisi kalliin kiven kiviroukkioon."],[26,9,"Sananlasku on tyhmäin suussa niinkuin orjantappura, joka juopuneen käsiin pistelee.","Sananlasku on tyhmäin suussa niinkuin orjantappura, joka juopuneen käsiin pistelee."],[26,10,"Taitava ihminen tekee kappaleen oikein; vaan joka taitamattoman palkkaa, hän sen turmelee.","Taitava ihminen tekee kappaleen oikein; vaan joka taitamattoman palkkaa, hän sen turmelee."],[26,11,"Niinkuin koira syö oksennuksensa, niin on hullu joka hulluutensa kertoo.","Niinkuin koira syö oksennuksensa, niin on hullu joka hulluutensa kertoo."],[26,12,"Koskas näet jonkun, joka luulee itsensä viisaaksi, enempi on silloin toivoa tyhmästä kuin hänestä.","Koskas näet jonkun, joka luulee itsensä viisaaksi, enempi on silloin toivoa tyhmästä kuin hänestä."],[26,13,"Laiska sanoo: nuori jalopeura on tiellä, ja jalopeura kujalla.","Laiska sanoo: nuori jalopeura on tiellä, ja jalopeura kujalla."],[26,14,"Laiska kääntelee itsiänsä vuoteella niinkuin ovi saranassa.","Laiska kääntelee itsiänsä vuoteella niinkuin ovi saranassa."],[26,15,"Laiska panee kätensä poveensa: ja se tulee hänelle työlääksi saattaa suuhunsa jälleen.","Laiska panee kätensä poveensa: ja se tulee hänelle työlääksi saattaa suuhunsa jälleen."],[26,16,"Laiska luulee itsensä viisaammaksi kuin seitsemän, jotka hyviä tapoja opettavat.","Laiska luulee itsensä viisaammaksi kuin seitsemän, jotka hyviä tapoja opettavat."],[26,17,"Joka käy ohitse ja sekoittaa itsensä muiden riitoihin, hän on senkaltainen, joka koiraa korvista vetää.","Joka käy ohitse ja sekoittaa itsensä muiden riitoihin, hän on senkaltainen, joka koiraa korvista vetää."],[26,18,"Niinkuin se, joka salaa ampuu, tarkoittaa joutsella ja tappaa,","Niinkuin se, joka salaa ampuu, tarkoittaa joutsella ja tappaa,"],[26,19,"Niin on petollinen ihminen hänen lähimmäisillensä, ja sanoo: leikillä minä sen tein.","Niin on petollinen ihminen hänen lähimmäisillensä, ja sanoo: leikillä minä sen tein."],[26,20,"Kuin halot loppuvat, niin tuli sammuu, ja kuin kielikellot pannaan pois, niin riidat lakkaavat.","Kuin halot loppuvat, niin tuli sammuu, ja kuin kielikellot pannaan pois, niin riidat lakkaavat."],[26,21,"Niinkuin hiilet tuleen, ja puut liekkiin, niin riitainen ihminen saattaa metelin.","Niinkuin hiilet tuleen, ja puut liekkiin, niin riitainen ihminen saattaa metelin."],[26,22,"Panettelian sanat ovat niinkuin haavat, ja käyvät läpi sydämen.","Panettelian sanat ovat niinkuin haavat, ja käyvät läpi sydämen."],[26,23,"Viekas kieli ja paha sydän on niinkuin saviastia hopian savulla juotettu.","Viekas kieli ja paha sydän on niinkuin saviastia hopian savulla juotettu."],[26,24,"Vihamien teeskelee itsensä toisin puheellansa; mutta petos on hänen sydämessänsä.","Vihamien teeskelee itsensä toisin puheellansa; mutta petos on hänen sydämessänsä."],[26,25,"Kuin hän liehakoitsee makeilla puheillansa, niin älä usko häntä; sillä seitsemän kauhistusta on hänen sydämessänsä.","Kuin hän liehakoitsee makeilla puheillansa, niin älä usko häntä; sillä seitsemän kauhistusta on hänen sydämessänsä."],[26,26,"Joka pitää salavihaa, tehdäksensä vahinkoa, hänen pahuutensa tulee ilmi kokouksissa.","Joka pitää salavihaa, tehdäksensä vahinkoa, hänen pahuutensa tulee ilmi kokouksissa."],[26,27,"Joka kuopan kaivaa, hän lankee siihen, ja joka kiven vierittää, se kierittää sen itse päällensä.","Joka kuopan kaivaa, hän lankee siihen, ja joka kiven vierittää, se kierittää sen itse päällensä."],[26,28,"Petollinen kieli vihaa rangaistusta, ja suu, joka myötäkielin puhuu, saattaa kadotukseen.","Petollinen kieli vihaa rangaistusta, ja suu, joka myötäkielin puhuu, saattaa kadotukseen."],[27,1,"Älä kehu huomisesta päivästä; sillä et sinä tiedä, mitä tänäpänä tapahtuu.","Älä kehu huomisesta päivästä; sillä et sinä tiedä, mitä tänäpänä tapahtuu."],[27,2,"Anna toisen sinuas kiittää, ja ei sinun oman suus, muukalaisen, ja ei omin huultes.","Anna toisen sinuas kiittää, ja ei sinun oman suus, muukalaisen, ja ei omin huultes."],[27,3,"Kivi on raskas ja santa painaa; vaan tyhmän viha on raskaampi kuin ne molemmat.","Kivi on raskas ja santa painaa; vaan tyhmän viha on raskaampi kuin ne molemmat."],[27,4,"Viha on julma kappale ja karvas mieli on myrsky; ja kuka taitaa olla kateutta vastaan?","Viha on julma kappale ja karvas mieli on myrsky; ja kuka taitaa olla kateutta vastaan?"],[27,5,"Julkinen kuritus on parempi kuin salainen rakkaus.","Julkinen kuritus on parempi kuin salainen rakkaus."],[27,6,"Hyvänsuovan haavat ovat paremmet kuin petolliset Vainoojain suunantamiset.","Hyvänsuovan haavat ovat paremmet kuin petolliset Vainoojain suunantamiset."],[27,7,"Ravittu sielu polkee hunajaa; vaan isoovaiselle sielulle ovat kaikki karvaatkin makiat.","Ravittu sielu polkee hunajaa; vaan isoovaiselle sielulle ovat kaikki karvaatkin makiat."],[27,8,"Niinkuin lintu, joka pesästänsä kulkee, niin on se mies, joka siastansa siirtää.","Niinkuin lintu, joka pesästänsä kulkee, niin on se mies, joka siastansa siirtää."],[27,9,"Voiteesta ja suitsutuksesta sydän iloitsee, ja ystävän hyvä neuvo on sielulle otollinen.","Voiteesta ja suitsutuksesta sydän iloitsee, ja ystävän hyvä neuvo on sielulle otollinen."],[27,10,"Älä hylkää ystävääs, ja isäs ystäviä, ja älä mene veljes huoneesen, kuin sinun väärin käy; sillä parempi on kylänmies, joka läsnä on, kuin veli, joka taampana on.","Älä hylkää ystävääs, ja isäs ystäviä, ja älä mene veljes huoneesen, kuin sinun väärin käy; sillä parempi on kylänmies, joka läsnä on, kuin veli, joka taampana on."],[27,11,"Ole viisas, poikani, ja iloita sydämeni, että minä taitaisin vastata sitä, joka minua pilkkaa.","Ole viisas, poikani, ja iloita sydämeni, että minä taitaisin vastata sitä, joka minua pilkkaa."],[27,12,"Viisas näkee vaaran, ja lymyttää itsensä; vaan tyhmät menevät siihen, ja saavat vahingon.","Viisas näkee vaaran, ja lymyttää itsensä; vaan tyhmät menevät siihen, ja saavat vahingon."],[27,13,"Ota hänen vaattensa, joka toisen takaa, ja ota häneltä pantti muukalaisen edestä.","Ota hänen vaattensa, joka toisen takaa, ja ota häneltä pantti muukalaisen edestä."],[27,14,"Joka lähimmäistänsä siunaa korkialla äänellä, ja nousee varhain, se luetaan hänelle kiroukseksi.","Joka lähimmäistänsä siunaa korkialla äänellä, ja nousee varhain, se luetaan hänelle kiroukseksi."],[27,15,"Riitainen vaimo, ja alinomainen tiukkuminen suuresta sateesta, nämät oikein yhteen verrataan.","Riitainen vaimo, ja alinomainen tiukkuminen suuresta sateesta, nämät oikein yhteen verrataan."],[27,16,"Joka häntä tahtoo kätkeä, hän käsittelee tuulta, ja pivo öljyä kädessänsä.","Joka häntä tahtoo kätkeä, hän käsittelee tuulta, ja pivo öljyä kädessänsä."],[27,17,"Veitsi hioo veitsen, ja mies teroittaa ystävänsä.","Veitsi hioo veitsen, ja mies teroittaa ystävänsä."],[27,18,"Joka fikunapuunsa varjelee, se syö siitä hedelmän, ja joka herraansa vartioitsee, se kunnioitetaan.","Joka fikunapuunsa varjelee, se syö siitä hedelmän, ja joka herraansa vartioitsee, se kunnioitetaan."],[27,19,"Niinkuin varjo on vedessä ihmisen kasvon suhteen, niin on ihmisen sydän toisia vastaan.","Niinkuin varjo on vedessä ihmisen kasvon suhteen, niin on ihmisen sydän toisia vastaan."],[27,20,"Helvetti ja kadotus ei tule ikänä täyteen, ja ihmisen silmät ovat tyytymättömät.","Helvetti ja kadotus ei tule ikänä täyteen, ja ihmisen silmät ovat tyytymättömät."],[27,21,"Mies tulee kiusatuksi kiittäjän suun kautta, niinkuin hopia ahjossa ja kulta pätsissä.","Mies tulee kiusatuksi kiittäjän suun kautta, niinkuin hopia ahjossa ja kulta pätsissä."],[27,22,"Jos sinä huhmaressa survoisit tyhmän niinkuin ryynit, niin ei kuitenkaan hänen hulluutensa hänestä erkane.","Jos sinä huhmaressa survoisit tyhmän niinkuin ryynit, niin ei kuitenkaan hänen hulluutensa hänestä erkane."],[27,23,"Ota ahkera vaari lampaistas, ja pidä murhe laumastas;","Ota ahkera vaari lampaistas, ja pidä murhe laumastas;"],[27,24,"Sillä ei tavara ole ijankaikkisesti, eikä kruunu suvusta sukuun.","Sillä ei tavara ole ijankaikkisesti, eikä kruunu suvusta sukuun."],[27,25,"Ruoho käy ylös ja kukkaset puhkeevat, ja heinät vuorilla kootaan.","Ruoho käy ylös ja kukkaset puhkeevat, ja heinät vuorilla kootaan."],[27,26,"Lampaat vaatettavat sinua, ja kauriit antavat pellon vuoron.","Lampaat vaatettavat sinua, ja kauriit antavat pellon vuoron."],[27,27,"Sinulla on vuohten rieskaa kyllä sekä omaksi settä huonees ravinnoksi, ja piikais elatukseksi.","Sinulla on vuohten rieskaa kyllä sekä omaksi settä huonees ravinnoksi, ja piikais elatukseksi."],[28,1,"Jumalatoin pakenee, ja ei kenkään aja häntä takaa; vaan jumalinen on rohkia niinkuin nuori jalopeura.","Jumalatoin pakenee, ja ei kenkään aja häntä takaa; vaan jumalinen on rohkia niinkuin nuori jalopeura."],[28,2,"Maakunnan synnin tähden tulee valtakuntaan monta päämiestä; vaan toimellisten ja ymmärtäväisten ihmisten tähden pysyy se kauvan.","Maakunnan synnin tähden tulee valtakuntaan monta päämiestä; vaan toimellisten ja ymmärtäväisten ihmisten tähden pysyy se kauvan."],[28,3,"Nälkäinen, joka köyhiä vaivaa, on niinkuin sadekuuro, joka hedelmän turmelee.","Nälkäinen, joka köyhiä vaivaa, on niinkuin sadekuuro, joka hedelmän turmelee."],[28,4,"Jotka lain hylkäävät, ne ylistävät jumalattomia; vaan jotka lain kätkevät, ovat heille vihaiset.","Jotka lain hylkäävät, ne ylistävät jumalattomia; vaan jotka lain kätkevät, ovat heille vihaiset."],[28,5,"Ei pahat ihmiset oikeudesta lukua pidä; vaan jotka Herraa etsivät, he ottavat kaikista vaarin.","Ei pahat ihmiset oikeudesta lukua pidä; vaan jotka Herraa etsivät, he ottavat kaikista vaarin."],[28,6,"Parempi on köyhä joka vakuudessansa vaeltaa, kuin rikas, joka väärillä teillä käyskentelee.","Parempi on köyhä joka vakuudessansa vaeltaa, kuin rikas, joka väärillä teillä käyskentelee."],[28,7,"Joka lain kätkee, se on toimellinen lapsi; mutta joka tuhlaajaa ruokkii, se häpäisee isänsä.","Joka lain kätkee, se on toimellinen lapsi; mutta joka tuhlaajaa ruokkii, se häpäisee isänsä."],[28,8,"Joka tavaransa enentää korolla ja voitolla, se kokoo köyhäin tarpeeksi.","Joka tavaransa enentää korolla ja voitolla, se kokoo köyhäin tarpeeksi."],[28,9,"Joka korvansa kääntää pois lain kuulosta, hänen rukouksensakin on kauhistus.","Joka korvansa kääntää pois lain kuulosta, hänen rukouksensakin on kauhistus."],[28,10,"Joka jumaliset saattaa väärälle tielle, hän lankee omaan kuoppaansa; mutta hurskaat perivät hyvyyden.","Joka jumaliset saattaa väärälle tielle, hän lankee omaan kuoppaansa; mutta hurskaat perivät hyvyyden."],[28,11,"Rikas luulee itsensä viisaaksi, vaan toimellinen köyhä ymmärtää hänen.","Rikas luulee itsensä viisaaksi, vaan toimellinen köyhä ymmärtää hänen."],[28,12,"Kuin vanhurskaat vallitsevat, niin käy sangen hyvin; vaan koska jumalattomat hallitsevat, niin muuttet ovat kansan seassa.","Kuin vanhurskaat vallitsevat, niin käy sangen hyvin; vaan koska jumalattomat hallitsevat, niin muuttet ovat kansan seassa."],[28,13,"Joka pahan tekonsa kieltää, ei hän menesty; vaan joka sen tunnustaa ja hylkää, hänelle tapahtuu laupius.","Joka pahan tekonsa kieltää, ei hän menesty; vaan joka sen tunnustaa ja hylkää, hänelle tapahtuu laupius."],[28,14,"Autuas on se ihminen, joka aina pelkää; vaan joka sydämensä paaduttaa, se lankee onnettomuuteen.","Autuas on se ihminen, joka aina pelkää; vaan joka sydämensä paaduttaa, se lankee onnettomuuteen."],[28,15,"Jumalatoin päämies, joka köyhää kansaa hallitsee, on kiljuva jalopeura ja ahne karhu.","Jumalatoin päämies, joka köyhää kansaa hallitsee, on kiljuva jalopeura ja ahne karhu."],[28,16,"Kuin hallitsia on ilman toimeta, niin paljon vääryyttä tapahtuu; vaan joka vihaa ahneutta, hän saa kauvan elää.","Kuin hallitsia on ilman toimeta, niin paljon vääryyttä tapahtuu; vaan joka vihaa ahneutta, hän saa kauvan elää."],[28,17,"Ihminen, joka jonkun sielun veressä vääryyttä tekee, ei pääse, vaikka hän hamaan hautaan pakenis.","Ihminen, joka jonkun sielun veressä vääryyttä tekee, ei pääse, vaikka hän hamaan hautaan pakenis."],[28,18,"Joka vakuudessa vaeltaa, se on tallessa; mutta joka käy pahaa tietä, hänen täytyy joskus langeta.","Joka vakuudessa vaeltaa, se on tallessa; mutta joka käy pahaa tietä, hänen täytyy joskus langeta."],[28,19,"Joka peltonsa viljelee, hän saa leipää yltäisesti; vaan joka pyytää joutilaana käydä, se ravitaan köyhyydellä.","Joka peltonsa viljelee, hän saa leipää yltäisesti; vaan joka pyytää joutilaana käydä, se ravitaan köyhyydellä."],[28,20,"Uskollinen mies runsaasti siunataan; vaan joka pyrkii rikkauden perään, ei hän ole viaton.","Uskollinen mies runsaasti siunataan; vaan joka pyrkii rikkauden perään, ei hän ole viaton."],[28,21,"Ei ole se hyvä, että joku katsoo muotoa; sillä ihminen taitaa tehdä leivän kappaleen tähden väärin.","Ei ole se hyvä, että joku katsoo muotoa; sillä ihminen taitaa tehdä leivän kappaleen tähden väärin."],[28,22,"Joka äkisti rikkautta pyytää, ja on kade, hänelle tulee köyhyys, ettei hän tiedäkään.","Joka äkisti rikkautta pyytää, ja on kade, hänelle tulee köyhyys, ettei hän tiedäkään."],[28,23,"Joka ihmistä rankaisee, hän löytää paremman ystävyyden kuin se, joka puhuu ymötämielin.","Joka ihmistä rankaisee, hän löytää paremman ystävyyden kuin se, joka puhuu ymötämielin."],[28,24,"Joka ottaa isältänsä ja äidiltänsä, ja sanoo; ei se ole synti, hän on hävittäjän kanssaveli.","Joka ottaa isältänsä ja äidiltänsä, ja sanoo; ei se ole synti, hän on hävittäjän kanssaveli."],[28,25,"Ylpiä ihminen saattaa riidan; mutta joka luottaa Herraan, hän kostuu.","Ylpiä ihminen saattaa riidan; mutta joka luottaa Herraan, hän kostuu."],[28,26,"Joka omaan sydämeensä uskaltaa, hän on tyhmä; mutta joka viisaudessa vaeltaa, hän vapahdetaan.","Joka omaan sydämeensä uskaltaa, hän on tyhmä; mutta joka viisaudessa vaeltaa, hän vapahdetaan."],[28,27,"Joka vaivaiselle antaa, ei häneltä puutu; vaan joka silmänsä hänestä kääntää, se tulee pahasti kirotuksi.","Joka vaivaiselle antaa, ei häneltä puutu; vaan joka silmänsä hänestä kääntää, se tulee pahasti kirotuksi."],[28,28,"Kuin jumalattomat tulevat, niin kansa itsensä kätkee; mutta kuin ne hukkuvat, niin vanhurskaat enenevät.","Kuin jumalattomat tulevat, niin kansa itsensä kätkee; mutta kuin ne hukkuvat, niin vanhurskaat enenevät."],[29,1,"Joka kuritukselle on uppiniskainen, hän äkisti kadotetaan ilman yhdetäkään avuta.","Joka kuritukselle on uppiniskainen, hän äkisti kadotetaan ilman yhdetäkään avuta."],[29,2,"Kuin vanhurskaita monta on, niin kansa iloitsee; vaan kuin jumalatoin hallitsee, niin kansa huokaa.","Kuin vanhurskaita monta on, niin kansa iloitsee; vaan kuin jumalatoin hallitsee, niin kansa huokaa."],[29,3,"Joka viisautta rakastaa, hän iloittaa isänsä; mutta joka huoria elättää, hän tuhlaa tavaraansa.","Joka viisautta rakastaa, hän iloittaa isänsä; mutta joka huoria elättää, hän tuhlaa tavaraansa."],[29,4,"Kuningas rakentaa oikeudella valtakunnan; vaan lahjain ottaja sen turmelee.","Kuningas rakentaa oikeudella valtakunnan; vaan lahjain ottaja sen turmelee."],[29,5,"Joka lähimmäisensä kanssa liehakoitsee, hän hajoittaa verkon jalkainsa eteen.","Joka lähimmäisensä kanssa liehakoitsee, hän hajoittaa verkon jalkainsa eteen."],[29,6,"Kuin paha syntiä tekee, niin hän hänensä paulaan sekoittaa; vaan vanhurskas riemuitsee, ja hänellä on ilo.","Kuin paha syntiä tekee, niin hän hänensä paulaan sekoittaa; vaan vanhurskas riemuitsee, ja hänellä on ilo."],[29,7,"Vanhurskas tuntee köyhän asian; vaan jumalatoin ei ymmärrä viisautta.","Vanhurskas tuntee köyhän asian; vaan jumalatoin ei ymmärrä viisautta."],[29,8,"Pilkkaajat hajoittavat kaupungin; vaan viisaat asettavat vihan.","Pilkkaajat hajoittavat kaupungin; vaan viisaat asettavat vihan."],[29,9,"Kuin viisas tulee tyhmän kanssa oikeutta käymään, joko hän on vihainen eli iloinen, niin ei ole hänellä yhtään lepoa.","Kuin viisas tulee tyhmän kanssa oikeutta käymään, joko hän on vihainen eli iloinen, niin ei ole hänellä yhtään lepoa."],[29,10,"Verikoirat vihaavat siviää; vaan vanhurskaat holhovat häntä.","Verikoirat vihaavat siviää; vaan vanhurskaat holhovat häntä."],[29,11,"Tyhmä vuodattaa kaiken henkensä; vaan viisas sen pidättää.","Tyhmä vuodattaa kaiken henkensä; vaan viisas sen pidättää."],[29,12,"Päämies, joka valhetta rakastaa, hänen palveliansa ovat kaikki jumalattomat.","Päämies, joka valhetta rakastaa, hänen palveliansa ovat kaikki jumalattomat."],[29,13,"Köyhä ja rikas kohtasivat toinen toisensa: Herra valaisee heidän molempain silmänsä.","Köyhä ja rikas kohtasivat toinen toisensa: Herra valaisee heidän molempain silmänsä."],[29,14,"Kuningas, joka uskollisesti tuomitsee köyhiä, hänen istuimensa vahvistetaan ijankaikkisesti.","Kuningas, joka uskollisesti tuomitsee köyhiä, hänen istuimensa vahvistetaan ijankaikkisesti."],[29,15,"Vitsa ja rangaistus antaa viisauden; vaan itsevaltainen lapsi häpäisee äitinsä.","Vitsa ja rangaistus antaa viisauden; vaan itsevaltainen lapsi häpäisee äitinsä."],[29,16,"Jossa monta jumalatointa on, siinä on monta syntiä; vaan vanhurskaat näkevät heidän lankeemisensa.","Jossa monta jumalatointa on, siinä on monta syntiä; vaan vanhurskaat näkevät heidän lankeemisensa."],[29,17,"Kurita poikaas, niin hän sinua virvoitaa, ja saattaa sielus iloiseksi.","Kurita poikaas, niin hän sinua virvoitaa, ja saattaa sielus iloiseksi."],[29,18,"Kuin ennustukset loppuvat, niin kansa hajoitetaan; vaan autuas kätkee lain.","Kuin ennustukset loppuvat, niin kansa hajoitetaan; vaan autuas kätkee lain."],[29,19,"Palvelia ei anna itsiänsä kurittaa sanoilla; sillä vaikka hän sen ymmärtää, niin ei hän vastaa.","Palvelia ei anna itsiänsä kurittaa sanoilla; sillä vaikka hän sen ymmärtää, niin ei hän vastaa."],[29,20,"Jos sinä näet jonkun, joka on nopsa puhumaan: enempi on toivoa tyhmästä kuin hänestä.","Jos sinä näet jonkun, joka on nopsa puhumaan: enempi on toivoa tyhmästä kuin hänestä."],[29,21,"Jos palvelia nuoruudesta herkullisesti pidetään, niin hän tahtoo sitte poikana olla.","Jos palvelia nuoruudesta herkullisesti pidetään, niin hän tahtoo sitte poikana olla."],[29,22,"Vihainen mies saattaa riidan, ja kiukkuinen tekee monta syntiä.","Vihainen mies saattaa riidan, ja kiukkuinen tekee monta syntiä."],[29,23,"Ylpeys kukistaa ihmisen; vaan kunnia korottaa nöyrän.","Ylpeys kukistaa ihmisen; vaan kunnia korottaa nöyrän."],[29,24,"Joka varkaan kanssa on osallinen, hän vihaa sieluansa, niin myös se, joka kuulee kirouksen ja ei ilmoita.","Joka varkaan kanssa on osallinen, hän vihaa sieluansa, niin myös se, joka kuulee kirouksen ja ei ilmoita."],[29,25,"Joka pelkää ihmistä, hän tulee lankeemukseen; mutta joka luottaa Herraan, hän tulee pidetyksi ylös.","Joka pelkää ihmistä, hän tulee lankeemukseen; mutta joka luottaa Herraan, hän tulee pidetyksi ylös."],[29,26,"Moni etsii päämiehenkasvoja; mutta jokaisen tuomio tulee Herralta.","Moni etsii päämiehenkasvoja; mutta jokaisen tuomio tulee Herralta."],[29,27,"Jumalatoin ihminen on vanhurskaille kauhistus; ja joka oikialla tiellä on, hän on jumalattomalle kauhistus.","Jumalatoin ihminen on vanhurskaille kauhistus; ja joka oikialla tiellä on, hän on jumalattomalle kauhistus."],[30,1,"Agurin Jakenin pojan pojan sanat ja opetus, jonka se mies pujui Itielille, Itielille ja Ukkalille.","Agurin Jakenin pojan pojan sanat ja opetus, jonka se mies pujui Itielille, Itielille ja Ukkalille."],[30,2,"Minä olen kaikkein hulluin, ja ihmisten ymmärrys ei ole minussa.","Minä olen kaikkein hulluin, ja ihmisten ymmärrys ei ole minussa."],[30,3,"En minä ole oppinut viisautta, ja en tiedä pyhäin taitoa.","En minä ole oppinut viisautta, ja en tiedä pyhäin taitoa."],[30,4,"Kuka taivaaseen menee ylös ja tulee alas? kuka käsittää tuulen pivoonsa? kuka sitoo veden vaatteeseen? kuka 0n asttanut kaikki maan ääret? mikä on hänen nimensä? kuinka hänen poikansa kutsutaan? tiedätkös?","Kuka taivaaseen menee ylös ja tulee alas? kuka käsittää tuulen pivoonsa? kuka sitoo veden vaatteeseen? kuka 0n asttanut kaikki maan ääret? mikä on hänen nimensä? kuinka hänen poikansa kutsutaan? tiedätkös?"],[30,5,"Kaikki Jumalan sanat ovat kirkastetut, ja ovat kilpi niille, jotka uskovat hänen päällensä.","Kaikki Jumalan sanat ovat kirkastetut, ja ovat kilpi niille, jotka uskovat hänen päällensä."],[30,6,"Älä lisää hänen sanoihinsa, ettei hän sinua rankaisisi, ja sinä löyttäisiin valehteliaksi.","Älä lisää hänen sanoihinsa, ettei hän sinua rankaisisi, ja sinä löyttäisiin valehteliaksi."],[30,7,"Kahta minä sinulta anon, ettes minulta niitä kieltäisi, ennenkuin minä kuolen:","Kahta minä sinulta anon, ettes minulta niitä kieltäisi, ennenkuin minä kuolen:"],[30,8,"Väärä oppi ja valhe olkoon minusta kaukana: köyhyyttä ja rikkautta älä minulle anna; vaan anna minun saada määrätty osani ravinnosta.","Väärä oppi ja valhe olkoon minusta kaukana: köyhyyttä ja rikkautta älä minulle anna; vaan anna minun saada määrätty osani ravinnosta."],[30,9,"Etten minä, jos minä ylen ravituksi tulisin, kieltäisi sinua ja sanoisi: kuka on Herra? eli, jos minä ylen köyhäksi tulisin, varastaisi, ja syntiä tekisi Jumalani nimeä vastaan.","Etten minä, jos minä ylen ravituksi tulisin, kieltäisi sinua ja sanoisi: kuka on Herra? eli, jos minä ylen köyhäksi tulisin, varastaisi, ja syntiä tekisi Jumalani nimeä vastaan."],[30,10,"Älä kanna palvelian päälle hänen isäntänsä edessä, ettei hän sinua kiroilisi ja sinä niin nuhteeseen tulet.","Älä kanna palvelian päälle hänen isäntänsä edessä, ettei hän sinua kiroilisi ja sinä niin nuhteeseen tulet."],[30,11,"On niitä, jotka kiroilevat isäänsä ja ei siunaa äitiänsä.","On niitä, jotka kiroilevat isäänsä ja ei siunaa äitiänsä."],[30,12,"On niitäkin, jotka luulevat itsensä puhtaaksi, ja ei ole kuitenkaan saastaisuudestansa pestyt.","On niitäkin, jotka luulevat itsensä puhtaaksi, ja ei ole kuitenkaan saastaisuudestansa pestyt."],[30,13,"Ovat myös, jotka silmänsä nostavat, ja silmälautansa korottavat;","Ovat myös, jotka silmänsä nostavat, ja silmälautansa korottavat;"],[30,14,"Ja ovat, joilla on miekka hammasten siassa, ja veitset heidän syömähampainansa, ja syövät vaivaiset maan päältä, ja köyhät ihmisten seasta.","Ja ovat, joilla on miekka hammasten siassa, ja veitset heidän syömähampainansa, ja syövät vaivaiset maan päältä, ja köyhät ihmisten seasta."],[30,15,"Verenimijällä on kaksi tytärtä: tuo tänne, tuo tänne. Kolme on tyytymätöintä, ja tosin neljä ei sano kyllä olevan:","Verenimijällä on kaksi tytärtä: tuo tänne, tuo tänne. Kolme on tyytymätöintä, ja tosin neljä ei sano kyllä olevan:"],[30,16,"Helvetti, vaimon suljettu kohtu, maa, joka ei vedellä täytetä: ja tuli ei sano: jo kyllä on.","Helvetti, vaimon suljettu kohtu, maa, joka ei vedellä täytetä: ja tuli ei sano: jo kyllä on."],[30,17,"Silmä joka häpäisee isäänsä, ja katsoo ylön totella äitiänsä, sen kaarneet ojan tykönä hakkaavat ulos, ja kotkan pojat syövät.","Silmä joka häpäisee isäänsä, ja katsoo ylön totella äitiänsä, sen kaarneet ojan tykönä hakkaavat ulos, ja kotkan pojat syövät."],[30,18,"Kolme minulle ovat ihmeelliset, ja neljää en minä tiedä:","Kolme minulle ovat ihmeelliset, ja neljää en minä tiedä:"],[30,19,"Kotkan tiet taivaan alla, käärmeen retket kalliolla, haahden jäljet meren keskellä, ja miehen jäljet piian tykö.","Kotkan tiet taivaan alla, käärmeen retket kalliolla, haahden jäljet meren keskellä, ja miehen jäljet piian tykö."],[30,20,"Niin on myös porton polut: hän syö ja pyyhkii suunsa, ja sanoo: en minä mitään pahaa ole tehnyt.","Niin on myös porton polut: hän syö ja pyyhkii suunsa, ja sanoo: en minä mitään pahaa ole tehnyt."],[30,21,"Kolmen kautta maakunta tulee levottomuuteen, ja tosin neljää hän ei voi kärsiä:","Kolmen kautta maakunta tulee levottomuuteen, ja tosin neljää hän ei voi kärsiä:"],[30,22,"Kuin palvelia rupee hallitsemaan, kuin hullu ylen ravituksi tulee,","Kuin palvelia rupee hallitsemaan, kuin hullu ylen ravituksi tulee,"],[30,23,"Kuin ilkiä naitetaan, ja kuin piika tulee emäntänsä perilliseksi.","Kuin ilkiä naitetaan, ja kuin piika tulee emäntänsä perilliseksi."],[30,24,"Neljä on pientä maan päällä, ja ovat toimellisemmat viisaita.","Neljä on pientä maan päällä, ja ovat toimellisemmat viisaita."],[30,25,"Myyriäiset, heikko väki, jotka kuitenkin elatuksensa suvella toimittavat;","Myyriäiset, heikko väki, jotka kuitenkin elatuksensa suvella toimittavat;"],[30,26,"Kaninit, heikko väki, jotka kuitenkin pesänsä kalliolle tekevät;","Kaninit, heikko väki, jotka kuitenkin pesänsä kalliolle tekevät;"],[30,27,"Heinäsirkoilla ei ole kuningasta, kuitenkin he lähtevät kaikki ylös joukossansa;","Heinäsirkoilla ei ole kuningasta, kuitenkin he lähtevät kaikki ylös joukossansa;"],[30,28,"Hämähäkki kehrää käsillänsä, ja on kuninkaan linnoissa.","Hämähäkki kehrää käsillänsä, ja on kuninkaan linnoissa."],[30,29,"Kolmella on jalo käyntö, ja tosin neljä astuu hyvin:","Kolmella on jalo käyntö, ja tosin neljä astuu hyvin:"],[30,30,"Jalopeura, voimallinen petoin seassa, joka ei palaja kenenkään edestä;","Jalopeura, voimallinen petoin seassa, joka ei palaja kenenkään edestä;"],[30,31,"Hurtta, jolla vahvat sivut ovat, ja kauris, ja kuningas, jota vastaan ei kenkään tohdi.","Hurtta, jolla vahvat sivut ovat, ja kauris, ja kuningas, jota vastaan ei kenkään tohdi."],[30,32,"Jos sinä olet tyhmästi tehnyt, ja korottanut sinuas, ja jos sinä olet jotakin pahaa ajatellut, niin laske käsi suus päälle.","Jos sinä olet tyhmästi tehnyt, ja korottanut sinuas, ja jos sinä olet jotakin pahaa ajatellut, niin laske käsi suus päälle."],[30,33,"Joka rieskaa kirnuu, hän tekee voita: ja jokaa nenää pusertaa, hän vaatii ulos veren: ja joka vihaa kehoittaa, hän vaatii riitaan.","Joka rieskaa kirnuu, hän tekee voita: ja jokaa nenää pusertaa, hän vaatii ulos veren: ja joka vihaa kehoittaa, hän vaatii riitaan."],[31,1,"Kuningas Lemuelin sanat: oppi, jonka hänen äitinsä hänelle opetti:","Kuningas Lemuelin sanat: oppi, jonka hänen äitinsä hänelle opetti:"],[31,2,"Ah minun poikani, ah minun kohtuni poika, ah minun toivottu poikani!","Ah minun poikani, ah minun kohtuni poika, ah minun toivottu poikani!"],[31,3,"Älä anna vaimon saada tavaraas, ja älä käy niillä retkillä, joissa kuninkaat turmeltuvat.","Älä anna vaimon saada tavaraas, ja älä käy niillä retkillä, joissa kuninkaat turmeltuvat."],[31,4,"Ei kuningasten, o Lemuel, ei sovi kuningasten viinaa juoda, eli ruhtinasten väkeviä juotavia,","Ei kuningasten, o Lemuel, ei sovi kuningasten viinaa juoda, eli ruhtinasten väkeviä juotavia,"],[31,5,"Ettei he joisi, ja oikeutta unohtaisi, ja vääntelisi köyhäin asiaa.","Ettei he joisi, ja oikeutta unohtaisi, ja vääntelisi köyhäin asiaa."],[31,6,"Antakaat väkeviä juotavia niille, jotka hukkumallnsa ovat, ja viinaa murheellisille sieluille,","Antakaat väkeviä juotavia niille, jotka hukkumallnsa ovat, ja viinaa murheellisille sieluille,"],[31,7,"Että he joisivat, ja unohtaisivat ahdistuksensa, ja ei enää johdattaisi mieleensä viheliäisyyttänsä.","Että he joisivat, ja unohtaisivat ahdistuksensa, ja ei enää johdattaisi mieleensä viheliäisyyttänsä."],[31,8,"Avaa suus mykän edessä, ja auta hyljättyin asiaa.","Avaa suus mykän edessä, ja auta hyljättyin asiaa."],[31,9,"Avaa suus, ja tuomitse oikein, ja pelasta vaivainen ja köyhä.","Avaa suus, ja tuomitse oikein, ja pelasta vaivainen ja köyhä."],[31,10,"Joka toimellisen vaimon löytää, se on kalliimpi kuin kaikkein kallimmat päärlyt:","Joka toimellisen vaimon löytää, se on kalliimpi kuin kaikkein kallimmat päärlyt:"],[31,11,"Hänen miehensä sydän uskaltaa häneen: hänen elatuksensa ei puutu häneltä.","Hänen miehensä sydän uskaltaa häneen: hänen elatuksensa ei puutu häneltä."],[31,12,"Hän tekee hänelle hyvää ja ei pahaa kaikkena elinaikanansa.","Hän tekee hänelle hyvää ja ei pahaa kaikkena elinaikanansa."],[31,13,"Hän harjoittaa itsensä villoissa ja pellavissa, ja tekee mielellänsä työtä käsillänsä.","Hän harjoittaa itsensä villoissa ja pellavissa, ja tekee mielellänsä työtä käsillänsä."],[31,14,"Hän on niinkuin kauppamiehen haaksi, joka elatuksensa tuo kaukaa.","Hän on niinkuin kauppamiehen haaksi, joka elatuksensa tuo kaukaa."],[31,15,"Hän nousee yöllä, ja antaa perheellensä ruokaa, ja piioillensa heidän osansa.","Hän nousee yöllä, ja antaa perheellensä ruokaa, ja piioillensa heidän osansa."],[31,16,"Hän pyytää peltoa ja saa sen, ja istutaa viinapuita kättensä hedelmästä.","Hän pyytää peltoa ja saa sen, ja istutaa viinapuita kättensä hedelmästä."],[31,17,"Hän vyöttää kupeensa väkevydellä, ja vahvistaa käsivartensa.","Hän vyöttää kupeensa väkevydellä, ja vahvistaa käsivartensa."],[31,18,"Hän näkee askareensa hyödylliseksi: hänen kynttiläänsä ei sammuteta yöllä.","Hän näkee askareensa hyödylliseksi: hänen kynttiläänsä ei sammuteta yöllä."],[31,19,"Hän ojentaa kätensä rukkiin, ja tarttuu sormillansa kehrävarteen.","Hän ojentaa kätensä rukkiin, ja tarttuu sormillansa kehrävarteen."],[31,20,"Hän kohottaa kätensä köyhille, ja ojentaa kätensä tarvitseville.","Hän kohottaa kätensä köyhille, ja ojentaa kätensä tarvitseville."],[31,21,"Ei hän pelkää lunta huoneessansa; sillä kaikella hänen perheellänsä ovat kaksinkertaiset vaatteet.","Ei hän pelkää lunta huoneessansa; sillä kaikella hänen perheellänsä ovat kaksinkertaiset vaatteet."],[31,22,"Hän tekee itsellensä makausvaatteita: valkia kallis liina ja purppura ovat hänen pukunsa.","Hän tekee itsellensä makausvaatteita: valkia kallis liina ja purppura ovat hänen pukunsa."],[31,23,"Hänen miehensä on tuttu porteissa, istuissansa maan vanhimpain tykönä.","Hänen miehensä on tuttu porteissa, istuissansa maan vanhimpain tykönä."],[31,24,"Hän tekee kallista liinaa ja myy sitä, ja antaa vyön kauppaajalle.","Hän tekee kallista liinaa ja myy sitä, ja antaa vyön kauppaajalle."],[31,25,"Väkevyys ja kunnia on hänen pukunsa, ja hän nauraa seuraavaiselle ajalle.","Väkevyys ja kunnia on hänen pukunsa, ja hän nauraa seuraavaiselle ajalle."],[31,26,"Hän avaa suunsa viisaudessa, ja hänen kielensä on suloinen oppi.","Hän avaa suunsa viisaudessa, ja hänen kielensä on suloinen oppi."],[31,27,"Hän katselee kurkistellen, kuinka hänen huoneessansa kaikki asiat ovat, ja ei syö laiskuudessa leipäänsä.","Hän katselee kurkistellen, kuinka hänen huoneessansa kaikki asiat ovat, ja ei syö laiskuudessa leipäänsä."],[31,28,"Hänen poikansa tulevat ja ylistävät häntä autuaaksi: hänen miehensä kiittää häntä sanoen:","Hänen poikansa tulevat ja ylistävät häntä autuaaksi: hänen miehensä kiittää häntä sanoen:"],[31,29,"Moni tytär käyttää itsensä kauniisti; mutta sinä käyt ylitse heidän kaikkein.","Moni tytär käyttää itsensä kauniisti; mutta sinä käyt ylitse heidän kaikkein."],[31,30,"Otollinen olla on petollisuus, ihana olla on turha; vaan vaimo, joka Herraa pelkää, ylistetään.","Otollinen olla on petollisuus, ihana olla on turha; vaan vaimo, joka Herraa pelkää, ylistetään."],[31,31,"Antakaat hänelle kättensä hedelmästä, ja hänen kättensä työt kiittäkään häntä porteissa.","Antakaat hänelle kättensä hedelmästä, ja hänen kättensä työt kiittäkään häntä porteissa."]]}};